css:
.dbe-live {
  width: 100%;
  height: var(--dbe-live-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-live-line);
  border-radius: 14px;
  background: var(--dbe-live-bg);
  color: var(--dbe-live-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-live-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-live-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-live-num { font-variant-numeric: tabular-nums; }
  & .dbe-live-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-live-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-live-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-live-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-live-line-2) transparent; }
  & .dbe-live-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  & .dbe-live-scroll::-webkit-scrollbar-thumb { background: var(--dbe-live-line-2); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  & .dbe-live-scroll::-webkit-scrollbar-track { background: transparent; }
}

@keyframes dbe-live-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbe-live-flash { from { background-color: color-mix(in oklch, var(--dbe-live-accent) 26%, transparent); } }
@keyframes dbe-live-beat { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(0.72); opacity: 0.55; } }
@keyframes dbe-live-cell { from { opacity: 0; transform: scale(0.4); } }
@keyframes dbe-live-grow { from { transform: scaleX(0); } }

.dbe-live {
  /* re-theme with these four */
  --dbe-live-bg: oklch(0.185 0.012 55);
  --dbe-live-ink: oklch(0.95 0.018 80);
  --dbe-live-accent: oklch(0.77 0.135 62);
  --dbe-live-up: oklch(0.8 0.13 150);
  /* channels */
  --dbe-live-c-web: var(--dbe-live-accent);
  --dbe-live-c-app: oklch(0.82 0.1 118);
  --dbe-live-c-sub: oklch(0.74 0.12 22);
  --dbe-live-c-whl: oklch(0.86 0.045 85);
  /* derived */
  --dbe-live-down: oklch(0.7 0.16 28);
  --dbe-live-sunk: color-mix(in oklch, var(--dbe-live-bg), black 22%);
  --dbe-live-panel: color-mix(in oklch, var(--dbe-live-bg), var(--dbe-live-ink) 4.5%);
  --dbe-live-raise: color-mix(in oklch, var(--dbe-live-bg), var(--dbe-live-ink) 9%);
  --dbe-live-line: color-mix(in oklch, var(--dbe-live-ink) 10%, transparent);
  --dbe-live-line-2: color-mix(in oklch, var(--dbe-live-ink) 20%, transparent);
  --dbe-live-muted: color-mix(in oklch, var(--dbe-live-ink) 62%, var(--dbe-live-bg));
  --dbe-live-faint: color-mix(in oklch, var(--dbe-live-ink) 38%, var(--dbe-live-bg));
  --dbe-live-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbe-live-spring: linear(0, 0.012, 0.047 2.3%, 0.18 4.9%, 0.74 13.5%, 0.94 17.6%, 1.03 21.4%, 1.07 26%, 1.07 30.4%, 1.02 40%, 0.996 50%, 1);

  .dbe-live-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbe-live-muted); }

  /* ---------- shell ---------- */
  .dbe-live-app {
    display: grid;
    height: 100%;
    grid-template-columns: 72px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "rail top" "rail main";
  }
  .dbe-live-rail {
    grid-area: rail;
    display: flex; flex-direction: column; align-items: center; gap: 22px;
    padding: 16px 0 14px;
    background: var(--dbe-live-sunk);
    border-right: 1px solid var(--dbe-live-line);
  }
  .dbe-live-mark svg {
    width: 36px; height: 36px; padding: 7px; border-radius: 11px;
    background: var(--dbe-live-accent); color: var(--dbe-live-bg);
    fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round;
  }
  .dbe-live-nav { display: grid; gap: 6px; }
  .dbe-live-tab {
    position: relative;
    display: grid; justify-items: center; gap: 3px;
    width: 56px; padding: 8px 0 7px; border-radius: 10px;
    color: var(--dbe-live-muted);
    font-size: 10.5px; font-weight: 600; letter-spacing: 0.02em;
    transition: color 160ms var(--dbe-live-ease), background-color 160ms var(--dbe-live-ease);
    &:hover { color: var(--dbe-live-ink); background: color-mix(in oklch, var(--dbe-live-ink) 6%, transparent); }
    &[aria-selected="true"] { color: var(--dbe-live-ink); background: var(--dbe-live-raise); }
    &[aria-selected="true"]::before {
      content: ""; position: absolute; left: -8px; top: 10px; bottom: 10px; width: 3px; border-radius: 3px;
      background: var(--dbe-live-accent);
    }
    &[aria-selected="true"] .dbe-live-ico { color: var(--dbe-live-accent); }
  }
  .dbe-live-status {
    margin-top: auto;
    display: grid; justify-items: center; gap: 4px;
    font-size: 10px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbe-live-up);
    & i { width: 8px; height: 8px; border-radius: 50%; background: currentColor; box-shadow: 0 0 0 4px color-mix(in oklch, currentColor 18%, transparent); animation: dbe-live-beat 2.4s ease-in-out infinite; }
  }

  .dbe-live-top {
    grid-area: top;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "title clock" "tools tools";
    align-items: end;
    gap: 10px 16px;
    padding: 16px 20px 12px;
    border-bottom: 1px solid var(--dbe-live-line);
  }
  .dbe-live-title { grid-area: title; display: grid; gap: 2px; min-width: 0; }
  .dbe-live-h { font-size: clamp(20px, 0.9rem + 1.1cqi, 28px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.05; }
  .dbe-live-clock { grid-area: clock; display: grid; justify-items: end; line-height: 1.1; }
  .dbe-live-date { font-size: 11.5px; color: var(--dbe-live-muted); }
  .dbe-live-time { font-size: clamp(18px, 0.8rem + 1cqi, 24px); font-weight: 600; letter-spacing: -0.02em; }
  .dbe-live-tools { grid-area: tools; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: space-between; }
  .dbe-live-chips { display: flex; gap: 6px; flex-wrap: wrap; }
  .dbe-live-chip {
    display: inline-flex; align-items: center; gap: 7px;
    height: 28px; padding: 0 11px 0 9px; border-radius: 99px;
    border: 1px solid var(--dbe-live-line-2);
    color: var(--dbe-live-muted); font-size: 12px; font-weight: 560;
    transition: background-color 180ms var(--dbe-live-ease), color 180ms var(--dbe-live-ease), border-color 180ms var(--dbe-live-ease);
    & i { width: 8px; height: 8px; border-radius: 50%; border: 1.5px solid var(--c); transition: background-color 180ms var(--dbe-live-ease), transform 260ms var(--dbe-live-spring); }
    &:hover { color: var(--dbe-live-ink); border-color: color-mix(in oklch, var(--c) 60%, transparent); }
    &[aria-pressed="true"] { color: var(--dbe-live-ink); background: color-mix(in oklch, var(--c) 14%, transparent); border-color: color-mix(in oklch, var(--c) 45%, transparent); }
    &[aria-pressed="true"] i { background: var(--c); transform: scale(1.1); }
  }
  .dbe-live-pause {
    display: inline-flex; align-items: center; gap: 7px;
    height: 30px; padding: 0 12px 0 10px; border-radius: 8px;
    background: var(--dbe-live-raise); font-size: 12px; font-weight: 600;
    transition: background-color 160ms var(--dbe-live-ease);
    &:hover { background: color-mix(in oklch, var(--dbe-live-raise), var(--dbe-live-ink) 6%); }
    & .dbe-live-p2 { display: none; fill: currentColor; stroke: none; }
    &[aria-pressed="true"] { background: color-mix(in oklch, var(--dbe-live-accent) 22%, var(--dbe-live-panel)); }
    &[aria-pressed="true"] .dbe-live-p1 { display: none; }
    &[aria-pressed="true"] .dbe-live-p2 { display: block; }
  }
  .dbe-live-queued { font-style: normal; font-size: 11px; padding: 1px 7px; border-radius: 99px; background: var(--dbe-live-accent); color: var(--dbe-live-bg); font-variant-numeric: tabular-nums; }

  .dbe-live-main { grid-area: main; min-height: 0; padding: 14px 20px 18px; }
  .dbe-live-view { height: 100%; display: grid; gap: 14px; grid-template-rows: auto minmax(0, 1fr); animation: dbe-live-rise 420ms var(--dbe-live-ease) both; }
  .dbe-live-v-hours { grid-template-rows: auto minmax(0, 1fr) auto; }

  /* ---------- KPIs ---------- */
  .dbe-live-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--dbe-live-line); border: 1px solid var(--dbe-live-line); }
  .dbe-live-kpi {
    display: grid; gap: 3px; align-content: start;
    padding: 11px 14px 12px;
    background: var(--dbe-live-panel);
    animation: dbe-live-rise 520ms var(--dbe-live-ease) both;
    animation-delay: calc(var(--i) * 55ms);
    & output { font-size: clamp(19px, 0.8rem + 1.15cqi, 27px); font-weight: 680; letter-spacing: -0.03em; line-height: 1.1; white-space: nowrap; }
    & small { font-size: 11.5px; color: var(--dbe-live-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small b { font-weight: 650; }
    & .dbe-live-u { color: var(--dbe-live-up); }
    & .dbe-live-d { color: var(--dbe-live-down); }
  }
  .dbe-live-kpi-proj { background: color-mix(in oklch, var(--dbe-live-accent) 10%, var(--dbe-live-panel)); }
  .dbe-live-kpi-proj output { color: var(--dbe-live-accent); }

  /* ---------- cards ---------- */
  .dbe-live-split { display: grid; grid-template-columns: minmax(0, 1fr) clamp(280px, 30cqi, 340px); gap: 14px; min-height: 0; }
  .dbe-live-card { margin: 0; min-height: 0; border-radius: 12px; background: var(--dbe-live-panel); border: 1px solid var(--dbe-live-line); }
  .dbe-live-cardhead { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; padding: 11px 14px 0; }
  .dbe-live-cardhead h3 { font-size: 13px; font-weight: 650; letter-spacing: -0.005em; }
  .dbe-live-legend { display: flex; gap: 14px; font-size: 11.5px; color: var(--dbe-live-muted); flex-wrap: wrap; }
  .dbe-live-legend li { display: inline-flex; align-items: center; gap: 6px; }
  .dbe-live-legend i { width: 14px; height: 0; border-top: 2px solid; }
  .dbe-live-sw-today { border-color: var(--dbe-live-accent) !important; }
  .dbe-live-sw-lw { border-top-style: dashed !important; border-color: var(--dbe-live-faint) !important; }
  .dbe-live-sw-tgt { border-top-style: dotted !important; border-color: var(--dbe-live-up) !important; }

  .dbe-live-pace { display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbe-live-plot { position: relative; min-height: 0; }
  .dbe-live-cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: crosshair; touch-action: pan-y; }

  .dbe-live-tip {
    position: absolute; left: 0; top: 0; z-index: 5; pointer-events: none;
    min-width: 168px; padding: 9px 11px; border-radius: 9px;
    background: color-mix(in oklch, var(--dbe-live-sunk) 92%, transparent);
    border: 1px solid var(--dbe-live-line-2);
    box-shadow: 0 12px 28px -8px oklch(0 0 0 / 0.55);
    backdrop-filter: blur(6px);
    font-size: 12px; font-variant-numeric: tabular-nums;
    & b { display: block; font-size: 11px; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbe-live-muted); margin-bottom: 4px; }
    & p { display: flex; justify-content: space-between; gap: 14px; }
    & p span { display: inline-flex; align-items: center; gap: 6px; color: var(--dbe-live-muted); }
    & p i { width: 7px; height: 7px; border-radius: 2px; background: var(--c); }
    & p em { font-style: normal; font-weight: 620; }
  }

  /* ---------- ticker ---------- */
  .dbe-live-ticker { display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbe-live-rate { font-size: 11.5px; color: var(--dbe-live-muted); }
  .dbe-live-rate b { color: var(--dbe-live-ink); font-weight: 650; }
  .dbe-live-list { min-height: 0; padding: 8px 6px 8px; }
  .dbe-live-list li {
    display: grid; grid-template-rows: 1fr;
    transition: grid-template-rows 460ms var(--dbe-live-ease), opacity 360ms var(--dbe-live-ease);
    transition-delay: calc(var(--i, 0) * 28ms);
    @starting-style { grid-template-rows: 0fr; opacity: 0; }
  }
  .dbe-live-row {
    min-height: 0; overflow: hidden;
    display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; align-items: center; gap: 10px;
    width: 100%; padding: 7px 8px; border-radius: 8px;
    transition: background-color 140ms var(--dbe-live-ease);
    &:hover, &.is-hot { background: var(--dbe-live-raise); }
    &.is-new { animation: dbe-live-flash 1.4s var(--dbe-live-ease); }
    &[aria-expanded="true"] { background: color-mix(in oklch, var(--dbe-live-accent) 16%, var(--dbe-live-panel)); }
  }
  .dbe-live-row-t { font-size: 11.5px; color: var(--dbe-live-muted); }
  .dbe-live-row-who { display: grid; min-width: 0; line-height: 1.25; }
  .dbe-live-row-who b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbe-live-row-who small { font-size: 11px; color: var(--dbe-live-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbe-live-row-who small i { display: inline-block; width: 6px; height: 6px; margin-right: 5px; border-radius: 50%; background: var(--c); vertical-align: 1px; }
  .dbe-live-row-amt { font-weight: 650; font-variant-numeric: tabular-nums; }

  /* ---------- views 2 + 3 ---------- */
  .dbe-live-viewhead { display: flex; align-items: flex-end; gap: 12px 14px; flex-wrap: wrap; }
  .dbe-live-viewhead > div:first-child { flex: 1 1 260px; display: grid; gap: 3px; }
  .dbe-live-viewhead h3 { font-size: clamp(15px, 0.7rem + 0.6cqi, 18px); font-weight: 680; letter-spacing: -0.02em; }
  .dbe-live-sub { font-size: 12px; color: var(--dbe-live-muted); max-width: 60ch; }
  .dbe-live-seg {
    display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbe-live-sunk); border: 1px solid var(--dbe-live-line);
    & button { height: 26px; padding: 0 11px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dbe-live-muted); transition: background-color 160ms var(--dbe-live-ease), color 160ms var(--dbe-live-ease); }
    & button:hover { color: var(--dbe-live-ink); }
    & button[aria-checked="true"] { background: var(--dbe-live-raise); color: var(--dbe-live-ink); box-shadow: inset 0 0 0 1px var(--dbe-live-line-2); }
  }

  .dbe-live-heatcard { position: relative; padding: 12px 14px 12px 10px; overflow: auto; }
  .dbe-live-heat {
    display: grid;
    grid-template-columns: 62px repeat(24, minmax(14px, 1fr)) 64px;
    grid-template-rows: auto auto;
    grid-auto-rows: minmax(14px, 1fr);
    gap: 3px;
    height: 100%;
    max-height: calc(var(--n, 7) * 40px + 66px);
    min-width: 560px;
    font-size: 10.5px; font-variant-numeric: tabular-nums;
  }
  .dbe-live-hrow { display: contents; }
  .dbe-live-hlab { align-self: center; color: var(--dbe-live-muted); white-space: nowrap; }
  .dbe-live-hlab b { color: var(--dbe-live-ink); font-weight: 600; }
  .dbe-live-htot { align-self: center; text-align: right; color: var(--dbe-live-muted); }
  .dbe-live-hhead { color: var(--dbe-live-faint); text-align: center; align-self: end; padding-bottom: 2px; }
  .dbe-live-hbar { height: 34px; display: flex; align-items: flex-end; }
  .dbe-live-hbar i { display: block; width: 100%; height: calc(var(--h) * 100%); border-radius: 2px 2px 0 0; background: color-mix(in oklch, var(--dbe-live-accent) 50%, var(--dbe-live-panel)); transform-origin: bottom; transition: height 420ms var(--dbe-live-ease); }
  .dbe-live-cell {
    min-height: 14px; border-radius: 3px;
    background: color-mix(in oklch, var(--dbe-live-accent) calc(var(--t) * 100%), var(--dbe-live-sunk));
    transition: background-color 300ms var(--dbe-live-ease), box-shadow 120ms;
    &[data-empty] { background: repeating-linear-gradient(135deg, var(--dbe-live-line) 0 2px, transparent 2px 5px); }
    &:hover, &:focus-visible { box-shadow: 0 0 0 2px var(--dbe-live-ink); outline: none; position: relative; z-index: 1; }
    &.is-now { box-shadow: inset 0 0 0 1.5px var(--dbe-live-ink); }
  }
  .dbe-live-heat.is-enter .dbe-live-cell { animation: dbe-live-cell 520ms var(--dbe-live-spring) both; animation-delay: calc(var(--c) * 16ms + var(--r) * 22ms); }
  .dbe-live-heatnote { font-size: 12px; color: var(--dbe-live-muted); }
  .dbe-live-heatnote b { color: var(--dbe-live-ink); font-weight: 650; }

  .dbe-live-itemcard { position: relative; display: grid; grid-template-rows: minmax(0, 1fr); min-height: 0; overflow: hidden; }
  .dbe-live-items { padding: 8px 6px; min-height: 0; }
  .dbe-live-item {
    display: grid; grid-template-columns: 26px minmax(0, 1.2fr) minmax(80px, 1fr) 56px 82px; align-items: center; gap: 12px;
    padding: 8px 10px; border-radius: 8px;
    &:hover { background: var(--dbe-live-raise); }
  }
  .dbe-live-item-rank { color: var(--dbe-live-faint); font-variant-numeric: tabular-nums; font-weight: 600; text-align: right; }
  .dbe-live-item-name { display: grid; min-width: 0; line-height: 1.25; }
  .dbe-live-item-name b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbe-live-item-name small { font-size: 11px; color: var(--dbe-live-muted); }
  .dbe-live-item-bar { height: 8px; border-radius: 4px; background: var(--dbe-live-sunk); overflow: hidden; }
  .dbe-live-item-bar i { display: flex; gap: 1px; height: 100%; width: 100%; border-radius: inherit; overflow: hidden; transform-origin: left; transform: scaleX(var(--s)); transition: transform 600ms var(--dbe-live-ease); }
  .dbe-live-item-bar b { height: 100%; flex: 0 0 auto; background: var(--c); transition: width 600ms var(--dbe-live-ease); }
  .dbe-live-items.is-enter .dbe-live-item-bar i { animation: dbe-live-grow 700ms var(--dbe-live-ease) both; animation-delay: calc(var(--i) * 40ms); }
  .dbe-live-item-q, .dbe-live-item-c { text-align: right; font-variant-numeric: tabular-nums; }
  .dbe-live-item-q { color: var(--dbe-live-muted); }
  .dbe-live-item-c { font-weight: 650; }

  /* ---------- drawer ---------- */
  .dbe-live-drawer {
    position: absolute; z-index: 20; top: 10px; right: 10px; bottom: 10px;
    width: min(360px, calc(100% - 20px));
    display: grid; grid-template-rows: auto minmax(0, 1fr);
    border-radius: 14px;
    background: var(--dbe-live-raise);
    border: 1px solid var(--dbe-live-line-2);
    box-shadow: 0 24px 60px -18px oklch(0 0 0 / 0.7);
    transform: translateX(calc(100% + 24px));
    opacity: 0;
    transition: transform 420ms var(--dbe-live-ease), opacity 260ms var(--dbe-live-ease);
    &.is-open { transform: none; opacity: 1; }
  }
  .dbe-live-dhead { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; padding: 14px 14px 10px 16px; border-bottom: 1px solid var(--dbe-live-line); }
  .dbe-live-dhead h3 { font-size: 17px; font-weight: 650; letter-spacing: -0.01em; margin-top: 2px; }
  .dbe-live-x { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; color: var(--dbe-live-muted); &:hover { background: var(--dbe-live-panel); color: var(--dbe-live-ink); } }
  .dbe-live-dbody { padding: 14px 16px 16px; display: grid; gap: 14px; align-content: start; }
  .dbe-live-who { display: grid; gap: 2px; }
  .dbe-live-who b { font-size: 14px; font-weight: 650; }
