/* ---------- helpers (scoped to this component) ---------- */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const calm = () => RM.matches;
const uid = p => 'dbe-live-' + p + '-' + Math.random().toString(36).slice(2, 8);
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;
const easeOut = t => 1 - Math.pow(1 - t, 3);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function rng(seed) {
  let a = seed | 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/* round an axis maximum up to 1/2/2.5/5 x 10^n */
function nice(max, n = 4) {
  if (!(max > 0)) return { step: 1, top: n };
  const raw = max / n, mag = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / mag;
  const step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * mag;
  return { step, top: Math.ceil(max / step - 1e-9) * step };
}
/* one rAF tween; returns a cancel function */
function tween(ms, fn, done) {
  if (calm() || ms <= 0) { fn(1); if (done) done(); return () => {}; }
  let dead = false;
  const t0 = performance.now();
  const step = now => {
    if (!root.isConnected) return;
    if (dead) return;
    const t = Math.min(1, (now - t0) / ms);
    fn(easeOut(t));
    if (t < 1) requestAnimationFrame(step); else if (done) done();
  };
  requestAnimationFrame(step);
  return () => { dead = true; };
}
/* roving focus for radio groups, tab lists and toolbars: arrows move, Home/End jump */
function roving(group, sel, attr, onPick) {
  const items = () => $$(sel, group);
  const pick = (b, focus) => {
    items().forEach(x => {
      const on = x === b;
      if (attr === 'aria-current') { if (on) x.setAttribute(attr, 'page'); else x.removeAttribute(attr); }
      else x.setAttribute(attr, String(on));
      x.tabIndex = on ? 0 : -1;
    });
    if (focus) b.focus();
    onPick(b.dataset.v, b);
  };
  items().forEach(x => { const on = attr === 'aria-current' ? x.hasAttribute(attr) : x.getAttribute(attr) === 'true'; x.tabIndex = on ? 0 : -1; });
  group.addEventListener('click', e => { const b = e.target.closest(sel); if (b && group.contains(b)) pick(b); });
  group.addEventListener('keydown', e => {
    const list = items(), i = list.indexOf(e.target.closest(sel));
    if (i < 0) return;
    const d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
    let j = -1;
    if (d) j = (i + d + list.length) % list.length;
    else if (e.key === 'Home') j = 0;
    else if (e.key === 'End') j = list.length - 1;
    if (j >= 0) { e.preventDefault(); pick(list[j], true); }
  });
  return { set: v => { const b = items().find(x => x.dataset.v === v); if (b) pick(b); } };
}
/* place an absolutely positioned tooltip inside its host, flipping at the edges */
function placeTip(tip, host, x, y) {
  tip.hidden = false;
  const hw = host.clientWidth, hh = host.clientHeight, tw = tip.offsetWidth, th = tip.offsetHeight;
  let l = x + 14, t = y - th - 12;
  if (l + tw > hw - 6) l = x - tw - 14;
  if (l < 6) l = Math.max(6, Math.min(hw - tw - 6, x - tw / 2));
  if (t < 6) t = Math.min(hh - th - 6, y + 18);
  tip.style.transform = `translate(${Math.round(l)}px, ${Math.round(t)}px)`;
}
/* is the component on screen and the tab visible? loops sleep otherwise */
let onScreen = true;
const wakers = [];
const awake = () => onScreen && !document.hidden && root.isConnected;
new IntersectionObserver(es => {
  onScreen = es[es.length - 1].isIntersecting;
  if (onScreen) wakers.forEach(f => f());
}).observe(root);

/* resolve a theme token (or any CSS colour) to an rgba() string the canvas can use:
   custom properties hold unresolved color-mix() text, so a hidden probe computes it
   and a 1x1 canvas normalises whatever colour space the browser reports */
const probe = document.createElement('i');
probe.hidden = true;
root.appendChild(probe);
const px1 = document.createElement('canvas');
px1.width = px1.height = 1;
const pxc = px1.getContext('2d', { willReadFrequently: true });
const rgbCache = new Map();
function col(v, alpha = 1) {
  probe.style.color = v.startsWith('--') ? `var(${v})` : v;
  const c = getComputedStyle(probe).color;
  let rgb = rgbCache.get(c);
  if (!rgb) {
    pxc.clearRect(0, 0, 1, 1);
    pxc.fillStyle = '#000';
    pxc.fillStyle = c;
    pxc.fillRect(0, 0, 1, 1);
    const d = pxc.getImageData(0, 0, 1, 1).data;
    rgb = [d[0], d[1], d[2], d[3] / 255];
    rgbCache.set(c, rgb);
  }
  return `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${+(alpha * rgb[3]).toFixed(3)})`;
}
/* size a canvas to its box at devicePixelRatio (capped at 2); returns css size */
function fitCanvas(cv) {
  const r = cv.getBoundingClientRect(), dpr = Math.min(2, window.devicePixelRatio || 1);
  const w = Math.max(1, Math.round(r.width)), h = Math.max(1, Math.round(r.height));
  if (cv.width !== Math.round(w * dpr) || cv.height !== Math.round(h * dpr)) {
    cv.width = Math.round(w * dpr);
    cv.height = Math.round(h * dpr);
  }
  const g = cv.getContext('2d');
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { w, h, g };
}

/* ---------- catalogue (prices in cents) ---------- */
const CHS = ['web', 'app', 'sub', 'whl'];
const CHN = { web: 'Web store', app: 'Mobile app', sub: 'Subscription', whl: 'Trade account' };
const P = [
  { n: 'Halcyon Espresso Blend', v: '1 kg whole bean', p: 3400, w: 9 },
  { n: 'Halcyon Espresso Blend', v: '340 g whole bean', p: 1650, w: 16 },
  { n: 'Kiboko Washed', v: '340 g · Kenya', p: 2100, w: 10 },
  { n: 'Finca Lirio Natural', v: '340 g · Colombia', p: 1950, w: 9 },
  { n: 'Night Owl Decaf', v: '340 g · Swiss water', p: 1700, w: 6 },
  { n: 'Cold Brew Coarse', v: '1 kg ground', p: 2900, w: 5 },
  { n: 'Burr Grinder Q2', v: 'Matte stone', p: 18900, w: 1.1 },
  { n: 'Gooseneck Kettle', v: '0.9 L · brushed steel', p: 7200, w: 1.8 },
  { n: 'Ceramic Dripper No. 4', v: 'Ash glaze', p: 2800, w: 3 },
  { n: 'Paper Filters', v: 'Pack of 100', p: 750, w: 8 },
  { n: "Roaster's Choice", v: 'Monthly · 2 × 250 g', p: 2400, w: 0 },
  { n: 'Café Pack', v: '5 kg whole bean', p: 11800, w: 0 }
];
const SUBI = 10, TRADEI = 11, FILTERI = 9;
const WSUM = P.reduce((a, x) => a + x.w, 0);
const PEOPLE = ['Ines R.', 'Tomasz K.', 'Amara O.', 'Jules F.', 'Priya N.', 'Mateo G.', 'Hana S.', 'Callum B.', 'Noor A.', 'Wren T.', 'Elio D.', 'Saoirse M.', 'Kenji W.', 'Lucia P.', 'Bram V.', 'Odile C.', 'Rafi H.', 'Mina L.', 'Dario Q.', 'Yusuf E.', 'Greta J.', 'Ayo B.'];
const TRADE = ['Lantern & Loaf', 'Pocket Espresso Bar', 'Ferro Bakehouse', 'Quay Street Kitchen', 'Little Alder Café', 'Marrow Canteen'];
const CITIES = ['Portland, OR', 'Austin, TX', 'Brooklyn, NY', 'Denver, CO', 'Chicago, IL', 'Seattle, WA', 'Asheville, NC', 'Minneapolis, MN', 'Oakland, CA', 'Savannah, GA', 'Madison, WI', 'Tucson, AZ', 'Burlington, VT', 'Boise, ID', 'Richmond, VA', 'Providence, RI'];
/* orders per hour on an ordinary weekday, by hour of day */
const SHAPE = [15, 10, 7, 5, 5, 10, 25, 55, 85, 95, 82, 75, 90, 85, 72, 68, 65, 70, 82, 100, 105, 85, 55, 30];
const LMAX = 110;
const lam = t => {
  const h = t / 3600 - 0.5, i = Math.floor(h), f = h - i;
  return lerp(SHAPE[(i + 24) % 24], SHAPE[(i + 25) % 24], f);
};
const pickProduct = R => {
  let x = R() * WSUM;
  for (let i = 0; i < P.length; i++) { x -= P[i].w; if (x <= 0) return i; }
  return 0;
};
function makeOrder(R, t, seq) {
  const u = R();
  const ch = u < 0.5 ? 'web' : u < 0.75 ? 'app' : u < 0.92 ? 'sub' : 'whl';
  const lines = [];
  const add = (pi, q) => { const l = lines.find(x => x[0] === pi); if (l) l[1] += q; else lines.push([pi, q]); };
  if (ch === 'sub') { add(SUBI, 1); if (R() < 0.25) add(FILTERI, 1); }
  else if (ch === 'whl') add(TRADEI, 1 + Math.floor(R() * R() * 3));
  else {
    const k = 1 + Math.floor(Math.pow(R(), 1.9) * 4);
    for (let i = 0; i < k; i++) { const pi = pickProduct(R); add(pi, pi < 6 && R() < 0.2 ? 2 : 1); }
  }
  let sub = 0, units = 0;
  for (const [pi, q] of lines) { sub += q * P[pi].p; units += q; }
  const code = (ch === 'web' || ch === 'app') && R() < 0.1 ? 'FIRSTCUP' : '';
  const disc = code ? Math.round(sub * 0.15) : 0;
  const ship = ch === 'sub' ? 0 : ch === 'whl' ? 1400 : (sub - disc >= 4500 ? 0 : 595);
  const who = ch === 'whl' ? TRADE[Math.floor(R() * TRADE.length)] : PEOPLE[Math.floor(R() * PEOPLE.length)];
  const pay = ch === 'whl' ? 'Invoice · net 30' : ch === 'sub' ? 'Card on file' : R() < 0.46 ? 'Wallet' : 'Card';
  return { id: seq, t, ch, lines, sub, disc, ship, total: sub - disc + ship, units, who, city: CITIES[Math.floor(R() * CITIES.length)], code, pay };
}

/* ---------- 28 days of history + today up to the start of the stream ---------- */
const DAY = 86400, DAYS = 28, TODAY = Date.UTC(2026, 9, 2), START = 14 * 3600 + 32 * 60 + 10, SPEED = 20;
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const WDL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MO = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const dayDate = d => new Date(TODAY - (DAYS - 1 - d) * DAY * 1000);
const dayLabel = d => { const x = dayDate(d); return WD[x.getUTCDay()] + ' ' + x.getUTCDate() + ' ' + MO[x.getUTCMonth()]; };
const DOWF = [0.86, 1.0, 0.97, 1.0, 1.03, 1.08, 0.9];
const RD = rng(90210);
const factor = d => DOWF[dayDate(d).getUTCDay()] * (0.9 + 0.1 * d / (DAYS - 1)) * (0.95 + RD() * 0.1);
const HOUR = new Float64Array(DAYS * 24 * 4 * 2); // [day][hour][channel][orders, cents]
const hIdx = (d, h, c) => ((d * 24 + h) * 4 + c) * 2;
function tally(d, o) {
  const k = hIdx(d, Math.floor(o.t / 3600), CHS.indexOf(o.ch));
  HOUR[k] += 1; HOUR[k + 1] += o.total;
}
let seq = 51840;
function genDay(seed, f, until) {
  const R = rng(seed), out = [];
  const lmax = LMAX * f / 3600;
  let t = 0;
  for (;;) {
    t += -Math.log(1 - R()) / lmax;
    if (t >= until) break;
    if (R() * LMAX <= lam(t)) out.push(makeOrder(R, t, seq++));
  }
  return out;
}
const LWD = DAYS - 8; // same weekday last week
let lastWeek = [];
for (let d = 0; d < DAYS - 1; d++) {
  const os = genDay(1000 + d * 7919, factor(d), DAY);
  os.forEach(o => tally(d, o));
  if (d === LWD) lastWeek = os;
}
const TF = factor(DAYS - 1) * 1.06; // a payday Friday, running a little ahead of last week
const today = genDay(424242, TF, START);
today.forEach(o => tally(DAYS - 1, o));
/* the live stream continues with its own generator */
const RL = rng(31337);
const lmaxLive = LMAX * TF / 3600;
let simT = START, nextT = START;
function scheduleNext() {
  for (;;) {
    nextT += -Math.log(1 - RL()) / lmaxLive;
    if (nextT >= DAY || RL() * LMAX <= lam(nextT)) return;
  }
}
scheduleNext();

/* cumulative revenue at 5-minute steps for last week, per channel */
const STEPS = 288;
const lwCum = CHS.map(() => new Float64Array(STEPS + 1));
lastWeek.forEach(o => { const c = CHS.indexOf(o.ch), k = Math.min(STEPS, Math.ceil(o.t / 300)); lwCum[c][k] += o.total; });
lwCum.forEach(a => { for (let k = 1; k <= STEPS; k++) a[k] += a[k - 1]; });
const lwFullAll = CHS.reduce((s, _, c) => s + lwCum[c][STEPS], 0);
const TARGET = Math.round(lwFullAll * 1.06 / 50000) * 50000; // in cents, rounded to $500

/* ---------- formatting ---------- */
const nf0 = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const nf2 = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const usd = c => '$' + nf2.format(c / 100);
const usd0 = c => '$' + nf0.format(Math.round(c / 100));
const usdk = c => { const d = c / 100; return d >= 1000 ? '$' + (d / 1000).toFixed(d >= 100000 ? 0 : 1).replace(/\.0$/, '') + 'k' : '$' + nf0.format(d); };
const p2 = n => String(n).padStart(2, '0');
const hm = t => p2(Math.floor(t / 3600) % 24) + ':' + p2(Math.floor(t % 3600 / 60));
const hms = t => hm(t) + ':' + p2(Math.floor(t % 60));
const signed = x => (x >= 0 ? '+' : '−') + Math.abs(x * 100).toFixed(1) + '%';
const deltaHTML = (x, tail) => `<b class="${x >= 0 ? 'dbe-live-u' : 'dbe-live-d'}">${signed(x)}</b> ${tail}`;

/* ---------- state ---------- */
const st = { chans: new Set(CHS), paused: false, queued: [], view: 'live', metric: 'n', days: 7, rank: 'c', hoverX: null, markT: null, open: null, reveal: calm() ? 1 : 0 };
const on = o => st.chans.has(o.ch);
const chMask = () => CHS.map(c => st.chans.has(c));

$('.dbe-live-date').textContent = dayLabel(DAYS - 1);
$('.dbe-live-lwlabel').textContent = 'Last ' + WDL[dayDate(LWD).getUTCDay()];

/* ---------- aggregates ---------- */
let agg = null;
function lwAt(t, mask) {
  const k = t / 300, i = Math.floor(k), f = k - i;
  let s = 0;
  CHS.forEach((_, c) => { if (mask[c]) s += lerp(lwCum[c][Math.min(STEPS, i)], lwCum[c][Math.min(STEPS, i + 1)], f); });
  return s;
}
function recalc() {
  const mask = chMask();
  let rev = 0, ord = 0, units = 0;
  const cum = new Float64Array(STEPS + 1);
  for (const o of today) {
    if (!mask[CHS.indexOf(o.ch)]) continue;
    rev += o.total; ord++; units += o.units;
    cum[Math.min(STEPS, Math.ceil(o.t / 300))] += o.total;
  }
  for (let k = 1; k <= STEPS; k++) cum[k] += cum[k - 1];
  let lwRev = 0, lwOrd = 0, lwUnits = 0;
  for (const o of lastWeek) {
    if (o.t > simT || !mask[CHS.indexOf(o.ch)]) continue;
    lwRev += o.total; lwOrd++; lwUnits += o.units;
  }
  const lwFull = CHS.reduce((s, _, c) => s + (mask[c] ? lwCum[c][STEPS] : 0), 0);
  const share = lwFull / lwFullAll;
  const lwNow = lwAt(simT, mask);
  const ratio = lwNow > 0 ? rev / lwNow : 1;
  agg = { mask, rev, ord, units, cum, lwRev, lwOrd, lwUnits, lwFull, target: TARGET * share, ratio, proj: lwFull * ratio };
}

/* ---------- KPIs with rolling numbers ---------- */
const kpiEl = k => $(`[data-k="${k}"]`), kd = k => $(`[data-d="${k}"]`);
const shown = {};
function roll(k, to, fmt) {
  const el = kpiEl(k), from = shown[k] ?? 0;
  shown[k] = to;
  if (el._stop) el._stop();
  el._stop = tween(from === 0 ? 900 : 600, t => { el.textContent = fmt(lerp(from, to, t)); });
}
function renderKpis() {
  const a = agg;
  const aov = a.ord ? a.rev / a.ord : 0, lwAov = a.lwOrd ? a.lwRev / a.lwOrd : 0;
  const upo = a.ord ? a.units / a.ord : 0, lwUpo = a.lwOrd ? a.lwUnits / a.lwOrd : 0;
  roll('rev', a.rev, usd0);
  roll('ord', a.ord, v => nf0.format(Math.round(v)));
  roll('aov', aov, usd);
  roll('upo', upo, v => v.toFixed(2));
  roll('proj', a.proj, usd0);
  const vs = 'vs last ' + WD[dayDate(LWD).getUTCDay()];
  kd('rev').innerHTML = deltaHTML(a.lwRev ? a.rev / a.lwRev - 1 : 0, vs);
  kd('ord').innerHTML = deltaHTML(a.lwOrd ? a.ord / a.lwOrd - 1 : 0, vs);
  kd('aov').innerHTML = deltaHTML(lwAov ? aov / lwAov - 1 : 0, vs);
  kd('upo').innerHTML = deltaHTML(lwUpo ? upo / lwUpo - 1 : 0, vs);
  kd('proj').innerHTML = deltaHTML(a.target ? a.proj / a.target - 1 : 0, 'vs ' + usd0(a.target) + ' target');
}

/* ---------- pace chart (canvas) ---------- */
const plot = $('.dbe-live-plot'), cv = $('.dbe-live-cv'), tip = $('.dbe-live-tip', plot);
let pal = {};
function palette() {
  const acc = col('--dbe-live-accent'), m = acc.match(/[\d.]+/g);
