    ink: col('--dbe-live-ink'), muted: col('--dbe-live-muted'), faint: col('--dbe-live-faint'), line: col('--dbe-live-line'),
    acc, acc0: col('--dbe-live-accent', 0), acc2: col('--dbe-live-accent', 0.26), up: col('--dbe-live-up'), bg: col('--dbe-live-panel'),
