  const X = t => L + (t / DAY) * pw, Y = v => T + ph - (v / sc.top) * ph;
  geo = { L, pw, X, Y, sc };
  g.font = '500 10.5px system-ui, sans-serif';
  g.textBaseline = 'middle';
  /* grid */
  g.lineWidth = 1;
  for (let v = 0; v <= sc.top + 1e-6; v += sc.step) {
    const y = Math.round(Y(v)) + 0.5;
    g.strokeStyle = pal.line; g.beginPath(); g.moveTo(L, y); g.lineTo(L + pw, y); g.stroke();
    g.fillStyle = pal.faint; g.textAlign = 'right'; g.fillText(usdk(v), L - 8, y);
  }
