  for (let hh = 0; hh <= 24; hh += every) g.fillText(p2(hh) + ':00', X(hh * 3600), T + ph + 8);
  /* last week, dashed */
  const mask = a.mask;
  g.setLineDash([4, 4]); g.strokeStyle = pal.faint; g.lineWidth = 1.5;
  g.beginPath();
  for (let k = 0; k <= STEPS; k++) { const x = X(k * 300), y = Y(lwAt(k * 300, mask)); k ? g.lineTo(x, y) : g.moveTo(x, y); }
  g.stroke();
  /* target, dotted, shaped like last week */
  g.setLineDash([1.5, 4]); g.strokeStyle = pal.up; g.lineWidth = 1.6;
  g.beginPath();
  for (let k = 0; k <= STEPS; k += 2) { const x = X(k * 300), y = Y(lwAt(k * 300, mask) / a.lwFull * a.target); k ? g.lineTo(x, y) : g.moveTo(x, y); }
  g.stroke();
