  g.beginPath(); g.moveTo(X(simT), Y(a.rev));
  for (let k = Math.ceil(simT / 300); k <= STEPS; k++) g.lineTo(X(k * 300), Y(lwAt(k * 300, mask) * a.ratio));
  g.stroke();
  g.setLineDash([]);
