  const nowK = Math.floor(simT / 300);
  const path = () => { g.moveTo(X(0), Y(0)); for (let k = 1; k <= nowK; k++) g.lineTo(X(k * 300), Y(a.cum[k])); g.lineTo(X(simT), Y(a.rev)); };
