  g.beginPath(); path(); g.lineTo(X(simT), Y(0)); g.closePath(); g.fillStyle = grad; g.fill();
  g.beginPath(); path(); g.strokeStyle = pal.acc; g.lineWidth = 2.2; g.lineJoin = 'round'; g.stroke();
  g.restore();
