  const nx = X(simT), ny = Y(a.rev);
  g.strokeStyle = pal.line; g.lineWidth = 1; g.beginPath(); g.moveTo(Math.round(nx) + 0.5, T); g.lineTo(Math.round(nx) + 0.5, T + ph); g.stroke();
  if (st.reveal >= 1) {
    if (!calm()) {
      const ph2 = (now / 1600) % 1;
      g.fillStyle = pal.accA(0.35 * (1 - ph2));
      g.beginPath(); g.arc(nx, ny, 4 + ph2 * 10, 0, Math.PI * 2); g.fill();
    }
    g.fillStyle = pal.acc; g.beginPath(); g.arc(nx, ny, 4, 0, Math.PI * 2); g.fill();
    g.strokeStyle = pal.bg; g.lineWidth = 1.5; g.stroke();
  }
  /* end labels */
  if (Rr > 40) {
    g.textAlign = 'left'; g.textBaseline = 'middle'; g.font = '600 11px system-ui, sans-serif';
    let yp = Y(a.proj), yt = Y(a.target);
    if (Math.abs(yp - yt) < 14) { if (yp < yt) { yp -= 7; yt += 7; } else { yp += 7; yt -= 7; } }
    g.fillStyle = pal.acc; g.fillText(usdk(a.proj), L + pw + 8, yp);
    g.fillStyle = pal.up; g.fillText(usdk(a.target), L + pw + 8, yt);
  }
  /* order marker from the stream */
