    const my = Y(a.cum[Math.min(k, nowK)]);
    g.strokeStyle = pal.ink; g.lineWidth = 1; g.setLineDash([2, 3]);
    g.beginPath(); g.moveTo(mx, T); g.lineTo(mx, T + ph); g.stroke(); g.setLineDash([]);
    g.fillStyle = pal.ink; g.beginPath(); g.arc(mx, my, 3.5, 0, Math.PI * 2); g.fill();
  }
  /* crosshair */
  if (st.hoverX != null) {
    const t = clamp((st.hoverX - L) / pw, 0, 1) * DAY, k = Math.round(t / 300), tt = k * 300;
    const x = Math.round(X(tt)) + 0.5;
    g.strokeStyle = pal.muted; g.lineWidth = 1; g.beginPath(); g.moveTo(x, T); g.lineTo(x, T + ph); g.stroke();
    const lw = lwAt(tt, mask), tg = lw / a.lwFull * a.target;
    const dots = [[lw, pal.faint], [tg, pal.up]];
    let td = null;
    if (tt <= simT) { td = a.cum[k]; dots.push([td, pal.acc]); } else dots.push([lw * a.ratio, pal.accA(0.6)]);
    dots.forEach(([v, c]) => { g.fillStyle = c; g.beginPath(); g.arc(x, Y(v), 3.5, 0, Math.PI * 2); g.fill(); });
    tip.innerHTML = `<b>${hm(tt)}${tt > simT ? ' · projected' : ''}</b>` +
      (td != null ? `<p><span><i style="--c:var(--dbe-live-accent)"></i>Today</span><em>${usd0(td)}</em></p>`
                  : `<p><span><i style="--c:var(--dbe-live-accent)"></i>Projected</span><em>${usd0(lw * a.ratio)}</em></p>`) +
      `<p><span><i style="--c:var(--dbe-live-faint)"></i>${esc($('.dbe-live-lwlabel').textContent)}</span><em>${usd0(lw)}</em></p>` +
      `<p><span><i style="--c:var(--dbe-live-up)"></i>Target</span><em>${usd0(tg)}</em></p>` +
      (td != null && lw > 0 ? `<p><span>Δ last week</span><em>${signed(td / lw - 1)}</em></p>` : '');
