  const steps = [['Placed', 0], ['Payment captured', 3], ['Fraud screen passed', 9], ['Queued at the roastery', 95], ['Label printed', 1500]];
  dbody.innerHTML =
    `<div class="dbe-live-who"><b>${esc(o.who)}</b><span>${esc(o.city)} · ${CHN[o.ch]} · ${o.pay}</span></div>` +
