/* ---------- hourly heatmap ---------- */
const heat = $('.dbe-live-heat'), heatTip = $('.dbe-live-heatcard .dbe-live-tip');
let heatFocus = null;
function hourVal(d, h) {
  let n = 0, c = 0;
  CHS.forEach((ch, i) => { if (st.chans.has(ch)) { const k = hIdx(d, h, i); n += HOUR[k]; c += HOUR[k + 1]; } });
  return { n, c };
}
function renderHeat(enter) {
  const nd = st.days, d0 = DAYS - nd, curH = Math.floor(simT / 3600), m = st.metric;
  const rows = [];
  let max = 0;
  const colAvg = new Array(24).fill(0);
  for (let d = d0; d < DAYS; d++) {
    const r = [];
    for (let h = 0; h < 24; h++) {
      const v = hourVal(d, h), x = v[m];
      r.push(v);
      if (!(d === DAYS - 1 && h > curH)) max = Math.max(max, x);
      if (d < DAYS - 1) colAvg[h] += x / (nd - 1);
    }
    rows.push(r);
  }
  const amax = Math.max(...colAvg);
  const fmt = m === 'n' ? (v => nf0.format(v)) : usdk;
  let html = `<div class="dbe-live-hrow" role="row"><span class="dbe-live-hlab" role="columnheader">Avg / hr</span>` +
    colAvg.map((v, h) => `<span class="dbe-live-hbar" role="columnheader" aria-label="${p2(h)}:00 average ${fmt(v)}"><i style="--h:${(v / amax).toFixed(3)}"></i></span>`).join('') + `<span class="dbe-live-htot" role="columnheader">Day</span></div>`;
  html += `<div class="dbe-live-hrow" aria-hidden="true"><span></span>` + colAvg.map((_, h) => `<span class="dbe-live-hhead">${h % 3 === 0 ? p2(h) : ''}</span>`).join('') + `<span></span></div>`;
  rows.forEach((r, ri) => {
    const d = d0 + ri, isToday = d === DAYS - 1;
    const tot = r.reduce((s, v, h) => s + (isToday && h > curH ? 0 : v[m]), 0);
    html += `<div class="dbe-live-hrow" role="row"><span class="dbe-live-hlab" role="rowheader">${isToday ? '<b>Today</b>' : dayLabel(d).replace(/ \w+$/, '')}</span>`;
    r.forEach((v, h) => {
      const empty = isToday && h > curH;
      const t = empty || !max ? 0 : Math.max(0.05, v[m] / max);
      html += `<span class="dbe-live-cell${isToday && h === curH ? ' is-now' : ''}" role="gridcell" tabindex="-1" data-d="${d}" data-h="${h}" style="--t:${t.toFixed(3)};--c:${h};--r:${ri}"${empty ? ' data-empty aria-label="Not yet"' : ` aria-label="${dayLabel(d)} ${p2(h)}:00, ${nf0.format(v.n)} orders, ${usd0(v.c)}"`}></span>`;
    });
    html += `<span class="dbe-live-htot">${fmt(tot)}</span></div>`;
  });
  heat.innerHTML = html;
  heat.style.setProperty('--n', nd);
  const cells = $$('.dbe-live-cell', heat);
  const keep = heatFocus && cells.find(c => c.dataset.d === heatFocus[0] && c.dataset.h === heatFocus[1]);
  (keep || cells[cells.length - 24 + Math.min(curH, 23)] || cells[0]).tabIndex = 0;
  if (enter && !calm()) { heat.classList.remove('is-enter'); void heat.offsetWidth; heat.classList.add('is-enter'); }
  /* the note: busiest hour and today's pace */
  const bh = colAvg.indexOf(amax);
  const a = agg;
  heatNote.innerHTML = `Busiest hour across the last ${nd - 1} full days: <b>${p2(bh)}:00–${p2(bh + 1)}:00</b>, averaging <b>${fmt(amax)}</b>${m === 'n' ? ' orders' : ''}. ` +
    `Today is running <b>${signed(a.lwRev ? a.rev / a.lwRev - 1 : 0)}</b> against last ${WDL[dayDate(LWD).getUTCDay()]} at ${hm(simT)}.`;
}
