/* ---------- top items, re-ranked with FLIP ---------- */
const itemsEl = $('.dbe-live-items'), itemCard = $('.dbe-live-itemcard'), itemTip = $('.dbe-live-tip', itemCard);
let split = [];
function renderItems(enter) {
  const q = new Array(P.length).fill(0), c = new Array(P.length).fill(0);
  split = P.map(() => CHS.map(() => [0, 0]));
  for (const o of today) if (on(o)) {
    const ci = CHS.indexOf(o.ch);
    for (const [pi, n] of o.lines) { q[pi] += n; c[pi] += n * P[pi].p; split[pi][ci][0] += n; split[pi][ci][1] += n * P[pi].p; }
  }
  const key = st.rank === 'c' ? c : q;
  const order = P.map((_, i) => i).filter(i => q[i] > 0).sort((a, b) => key[b] - key[a] || a - b);
  const top = key[order[0]] || 1;
  const before = new Map($$('.dbe-live-item', itemsEl).map(li => [li.dataset.p, li.getBoundingClientRect().top]));
  const existing = new Map($$('.dbe-live-item', itemsEl).map(li => [li.dataset.p, li]));
  const frag = [];
  order.forEach((pi, rank) => {
    let li = existing.get(String(pi));
    if (!li) {
      li = document.createElement('li'); li.className = 'dbe-live-item'; li.dataset.p = pi;
      li.innerHTML = `<span class="dbe-live-item-rank"></span><span class="dbe-live-item-name"><b>${esc(P[pi].n)}</b><small>${esc(P[pi].v)}</small></span><span class="dbe-live-item-bar"><i>${CHS.map(ch => `<b style="--c:${chColor(ch)}"></b>`).join('')}</i></span><span class="dbe-live-item-q"></span><span class="dbe-live-item-c"></span>`;
    }
    existing.delete(String(pi));
    li.style.setProperty('--i', rank);
    $('.dbe-live-item-rank', li).textContent = rank + 1;
    $('.dbe-live-item-bar i', li).style.setProperty('--s', (key[pi] / top).toFixed(4));
    const k = st.rank === 'c' ? 1 : 0;
    $$('.dbe-live-item-bar b', li).forEach((b, ci) => { b.style.width = (key[pi] ? split[pi][ci][k] / key[pi] * 100 : 0).toFixed(2) + '%'; });
    $('.dbe-live-item-q', li).textContent = nf0.format(q[pi]) + ' u';
    $('.dbe-live-item-c', li).textContent = usd0(c[pi]);
    li.setAttribute('aria-label', `${rank + 1}. ${P[pi].n}, ${q[pi]} units, ${usd0(c[pi])}`);
    frag.push(li);
  });
  existing.forEach(li => li.remove());
  frag.forEach(li => itemsEl.appendChild(li));
  if (enter && !calm()) { itemsEl.classList.remove('is-enter'); void itemsEl.offsetWidth; itemsEl.classList.add('is-enter'); return; }
  if (calm()) return;
  frag.forEach(li => {
    const b = before.get(li.dataset.p);
    if (b == null) return;
    const dy = b - li.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) li.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' });
  });
}

