itemsEl.addEventListener('pointerover', e => { const li = e.target.closest('.dbe-live-item'); if (li) itemShow(li); });
itemsEl.addEventListener('pointerleave', () => { itemTip.hidden = true; });
itemsEl.addEventListener('scroll', () => { itemTip.hidden = true; }, { passive: true });

/* ---------- controls ---------- */
const views = $$('.dbe-live-view');
const tabs = $$('.dbe-live-tab');
tabs.forEach((t, i) => { const id = uid('tab' + i), pid = uid('panel' + i); t.id = id; t.setAttribute('aria-controls', pid); views[i].id = pid; views[i].setAttribute('aria-labelledby', id); });
roving($('.dbe-live-nav'), '.dbe-live-tab', 'aria-selected', v => {
  st.view = v; root.dataset.view = v;
  views.forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'hours') renderHeat(true);
  if (v === 'items') renderItems(true);
  if (v === 'live') dirty = true;
});
roving($('[data-g="metric"]'), '[role="radio"]', 'aria-checked', v => { if (st.metric !== v) { st.metric = v; renderHeat(true); } });
roving($('[data-g="days"]'), '[role="radio"]', 'aria-checked', v => { if (st.days !== +v) { st.days = +v; renderHeat(true); } });
roving($('[data-g="rank"]'), '[role="radio"]', 'aria-checked', v => { if (st.rank !== v) { st.rank = v; renderItems(false); } });
$('.dbe-live-chips').addEventListener('click', e => {
  const b = e.target.closest('.dbe-live-chip');
  if (!b) return;
  const c = b.dataset.ch, onNow = st.chans.has(c);
  if (onNow && st.chans.size === 1) return; // keep at least one channel
  if (onNow) st.chans.delete(c); else st.chans.add(c);
  b.setAttribute('aria-pressed', String(!onNow));
  st.queued = st.queued.filter(on);
  updateQueued();
  refresh(true);
});
const pauseBtn = $('.dbe-live-pause');
function updateQueued() {
  qBadge.hidden = !st.queued.length;
  qBadge.textContent = '+' + st.queued.length;
}
pauseBtn.addEventListener('click', () => {
  st.paused = !st.paused;
  pauseBtn.setAttribute('aria-pressed', String(st.paused));
  $('span', pauseBtn).textContent = st.paused ? 'Resume' : 'Pause';
  pauseBtn.title = st.paused ? 'Resume the stream' : 'Pause the stream';
  if (!st.paused) {
    const q = st.queued.splice(0);
    q.forEach(pushRow);
    updateQueued();
  }
});

/* ---------- live loop ---------- */
let dirty = true, running = false, last = 0, lastSec = -1;
function refresh(rebuild) {
  recalc(); renderKpis(); rate();
  if (rebuild) buildList();
  if (st.view === 'hours') renderHeat(false);
  if (st.view === 'items') renderItems(false);
  if (st.open != null) renderDrawer();
  dirty = true;
}
function arrive(o) {
  today.push(o); tally(DAYS - 1, o);
  if (on(o)) { if (st.paused) { st.queued.push(o); updateQueued(); } else pushRow(o); }
}
function advance(ds) {
  const to = Math.min(DAY - 1, simT + ds);
  let any = false;
  while (nextT <= to) { simT = nextT; arrive(makeOrder(RL, nextT, seq++)); any = true; scheduleNext(); }
  simT = to;
  if (any) refresh(false);
  const sec = Math.floor(simT);
  if (sec !== lastSec) {
    lastSec = sec;
    $('.dbe-live-time').textContent = hms(simT);
    if (sec % 60 === 0) { rate(); recalc(); renderKpis(); }
  }
  dirty = true;
}
function loop(now) {
  if (!root.isConnected) return;
  if (!onScreen) { running = false; return; }
  const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
  last = now;
  if (!document.hidden) advance(dt * SPEED);
  if (st.view === 'live' && (dirty || !calm())) { drawPace(now); dirty = false; }
  requestAnimationFrame(loop);
}
function wake() { if (!running && root.isConnected) { running = true; last = 0; requestAnimationFrame(loop); } }
wakers.push(wake);

new ResizeObserver(() => { sizeCv(); dirty = true; if (calm() || !running) drawPace(performance.now()); }).observe(plot);

/* ---------- mount ---------- */
palette();
recalc();
renderKpis();
buildList();
rate();
$('.dbe-live-time').textContent = hms(simT);
tween(1200, t => { st.reveal = t; dirty = true; });
drawPace(performance.now());
wake();

css:
.dbe-stock {
  width: 100%;
  height: var(--dbe-stock-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-stock-line);
  border-radius: 14px;
  background: var(--dbe-stock-bg);
  color: var(--dbe-stock-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-stock-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-stock-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-stock-num { font-variant-numeric: tabular-nums; }
  & .dbe-stock-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-stock-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-stock-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-stock-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-stock-line-2) transparent; }
  & .dbe-stock-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  & .dbe-stock-scroll::-webkit-scrollbar-thumb { background: var(--dbe-stock-line-2); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  & .dbe-stock-scroll::-webkit-scrollbar-track { background: transparent; }
}

@keyframes dbe-stock-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dbe-stock-draw { from { stroke-dashoffset: 1; } }
@keyframes dbe-stock-fade { from { opacity: 0; } }
@keyframes dbe-stock-pop { from { opacity: 0; transform: scale(0.3); } }
@keyframes dbe-stock-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }

/* the need-action ring is a conic gradient whose stops are registered, so it eases between states */
@property --dbe-stock-p-out { syntax: "<percentage>"; inherits: true; initial-value: 0%; }
@property --dbe-stock-p-crit { syntax: "<percentage>"; inherits: true; initial-value: 0%; }
@property --dbe-stock-p-act { syntax: "<percentage>"; inherits: true; initial-value: 0%; }

.dbe-stock {
  /* re-theme with these four */
  --dbe-stock-bg: oklch(0.968 0.011 85);
  --dbe-stock-ink: oklch(0.27 0.028 60);
  --dbe-stock-accent: oklch(0.5 0.095 158);
  --dbe-stock-bad: oklch(0.56 0.165 32);
  /* derived */
  --dbe-stock-warn: oklch(0.74 0.14 72);
  --dbe-stock-over: oklch(0.6 0.065 245);
  --dbe-stock-card: color-mix(in oklch, var(--dbe-stock-bg), white 62%);
  --dbe-stock-sunk: color-mix(in oklch, var(--dbe-stock-bg), var(--dbe-stock-ink) 5%);
  --dbe-stock-line: color-mix(in oklch, var(--dbe-stock-ink) 12%, transparent);
  --dbe-stock-line-2: color-mix(in oklch, var(--dbe-stock-ink) 24%, transparent);
  --dbe-stock-muted: color-mix(in oklch, var(--dbe-stock-ink) 64%, var(--dbe-stock-bg));
  --dbe-stock-faint: color-mix(in oklch, var(--dbe-stock-ink) 40%, var(--dbe-stock-bg));
  --dbe-stock-tint: color-mix(in oklch, var(--dbe-stock-accent) 12%, var(--dbe-stock-card));
  --dbe-stock-ease: cubic-bezier(0.2, 0.9, 0.25, 1);
  --dbe-stock-spring: linear(0, 0.013, 0.05 2.4%, 0.2 5.2%, 0.77 14%, 0.96 18.4%, 1.04 22.5%, 1.065 27%, 1.06 31.5%, 1.015 42%, 0.997 52%, 1);
  transition: --dbe-stock-p-out 700ms var(--dbe-stock-ease), --dbe-stock-p-crit 700ms var(--dbe-stock-ease), --dbe-stock-p-act 700ms var(--dbe-stock-ease);

  .dbe-stock-eyebrow { font-size: 10.5px; font-weight: 680; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbe-stock-muted); }
  .dbe-stock-r { text-align: right; }

  /* ---------- shell ---------- */
  .dbe-stock-app {
    display: grid; height: 100%;
    grid-template-columns: 212px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side head" "side main";
  }
  .dbe-stock-side {
    grid-area: side; min-height: 0;
    display: flex; flex-direction: column; gap: 22px;
    padding: 18px 12px 14px;
    background: var(--dbe-stock-sunk);
    border-right: 1px solid var(--dbe-stock-line);
    overflow: auto;
  }
  .dbe-stock-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbe-stock-brand svg { width: 32px; height: 32px; padding: 6px; border-radius: 9px; background: var(--dbe-stock-ink); color: var(--dbe-stock-bg); fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; flex: none; }
  .dbe-stock-brand span { display: grid; line-height: 1.15; }
  .dbe-stock-brand b { font-weight: 720; letter-spacing: -0.01em; font-size: 14px; }
  .dbe-stock-brand small { font-size: 11.5px; color: var(--dbe-stock-muted); }
  .dbe-stock-nav { display: grid; gap: 2px; }
  .dbe-stock-tab {
    display: flex; align-items: center; gap: 10px;
    padding: 8px 10px; border-radius: 8px;
    color: var(--dbe-stock-muted); font-weight: 580;
    transition: background-color 160ms var(--dbe-stock-ease), color 160ms var(--dbe-stock-ease);
    & span { flex: 1; }
    &:hover { color: var(--dbe-stock-ink); background: color-mix(in oklch, var(--dbe-stock-ink) 5%, transparent); }
    &[aria-selected="true"] { color: var(--dbe-stock-ink); background: var(--dbe-stock-card); box-shadow: 0 0 0 1px var(--dbe-stock-line), 0 1px 2px color-mix(in oklch, var(--dbe-stock-ink) 8%, transparent); }
    &[aria-selected="true"] .dbe-stock-ico { color: var(--dbe-stock-accent); }
  }
  .dbe-stock-badge {
    font-style: normal; font-size: 11px; font-weight: 700; font-variant-numeric: tabular-nums;
    min-width: 20px; padding: 1px 6px; border-radius: 99px; text-align: center;
    background: var(--dbe-stock-bad); color: var(--dbe-stock-card);
  }
  .dbe-stock-badge[data-b="po"] { background: var(--dbe-stock-ink); }
  .dbe-stock-sites { display: grid; gap: 8px; }
  .dbe-stock-sites > .dbe-stock-eyebrow { padding: 0 8px; }
  .dbe-stock-sitelist { display: grid; gap: 2px; }
  .dbe-stock-site {
    position: relative; display: grid; gap: 6px; padding: 8px 10px 9px; border-radius: 8px;
    transition: background-color 160ms var(--dbe-stock-ease);
    & span { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
    & b { font-weight: 600; font-size: 12.5px; }
    & small { font-size: 11px; color: var(--dbe-stock-muted); font-variant-numeric: tabular-nums; }
    & i { display: block; height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--dbe-stock-ink) calc(var(--f) * 100%), var(--dbe-stock-line) 0); opacity: 0.55; transition: opacity 160ms; }
    &:hover { background: color-mix(in oklch, var(--dbe-stock-ink) 5%, transparent); }
    &[aria-checked="true"] { background: var(--dbe-stock-card); box-shadow: 0 0 0 1px var(--dbe-stock-line); }
    &[aria-checked="true"] i { opacity: 1; background: linear-gradient(90deg, var(--dbe-stock-accent) calc(var(--f) * 100%), var(--dbe-stock-line) 0); }
  }
  .dbe-stock-sync { margin-top: auto; padding: 0 8px; font-size: 11px; color: var(--dbe-stock-muted); }

  .dbe-stock-head {
    grid-area: head;
    display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 24px; flex-wrap: wrap;
    padding: 16px 20px 13px;
    border-bottom: 1px solid var(--dbe-stock-line);
  }
  .dbe-stock-title { display: grid; gap: 3px; }
  .dbe-stock-h { font-size: clamp(20px, 0.95rem + 1cqi, 27px); font-weight: 740; letter-spacing: -0.03em; line-height: 1.05; }
  .dbe-stock-knobs { display: flex; gap: 18px; flex-wrap: wrap; }
  .dbe-stock-knob {
    display: grid; gap: 4px; width: 170px;
    & span { display: flex; justify-content: space-between; font-size: 11.5px; font-weight: 600; color: var(--dbe-stock-muted); }
    & output { color: var(--dbe-stock-ink); font-weight: 700; }
    & input { width: 100%; margin: 0; height: 18px; cursor: pointer; }
  }

  .dbe-stock-main { grid-area: main; min-height: 0; padding: 14px 20px 18px; }
  .dbe-stock-view { height: 100%; display: grid; gap: 14px; grid-template-rows: auto minmax(0, 1fr); align-content: start; animation: dbe-stock-rise 420ms var(--dbe-stock-ease) both; }
  .dbe-stock-v-alerts, .dbe-stock-v-po { height: auto; grid-template-rows: none; }

  /* ---------- KPIs ---------- */
  .dbe-stock-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
  .dbe-stock-kpi {
    display: grid; gap: 2px; align-content: start;
    padding: 11px 14px 12px; border-radius: 11px;
    background: var(--dbe-stock-card); border: 1px solid var(--dbe-stock-line);
    animation: dbe-stock-rise 520ms var(--dbe-stock-ease) both; animation-delay: calc(var(--i) * 60ms);
    & output { font-size: clamp(19px, 0.8rem + 1.1cqi, 26px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.12; }
    & small { font-size: 11.5px; color: var(--dbe-stock-muted); font-variant-numeric: tabular-nums; }
  }
  .dbe-stock-kpi-ring { grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 12px; }
  .dbe-stock-kpi-ring > div { display: grid; gap: 2px; }
  .dbe-stock-ring {
    width: 44px; height: 44px; border-radius: 50%;
    background: conic-gradient(var(--dbe-stock-bad) 0 var(--dbe-stock-p-out), color-mix(in oklch, var(--dbe-stock-bad) 55%, var(--dbe-stock-warn)) 0 var(--dbe-stock-p-crit), var(--dbe-stock-warn) 0 var(--dbe-stock-p-act), color-mix(in oklch, var(--dbe-stock-accent) 30%, var(--dbe-stock-sunk)) 0);
    -webkit-mask: radial-gradient(circle, transparent 54%, black 56%);
    mask: radial-gradient(circle, transparent 54%, black 56%);
  }

  /* ---------- table ---------- */
  .dbe-stock-split { display: grid; grid-template-columns: minmax(0, 1fr) clamp(300px, 33cqi, 380px); gap: 14px; min-height: 0; }
  .dbe-stock-card { min-height: 0; border-radius: 12px; background: var(--dbe-stock-card); border: 1px solid var(--dbe-stock-line); }
  .dbe-stock-tablecard { display: grid; grid-template-rows: auto minmax(0, 1fr); overflow: hidden; }
  .dbe-stock-filters {
    display: flex; gap: 4px; padding: 10px 10px 8px; flex-wrap: wrap; border-bottom: 1px solid var(--dbe-stock-line);
    & button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dbe-stock-muted); transition: background-color 160ms var(--dbe-stock-ease), color 160ms var(--dbe-stock-ease); }
    & button b { font-weight: 700; font-size: 11px; padding: 0 6px; border-radius: 99px; background: var(--dbe-stock-sunk); color: var(--dbe-stock-ink); font-variant-numeric: tabular-nums; min-width: 22px; text-align: center; }
    & button:hover { color: var(--dbe-stock-ink); background: var(--dbe-stock-sunk); }
    & button[aria-checked="true"] { color: var(--dbe-stock-card); background: var(--dbe-stock-ink); }
    & button[aria-checked="true"] b { background: color-mix(in oklch, var(--dbe-stock-card) 22%, transparent); color: var(--dbe-stock-card); }
  }
  .dbe-stock-tablewrap { min-height: 0; }
  .dbe-stock-table { font-variant-numeric: tabular-nums; table-layout: fixed; }
  .dbe-stock-table th:nth-child(2) { width: 74px; }
  .dbe-stock-table th:nth-child(3) { width: 146px; }
  .dbe-stock-table th:nth-child(4) { width: 152px; }
  .dbe-stock-table th:nth-child(5) { width: 82px; }
  .dbe-stock-table th {
    position: sticky; top: 0; z-index: 2;
    background: var(--dbe-stock-card);
    border-bottom: 1px solid var(--dbe-stock-line-2);
    padding: 0;
    & button { width: 100%; display: flex; align-items: center; gap: 4px; padding: 9px 12px 8px; font-size: 10.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbe-stock-muted); }
    & button:hover { color: var(--dbe-stock-ink); }
    & button::after { content: ""; width: 0; height: 0; border: 3.5px solid transparent; opacity: 0; transition: opacity 120ms; }
    &[aria-sort="ascending"] button::after { opacity: 1; border-bottom-color: currentColor; transform: translateY(-2px); }
    &[aria-sort="descending"] button::after { opacity: 1; border-top-color: currentColor; transform: translateY(2px); }
    &[aria-sort="ascending"] button, &[aria-sort="descending"] button { color: var(--dbe-stock-ink); }
    &.dbe-stock-r button { justify-content: flex-end; }
  }
  .dbe-stock-table td { padding: 8px 12px; border-bottom: 1px solid var(--dbe-stock-line); vertical-align: middle; }
  .dbe-stock-table tbody tr {
    cursor: pointer; transition: background-color 140ms var(--dbe-stock-ease);
    &:hover { background: color-mix(in oklch, var(--dbe-stock-ink) 3.5%, transparent); }
    &[aria-selected="true"] { background: var(--dbe-stock-tint); box-shadow: inset 3px 0 0 var(--dbe-stock-accent); }
    &:focus-visible { outline: 2px solid var(--dbe-stock-accent); outline-offset: -2px; }
  }
  .dbe-stock-pname { display: grid; line-height: 1.3; min-width: 0; }
  .dbe-stock-pname b, .dbe-stock-pname small { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbe-stock-pname b { font-weight: 620; }
  .dbe-stock-pname small { font-size: 11px; color: var(--dbe-stock-muted); }
  .dbe-stock-cover { display: grid; grid-template-columns: 42px minmax(60px, 1fr); align-items: center; gap: 8px; min-width: 120px; }
  .dbe-stock-cover > span { text-align: right; font-weight: 620; }
  .dbe-stock-cbar { position: relative; height: 8px; border-radius: 2px; background: var(--dbe-stock-sunk); }
  .dbe-stock-cbar i { position: absolute; inset: 0 auto 0 0; width: calc(var(--w) * 100%); border-radius: 2px; background: var(--c); transition: width 520ms var(--dbe-stock-ease), background-color 300ms; }
  .dbe-stock-cbar b { position: absolute; top: -3px; bottom: -3px; left: calc(var(--m) * 100%); width: 2px; border-radius: 1px; background: var(--dbe-stock-ink); transition: left 520ms var(--dbe-stock-ease); }
  .dbe-stock-pill {
    display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
    height: 22px; padding: 0 9px 0 7px; border-radius: 99px;
    font-size: 11.5px; font-weight: 650;
    color: color-mix(in oklch, var(--c), var(--dbe-stock-ink) 35%);
    background: color-mix(in oklch, var(--c) 16%, var(--dbe-stock-card));
    &::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
  }
  .dbe-stock-dots { display: inline-flex; gap: 3px; margin-left: 5px; vertical-align: middle; }
  .dbe-stock-table td[data-c="st"] { white-space: nowrap; }
  .dbe-stock-dots i { width: 6px; height: 6px; border-radius: 50%; background: var(--c); }
  .dbe-stock-sug { font-weight: 620; }
  .dbe-stock-sug small { display: block; font-weight: 500; font-size: 10.5px; color: var(--dbe-stock-muted); }

  /* ---------- runway ---------- */
  .dbe-stock-runway { display: grid; grid-template-rows: auto auto auto minmax(150px, 1fr) auto; overflow: hidden; }
  .dbe-stock-rhead { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; padding: 13px 14px 8px; }
  .dbe-stock-rhead h3 { font-size: 15px; font-weight: 700; letter-spacing: -0.015em; line-height: 1.2; margin-top: 2px; }
  .dbe-stock-facts {
    display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); margin: 0; padding: 0 14px 10px; gap: 6px;
    & div { display: grid; gap: 1px; min-width: 0; }
    & dt { font-size: 10px; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbe-stock-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & dd { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; }
  }
  .dbe-stock-rtools { display: flex; justify-content: space-between; align-items: center; padding: 8px 14px 0; border-top: 1px solid var(--dbe-stock-line); }
  .dbe-stock-seg {
    display: inline-flex; padding: 2px; gap: 2px; border-radius: 8px; background: var(--dbe-stock-sunk);
    & button { height: 24px; padding: 0 9px; border-radius: 6px; font-size: 11.5px; font-weight: 650; color: var(--dbe-stock-muted); }
    & button[aria-checked="true"] { background: var(--dbe-stock-card); color: var(--dbe-stock-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbe-stock-ink) 14%, transparent); }
  }
