  const arr = c.arr[t] > 0 ? `<p><span>Delivery</span><em>+${nf0.format(c.arr[t])}</em></p>` : '';
  const note = c.proj[t] <= 0 ? 'Out of stock' : c.proj[t] < c.ss ? 'Under safety stock' : c.proj[t] <= c.rop ? 'Under reorder point' : 'Above reorder point';
  tip.innerHTML = `<b>${dLong(t)} · day ${t}</b><p><span>Projected</span><em>${nf0.format(c.proj[t])} u</em></p>` +
    `<p><span>Likely range</span><em>${nf0.format(geo.lo[t])}–${nf0.format(geo.up[t])}</em></p>${arr}<p><span>${note}</span><em>${nf0.format(c.proj[t] / c.d)} d cover</em></p>`;
  placeTip(tip, chart, px, py);
}
svg.addEventListener('pointermove', e => {
  if (!geo) return;
  const r = svg.getBoundingClientRect();
  hoverAt(Math.round((e.clientX - r.left - geo.L) / geo.pw * geo.H));
});
svg.addEventListener('pointerleave', () => { st.hover = null; tip.hidden = true; const x = $('.dbe-stock-x', svg); if (x) x.setAttribute('visibility', 'hidden'); });
new ResizeObserver(es => {
  const r = es[0].contentRect;
  if (Math.abs(r.width - cw) < 1 && Math.abs(r.height - ch) < 1) return;
  cw = r.width; ch = r.height;
  drawRunway(false);
}).observe(chart);

/* ---------- drafting purchase orders ---------- */
const toast = $('.dbe-stock-toast');
let toastT = 0;
function say(msg) {
  toast.textContent = msg;
  toast.classList.remove('is-on'); void toast.offsetWidth; toast.classList.add('is-on');
  clearTimeout(toastT);
  toastT = setTimeout(() => toast.classList.remove('is-on'), 2600);
}
function draft(i) {
  const c = C[i];
  const lines = c.parts ? c.parts.filter(p => p.sug > 0).map(p => [p.w, p.sug]) : [[c.w, c.sug]];
  lines.forEach(([w, q]) => drafts.set(i + '|' + w, (drafts.get(i + '|' + w) || 0) + q));
  const n = lines.reduce((a, l) => a + l[1], 0);
  say(`${nf0.format(n)} × ${SKUS[i].name} added to the ${SUP[SKUS[i].sup].n} draft`);
  updateAll(false);
}
$('[data-r="draft"]').addEventListener('click', () => draft(st.sel));

/* ---------- alerts ---------- */
const alertsEl = $('.dbe-stock-alerts');
function renderAlerts() {
  const list = C.filter(c => ACT.has(c.status)).sort((a, b) => (a.outDay < 0 ? 999 : a.outDay) - (b.outDay < 0 ? 999 : b.outDay) || STAT[a.status].rank - STAT[b.status].rank);
  if (!list.length) { alertsEl.innerHTML = '<li class="dbe-stock-empty">Nothing needs action at this service level.</li>'; return; }
  alertsEl.innerHTML = list.map((c, k) => {
    const s = SKUS[c.i], H = 30;
    const max = Math.max(c.rop * 1.15, ...Array.from(c.proj.slice(0, H + 1))) || 1;
    const pts = Array.from(c.proj.slice(0, H + 1)).map((v, t) => `${(t / H * 200).toFixed(1)},${(44 - v / max * 40).toFixed(1)}`).join(' ');
    const ry = (44 - c.rop / max * 40).toFixed(1);
    const nextPo = c.pos.filter(p => p.eta > 0).sort((a, b) => a.eta - b.eta)[0];
    const when = c.outDay === 0 ? `<b>Out now</b>${nextPo ? ` · ${nextPo.id} lands ${dShort(nextPo.eta)}` : ' · nothing on order'}`
      : c.outDay > 0 ? `Runs out <b>${dLong(c.outDay)}</b>, ${inDays(c.outDay)}` : `<b>Order ${c.orderBy <= 0 ? 'today' : 'by ' + dLong(c.orderBy)}</b>`;
    const inBasket = [...drafts.keys()].some(key => +key.split('|')[0] === c.i);
    return `<li class="dbe-stock-alert" style="--i:${k};--c:${STAT[c.status].c}">${pill(c.status)}<h4>${esc(s.name)}<small>${esc(s.variant)} · ${SUP[s.sup].n}</small></h4>` +
      `<p class="dbe-stock-when">${when}</p>` +
      `<svg viewBox="0 0 200 46" preserveAspectRatio="none" aria-hidden="true"><line class="dbe-stock-sparkrop" x1="0" x2="200" y1="${ry}" y2="${ry}" vector-effect="non-scaling-stroke"/><polyline class="dbe-stock-spark" points="${pts}" vector-effect="non-scaling-stroke"/></svg>` +
      `<footer><span>${c.sug ? nf0.format(c.sug) + ' u · ' + usd0(c.sug * s.cost) : 'covered by open PO'}</span><button class="dbe-stock-btn${inBasket ? '' : ' dbe-stock-ghost'}" data-draft="${c.i}"${inBasket || !c.sug ? ' disabled' : ''}>${inBasket ? 'In basket' : 'Draft PO'}</button></footer></li>`;
  }).join('');
}
alertsEl.addEventListener('click', e => { const b = e.target.closest('[data-draft]'); if (b) draft(+b.dataset.draft); });

/* ---------- purchase orders ---------- */
const draftsEl = $('.dbe-stock-drafts'), openBody = $('.dbe-stock-otable tbody');
function renderPOs(freshIds) {
  const groups = new Map();
  drafts.forEach((q, key) => { const [i, w] = key.split('|').map(Number); const sup = SKUS[i].sup; if (!groups.has(sup)) groups.set(sup, []); groups.get(sup).push({ i, w, q, key }); });
  draftsEl.innerHTML = groups.size ? [...groups].map(([sup, ls]) => {
    const tot = ls.reduce((a, l) => a + l.q * SKUS[l.i].cost, 0);
    return `<section class="dbe-stock-card dbe-stock-pocard" data-sup="${sup}"><header><h4>${SUP[sup].n}</h4><span>Lead time ${SUP[sup].L} days · lands ${dLong(SUP[sup].L)}</span></header>` +
      `<div class="dbe-stock-scroll"><table><thead><tr><th>Product</th><th>Site</th><th class="dbe-stock-r">Units</th><th class="dbe-stock-r">Line</th><th></th></tr></thead><tbody>` +
      ls.map(l => `<tr><td>${esc(SKUS[l.i].name)} <small style="color:var(--dbe-stock-muted)">${esc(SKUS[l.i].variant)}</small></td><td>${SHORT[l.w]}</td>` +
        `<td class="dbe-stock-r"><input type="number" inputmode="numeric" min="${SKUS[l.i].pack}" step="${SKUS[l.i].pack}" value="${l.q}" data-key="${l.key}" aria-label="Units of ${esc(SKUS[l.i].name)} for ${SITES[l.w]}"></td>` +
        `<td class="dbe-stock-r">${usd0(l.q * SKUS[l.i].cost)}</td><td><button class="dbe-stock-rm" data-rm="${l.key}" aria-label="Remove line"><svg class="dbe-stock-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></td></tr>`).join('') +
      `</tbody></table></div><footer><span style="color:var(--dbe-stock-muted);font-size:12px">${ls.length} line${ls.length > 1 ? 's' : ''}</span><b>${usd0(tot)}</b><button class="dbe-stock-btn" data-submit="${sup}">Submit to supplier</button></footer></section>`;
  }).join('') : '<p class="dbe-stock-empty">No drafts yet. Draft an order from a runway or an alert.</p>';
  const open = OPEN.filter(p => st.scope === 'all' || p.w === +st.scope).sort((a, b) => a.eta - b.eta || a.id.localeCompare(b.id));
  openBody.innerHTML = open.map(p => `<tr class="${freshIds && freshIds.has(p.id) ? 'is-new' : ''}"><td class="dbe-stock-mono">${p.id}</td><td>${esc(SKUS[p.i].name)} <small style="color:var(--dbe-stock-muted)">${esc(SKUS[p.i].variant)}</small></td><td>${SHORT[p.w]}</td><td class="dbe-stock-r">${nf0.format(p.qty)}</td><td class="dbe-stock-r">${dShort(p.eta)} <small style="color:var(--dbe-stock-muted)">${inDays(p.eta)}</small></td></tr>`).join('');
  $('[data-f="opencount"]').textContent = `${new Set(open.map(p => p.id)).size} orders · ${nf0.format(open.reduce((a, p) => a + p.qty, 0))} units`;
  const pb = $('[data-b="po"]');
  pb.textContent = drafts.size; pb.hidden = !drafts.size;
}
draftsEl.addEventListener('change', e => {
  const inp = e.target.closest('input[data-key]');
  if (!inp) return;
  const [i] = inp.dataset.key.split('|').map(Number), pack = SKUS[i].pack;
  const q = Math.max(pack, Math.round((+inp.value || pack) / pack) * pack);
  drafts.set(inp.dataset.key, q);
  renderPOs();
});
draftsEl.addEventListener('click', e => {
  const rm = e.target.closest('[data-rm]');
  if (rm) { drafts.delete(rm.dataset.rm); updateAll(false); return; }
  const sb = e.target.closest('[data-submit]');
  if (!sb) return;
  const sup = sb.dataset.submit, id = 'PO-' + (++poSeq), fresh = new Set([id]);
  let units = 0;
  [...drafts].forEach(([key, q]) => {
    const [i, w] = key.split('|').map(Number);
    if (SKUS[i].sup !== sup) return;
    OPEN.push({ id, i, w, qty: q, eta: SUP[sup].L, fresh: true });
    units += q; drafts.delete(key);
  });
  say(`${id} sent to ${SUP[sup].n} · ${nf0.format(units)} units land ${dLong(SUP[sup].L)}`);
  updateAll(false, fresh);
});

/* ---------- controls ---------- */
const views = $$('.dbe-stock-view'), tabs = $$('.dbe-stock-tab');
tabs.forEach((t, k) => { const a = uid('t' + k), b = uid('p' + k); t.id = a; t.setAttribute('aria-controls', b); views[k].id = b; views[k].setAttribute('aria-labelledby', a); });
const TITLES = { stock: 'Stock levels', alerts: 'Alerts', po: 'Purchase orders' };
roving($('.dbe-stock-nav'), '.dbe-stock-tab', 'aria-selected', v => {
  st.view = v;
  views.forEach(s => { s.hidden = s.dataset.view !== v; });
  $('[data-f="title"]').textContent = TITLES[v];
  if (v === 'alerts') renderAlerts();
  if (v === 'po') renderPOs();
  if (v === 'stock') renderRunway(true);
});
roving($('.dbe-stock-sitelist'), '.dbe-stock-site', 'aria-checked', v => { st.scope = v; updateAll(true); });
roving($('.dbe-stock-filters'), '[role="radio"]', 'aria-checked', v => { st.filter = v; renderTable(); });
roving($('[data-g="hz"]'), '[role="radio"]', 'aria-checked', v => { st.hz = +v; drawRunway(true); });
const slIn = $('[data-k="sl"]'), upIn = $('[data-k="up"]');
slIn.addEventListener('input', () => { st.sl = +slIn.value / 100; $('[data-o="sl"]').textContent = (+slIn.value).toFixed(1) + '%'; updateAll(false); });
upIn.addEventListener('input', () => { st.up = +upIn.value; $('[data-o="up"]').textContent = '+' + upIn.value + '%'; updateAll(false); });

function updateAll(enter, fresh) {
  recompute();
  $('[data-f="scope"]').textContent = (st.scope === 'all' ? 'All sites' : SITES[+st.scope]) + ' · ' + SKUS.length + ' SKUs';
  renderKpis(); renderSites(); renderTable(); renderRunway(enter);
  if (st.view === 'alerts') renderAlerts();
  renderPOs(fresh);
}
updateAll(true);

css:
.dbe-fulfil {
  width: 100%;
  height: var(--dbe-fulfil-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-fulfil-line);
  border-radius: 14px;
  background: var(--dbe-fulfil-bg);
  color: var(--dbe-fulfil-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-fulfil-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-fulfil-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-fulfil-num { font-variant-numeric: tabular-nums; }
  & .dbe-fulfil-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-fulfil-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-fulfil-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-fulfil-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-fulfil-line-2) transparent; }
  & .dbe-fulfil-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  & .dbe-fulfil-scroll::-webkit-scrollbar-thumb { background: var(--dbe-fulfil-line-2); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  & .dbe-fulfil-scroll::-webkit-scrollbar-track { background: transparent; }
}

@keyframes dbe-fulfil-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbe-fulfil-blink { 50% { opacity: 0.35; } }
@keyframes dbe-fulfil-grow { from { transform: scaleY(0); } }
@keyframes dbe-fulfil-slide { from { transform: scaleX(0); } }

@property --dbe-fulfil-left {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

.dbe-fulfil {
  /* re-theme with these four */
  --dbe-fulfil-bg: oklch(0.2 0.005 95);
  --dbe-fulfil-ink: oklch(0.94 0.008 95);
  --dbe-fulfil-accent: oklch(0.89 0.175 103);
  --dbe-fulfil-late: oklch(0.66 0.2 27);
  /* derived */
  --dbe-fulfil-risk: oklch(0.78 0.155 62);
  --dbe-fulfil-sunk: color-mix(in oklch, var(--dbe-fulfil-bg), black 25%);
  --dbe-fulfil-panel: color-mix(in oklch, var(--dbe-fulfil-bg), var(--dbe-fulfil-ink) 4%);
  --dbe-fulfil-raise: color-mix(in oklch, var(--dbe-fulfil-bg), var(--dbe-fulfil-ink) 9%);
  --dbe-fulfil-line: color-mix(in oklch, var(--dbe-fulfil-ink) 10%, transparent);
  --dbe-fulfil-line-2: color-mix(in oklch, var(--dbe-fulfil-ink) 19%, transparent);
  --dbe-fulfil-muted: color-mix(in oklch, var(--dbe-fulfil-ink) 60%, var(--dbe-fulfil-bg));
  --dbe-fulfil-faint: color-mix(in oklch, var(--dbe-fulfil-ink) 36%, var(--dbe-fulfil-bg));
  --dbe-fulfil-ease: cubic-bezier(0.25, 1, 0.3, 1);
  --dbe-fulfil-mono: ui-monospace, Menlo, Consolas, monospace;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  .dbe-fulfil-eyebrow { margin: 0; font-size: 10px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--dbe-fulfil-muted); }

  /* ---------- shell ---------- */
  .dbe-fulfil-app {
    display: grid; height: 100%;
    grid-template-columns: 200px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side head" "side main";
  }
  .dbe-fulfil-side {
    grid-area: side; min-height: 0; overflow: auto;
    display: flex; flex-direction: column; gap: 20px;
    padding: 16px 12px;
    background: var(--dbe-fulfil-sunk);
    border-right: 1px solid var(--dbe-fulfil-line);
  }
  .dbe-fulfil-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .dbe-fulfil-brand svg { width: 32px; height: 32px; padding: 6px; border-radius: 6px; background: var(--dbe-fulfil-accent); color: var(--dbe-fulfil-sunk); fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linejoin: round; flex: none; }
  .dbe-fulfil-brand span { display: grid; line-height: 1.15; }
  .dbe-fulfil-brand b { font-weight: 760; letter-spacing: 0.02em; text-transform: uppercase; font-size: 13px; }
  .dbe-fulfil-brand small { color: var(--dbe-fulfil-muted); font-size: 11px; }
  .dbe-fulfil-nav { display: grid; gap: 2px; }
  .dbe-fulfil-tab {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 6px;
    color: var(--dbe-fulfil-muted); font-weight: 600;
    transition: background-color 150ms var(--dbe-fulfil-ease), color 150ms var(--dbe-fulfil-ease);
    &:hover { color: var(--dbe-fulfil-ink); background: color-mix(in oklch, var(--dbe-fulfil-ink) 6%, transparent); }
    &[aria-selected="true"] { color: var(--dbe-fulfil-sunk); background: var(--dbe-fulfil-accent); }
  }
  .dbe-fulfil-cutoffs { display: grid; gap: 8px; }
  .dbe-fulfil-cutoffs > h3 { padding: 0 6px; }
  .dbe-fulfil-cutlist { display: grid; gap: 6px; }
  .dbe-fulfil-cut {
    display: grid; gap: 4px; padding: 9px 10px 10px; border-radius: 6px;
    background: var(--dbe-fulfil-panel); border: 1px solid var(--dbe-fulfil-line);
    & header { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
    & b { font-weight: 650; font-size: 12.5px; }
    & time { font: 600 11px var(--dbe-fulfil-mono); color: var(--dbe-fulfil-muted); }
    & output { font: 650 20px/1.1 var(--dbe-fulfil-mono); letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
    & small { font-size: 11px; color: var(--dbe-fulfil-muted); font-variant-numeric: tabular-nums; }
    & i { display: block; height: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--dbe-fulfil-accent) var(--dbe-fulfil-left), var(--dbe-fulfil-line) 0); transition: --dbe-fulfil-left 900ms linear; }
    &.is-soon output { color: var(--dbe-fulfil-accent); }
    &.is-soon i { background: linear-gradient(90deg, var(--dbe-fulfil-risk) var(--dbe-fulfil-left), var(--dbe-fulfil-line) 0); }
    &.is-gone { opacity: 0.5; }
    &.is-gone output { font-size: 14px; }
  }

  .dbe-fulfil-head {
    grid-area: head;
    display: flex; justify-content: space-between; align-items: flex-end; gap: 12px;
    padding: 14px 20px 12px; border-bottom: 1px solid var(--dbe-fulfil-line);
  }
  .dbe-fulfil-title { display: grid; gap: 3px; }
  .dbe-fulfil-h { font-size: clamp(20px, 0.9rem + 1cqi, 27px); font-weight: 780; letter-spacing: -0.02em; text-transform: uppercase; line-height: 1; }
  .dbe-fulfil-clockwrap { display: grid; justify-items: end; gap: 2px; }
  .dbe-fulfil-clock { font: 650 clamp(18px, 0.8rem + 1cqi, 24px)/1 var(--dbe-fulfil-mono); color: var(--dbe-fulfil-accent); letter-spacing: -0.02em; }

  .dbe-fulfil-main { grid-area: main; min-height: 0; padding: 14px 20px 16px; }
  .dbe-fulfil-view { height: 100%; display: grid; gap: 12px; grid-template-rows: auto minmax(0, 1fr) auto; animation: dbe-fulfil-rise 380ms var(--dbe-fulfil-ease) both; }
  .dbe-fulfil-v-tput { grid-template-rows: auto minmax(0, 1fr); }
  .dbe-fulfil-v-carriers { grid-template-rows: auto auto minmax(0, 1fr); }

  /* ---------- KPIs ---------- */
  .dbe-fulfil-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border-top: 1px solid var(--dbe-fulfil-line-2); border-bottom: 1px solid var(--dbe-fulfil-line); }
  .dbe-fulfil-kpi {
    display: grid; gap: 1px; padding: 8px 12px 9px;
    &:not(:first-child) { border-left: 1px solid var(--dbe-fulfil-line); }
    & output { font: 650 clamp(18px, 0.75rem + 1.05cqi, 25px)/1.15 var(--dbe-fulfil-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
  }
  .dbe-fulfil-kpi-risk output { color: var(--dbe-fulfil-risk); }

  /* ---------- floor ---------- */
  .dbe-fulfil-floor { display: grid; grid-template-columns: minmax(0, 1fr) clamp(240px, 26cqi, 300px); gap: 12px; min-height: 0; }
  .dbe-fulfil-board {
    display: grid; min-height: 0;
    grid-template-columns: 92px repeat(4, minmax(0, 1fr));
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "corner stages stages stages stages" "lanes canvas canvas canvas canvas";
    border: 1px solid var(--dbe-fulfil-line); border-radius: 8px; overflow: hidden;
    background: var(--dbe-fulfil-panel);
  }
  .dbe-fulfil-corner { grid-area: corner; display: flex; align-items: flex-end; padding: 8px; border-bottom: 1px solid var(--dbe-fulfil-line-2); border-right: 1px solid var(--dbe-fulfil-line); }
  .dbe-fulfil-chips { display: flex; gap: 3px; flex-wrap: wrap; }
  .dbe-fulfil-chip {
    padding: 2px 5px; border-radius: 4px; font: 650 10px var(--dbe-fulfil-mono); letter-spacing: 0.04em;
    color: var(--dbe-fulfil-faint); box-shadow: inset 0 0 0 1px var(--dbe-fulfil-line-2);
    &[aria-pressed="true"] { color: var(--dbe-fulfil-ink); background: var(--dbe-fulfil-raise); }
  }
  .dbe-fulfil-stages { grid-area: stages; display: grid; grid-template-columns: subgrid; border-bottom: 1px solid var(--dbe-fulfil-line-2); }
  .dbe-fulfil-stage {
    display: grid; grid-template-columns: 1fr auto; align-items: baseline; gap: 0 8px;
    padding: 8px 10px 7px; text-align: left; position: relative;
    border-left: 1px solid var(--dbe-fulfil-line);
    animation: dbe-fulfil-rise 420ms var(--dbe-fulfil-ease) both; animation-delay: calc(var(--i) * 50ms);
    transition: background-color 150ms var(--dbe-fulfil-ease);
    & span { font-size: 10.5px; font-weight: 750; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbe-fulfil-muted); }
    & b { grid-row: span 2; font: 650 22px/1 var(--dbe-fulfil-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
    & small { font-size: 10.5px; color: var(--dbe-fulfil-faint); }
    &:hover { background: color-mix(in oklch, var(--dbe-fulfil-ink) 4%, transparent); }
    &[aria-checked="true"] { background: color-mix(in oklch, var(--dbe-fulfil-accent) 10%, transparent); }
