const CSTAT = [['Delivered on time', 'var(--dbe-fulfil-accent)'], ['Delivered late', 'color-mix(in oklch, var(--dbe-fulfil-accent) 45%, var(--dbe-fulfil-late))'], ['Out for delivery', 'color-mix(in oklch, var(--dbe-fulfil-ink) 82%, var(--dbe-fulfil-bg))'], ['In transit', 'color-mix(in oklch, var(--dbe-fulfil-ink) 52%, var(--dbe-fulfil-bg))'], ['Exception', 'var(--dbe-fulfil-late)']];
const CDATA = [[1802, 61, 148, 187, 3], [5110, 288, 642, 1490, 4], [1246, 97, 88, 402, 2]];
const EXC = [
  ['VO-69804', 0, 'Address not found', 'Unit number missing · Denver, CO'],
  ['VO-69377', 0, 'Damaged in transit', 'Claim opened with carrier · Boise, ID'],
  ['VO-69951', 0, 'Refused by recipient', 'Returning to Sparks DC'],
  ['VO-68820', 1, 'No scan for 72 h', 'Last seen at Salt Lake hub'],
  ['VO-69122', 1, 'Held at depot', 'Weather delay · Flagstaff, AZ'],
  ['VO-69640', 1, 'Address not found', 'Street number transposed · Eugene, OR'],
  ['VO-69703', 1, 'Signature required', 'Third attempt tomorrow · Reno, NV'],
  ['VO-69255', 2, 'Damaged pallet', 'Two cartons crushed · Fresno, CA'],
  ['VO-69486', 2, 'Delivery window missed', 'Rebooked for Mon 5 Oct · Tacoma, WA']
];
const resolved = new Set();
const ccard = $('.dbe-fulfil-ccard'), exlist = $('.dbe-fulfil-exlist');
function renderCarriers() {
  ccard.innerHTML = CARR.map((cr, c) => {
    const d = CDATA[c], tot = d.reduce((a, b) => a + b, 0), onTime = d[0] / (d[0] + d[1]);
    return `<div class="dbe-fulfil-crow"><div><b>${cr.name}</b><small>${nf0.format(tot)} handed over</small></div>` +
      `<div class="dbe-fulfil-stack" style="--i:${c}">${d.map((v, k) => `<i style="--c:${CSTAT[k][1]};flex:${v} 1 0" data-c="${c}" data-k="${k}" aria-label="${CSTAT[k][0]}: ${v}"></i>`).join('')}</div>` +
      `<output title="On-time share of delivered">${(onTime * 100).toFixed(1)}%</output></div>`;
  }).join('') + `<div class="dbe-fulfil-ckey">${CSTAT.map(([n, c]) => `<span><i style="--c:${c}"></i>${n}</span>`).join('')}<span style="margin-left:auto">right: on-time share of delivered</span></div><div class="dbe-fulfil-tip" role="status" hidden></div>`;
  ccard.style.position = 'relative';
  exlist.innerHTML = EXC.map(([id, c, what, where]) => `<li class="dbe-fulfil-ex${resolved.has(id) ? ' is-done' : ''}"><code>${id}</code><div><b>${what} · ${CARR[c].code}</b><small>${where}</small></div><button data-ex="${id}">${resolved.has(id) ? 'Logged' : 'Log follow-up'}</button></li>`).join('');
  $('[data-f="excount"]').textContent = `${EXC.length - resolved.size} open of ${EXC.length}`;
}
ccard.addEventListener('pointermove', e => {
  const seg = e.target.closest('.dbe-fulfil-stack i'), t = $('.dbe-fulfil-tip', ccard);
  if (!seg) { t.hidden = true; return; }
  const c = +seg.dataset.c, k = +seg.dataset.k, d = CDATA[c], tot = d.reduce((a, b) => a + b, 0);
  t.innerHTML = `<b>${CARR[c].code} · ${CSTAT[k][0]}</b><p><span>Parcels</span><em>${nf0.format(d[k])}</em></p><p><span>Share</span><em>${(d[k] / tot * 100).toFixed(1)}%</em></p>`;
  const r = seg.getBoundingClientRect(), cr = ccard.getBoundingClientRect();
  placeTip(t, ccard, e.clientX - cr.left, r.top - cr.top);
});
ccard.addEventListener('pointerleave', () => { const t = $('.dbe-fulfil-tip', ccard); if (t) t.hidden = true; });
exlist.addEventListener('click', e => { const b = e.target.closest('[data-ex]'); if (!b) return; resolved.add(b.dataset.ex); renderCarriers(); const nb = $(`[data-ex="${b.dataset.ex}"]`, exlist); if (nb) nb.closest('li').focus?.(); });

/* ---------- controls ---------- */
const views = $$('.dbe-fulfil-view'), tabs = $$('.dbe-fulfil-tab');
tabs.forEach((t, k) => { const a = uid('t' + k), b = uid('p' + k); t.id = a; t.setAttribute('aria-controls', b); views[k].id = b; views[k].setAttribute('aria-labelledby', a); });
const TITLES = { floor: 'Floor', tput: 'Throughput', carriers: 'Carriers' };
roving($('.dbe-fulfil-nav'), '.dbe-fulfil-tab', 'aria-selected', v => {
  st.view = v;
  views.forEach(s => { s.hidden = s.dataset.view !== v; });
  $('[data-f="title"]').textContent = TITLES[v];
  if (v === 'tput') drawTput(true);
  if (v === 'carriers') renderCarriers();
  if (v === 'floor') renderQueue(true);
});
const stageGroup = $('.dbe-fulfil-stages');
roving(stageGroup, '.dbe-fulfil-stage', 'aria-checked', v => { st.stage = st.stage === +v ? null : +v; syncStages(); renderQueue(true); });
function syncStages() { stageBtns.forEach((b, s) => { b.setAttribute('aria-checked', String(s === st.stage)); b.tabIndex = (st.stage == null ? s === 0 : s === st.stage) ? 0 : -1; }); }
syncStages();
$('[data-f="qall"]').addEventListener('click', () => { st.stage = null; syncStages(); renderQueue(true); });
$('.dbe-fulfil-chips').addEventListener('click', e => {
  const b = e.target.closest('.dbe-fulfil-chip');
  if (!b) return;
  const c = +b.dataset.c;
  if (st.on[c] && st.on.filter(Boolean).length === 1) return;
  st.on[c] = !st.on[c];
  b.setAttribute('aria-pressed', String(st.on[c]));
  $(`.dbe-fulfil-lane[data-c="${c}"]`).classList.toggle('is-off', !st.on[c]);
  readouts(); renderQueue(true);
});
roving($('[data-g="range"]'), '[role="radio"]', 'aria-checked', v => { st.range = v; drawTput(true); });
roving($('[data-g="station"]'), '[role="radio"]', 'aria-checked', v => { st.station = v; drawTput(true); });
root.addEventListener('keydown', e => { if (e.key === 'Escape' && (st.sel || st.stage != null)) { st.sel = null; st.stage = null; syncStages(); renderQueue(true); } });

/* ---------- loop ---------- */
let running = false, last = 0, tick = 0, qtick = 0;
function loop(ts) {
  if (!root.isConnected) return;
  if (!onScreen) { running = false; return; }
  const dt = last ? Math.min(0.1, (ts - last) / 1000) : 0;
  last = ts;
  if (!document.hidden && now < CLOSE) {
    let m = dt * SPEED;
    while (m > 0) { const d = Math.min(0.25, m); step(d); m -= d; }
  }
  if (st.view === 'floor') draw(ts);
  if (ts - tick > 250) { tick = ts; readouts(); }
  if (ts - qtick > 1000) {
    qtick = ts;
    renderQueue(false);
    if (st.view === 'tput' && st.range === 'day') drawTput(false);
    for (let i = orders.length - 1; i >= 0; i--) if (orders[i].gone === -1) orders.splice(i, 1);
  }
  requestAnimationFrame(loop);
}
function wake() { if (!running && root.isConnected) { running = true; last = 0; requestAnimationFrame(loop); } }
wakers.push(wake);
new ResizeObserver(() => { cvs = fitCanvas(cv); if (!running) draw(performance.now()); }).observe(wrap);

palette();
readouts();
renderQueue(true);
wake();

css:
.dbe-regions {
  width: 100%;
  height: var(--dbe-regions-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-regions-line);
  border-radius: 14px;
  background: var(--dbe-regions-bg);
  color: var(--dbe-regions-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-regions-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-regions-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-regions-num { font-variant-numeric: tabular-nums; }
  & .dbe-regions-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-regions-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-regions-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-regions-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-regions-line-2) transparent; }
  & .dbe-regions-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  & .dbe-regions-scroll::-webkit-scrollbar-thumb { background: var(--dbe-regions-line-2); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  & .dbe-regions-scroll::-webkit-scrollbar-track { background: transparent; }
}

@keyframes dbe-regions-tile { from { opacity: 0; transform: scale(0.55); } }
@keyframes dbe-regions-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbe-regions-grow { from { transform: scaleY(0); } }
@keyframes dbe-regions-draw { from { stroke-dashoffset: 1; } }
@keyframes dbe-regions-bar { from { transform: scaleX(0); } }

.dbe-regions {
  /* re-theme with these four: paper, ink, the low and high ends of the ramp */
  --dbe-regions-bg: oklch(0.982 0.005 240);
  --dbe-regions-ink: oklch(0.25 0.035 258);
  --dbe-regions-lo: oklch(0.955 0.04 96);
  --dbe-regions-hi: oklch(0.4 0.115 262);
  /* derived */
  --dbe-regions-accent: var(--dbe-regions-hi);
  --dbe-regions-neg: oklch(0.6 0.15 38);
  --dbe-regions-mid: color-mix(in oklch, var(--dbe-regions-lo), var(--dbe-regions-bg) 40%);
  --dbe-regions-card: color-mix(in oklch, var(--dbe-regions-bg), white 70%);
  --dbe-regions-sunk: color-mix(in oklch, var(--dbe-regions-bg), var(--dbe-regions-ink) 4.5%);
  --dbe-regions-line: color-mix(in oklch, var(--dbe-regions-ink) 11%, transparent);
  --dbe-regions-line-2: color-mix(in oklch, var(--dbe-regions-ink) 22%, transparent);
  --dbe-regions-muted: color-mix(in oklch, var(--dbe-regions-ink) 62%, var(--dbe-regions-bg));
  --dbe-regions-faint: color-mix(in oklch, var(--dbe-regions-ink) 38%, var(--dbe-regions-bg));
  --dbe-regions-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --dbe-regions-spring: linear(0, 0.015, 0.06 2.6%, 0.23 5.6%, 0.8 14.5%, 0.98 19%, 1.05 23.3%, 1.07 27.5%, 1.055 32%, 1.012 43%, 0.996 54%, 1);

  container-name: dbe-regions-root;

  .dbe-regions-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbe-regions-muted); }
  .dbe-regions-r { text-align: right; }

  /* ---------- shell ---------- */
  .dbe-regions-app {
    display: grid; height: 100%;
    grid-template-columns: 196px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side head" "side main";
  }
  .dbe-regions-side { grid-area: side; display: flex; flex-direction: column; gap: 24px; padding: 18px 12px; border-right: 1px solid var(--dbe-regions-line); min-height: 0; overflow: auto; }
  .dbe-regions-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbe-regions-brand svg { width: 32px; height: 32px; padding: 6px; border-radius: 50%; background: var(--dbe-regions-ink); color: var(--dbe-regions-lo); fill: currentColor; flex: none; }
  .dbe-regions-brand span { display: grid; line-height: 1.15; }
  .dbe-regions-brand b { font-weight: 720; letter-spacing: -0.01em; font-size: 13.5px; }
  .dbe-regions-brand small { font-size: 11.5px; color: var(--dbe-regions-muted); }
  .dbe-regions-nav { display: grid; gap: 2px; }
  .dbe-regions-tab {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px;
    color: var(--dbe-regions-muted); font-weight: 560;
    transition: background-color 160ms var(--dbe-regions-ease), color 160ms var(--dbe-regions-ease);
    &:hover { color: var(--dbe-regions-ink); background: var(--dbe-regions-sunk); }
    &[aria-selected="true"] { color: var(--dbe-regions-ink); background: var(--dbe-regions-sunk); font-weight: 650; }
    &[aria-selected="true"] .dbe-regions-ico { color: var(--dbe-regions-accent); }
  }
  .dbe-regions-regions { display: grid; gap: 8px; }
  .dbe-regions-regions > .dbe-regions-eyebrow { padding: 0 10px; }
  .dbe-regions-reglist { display: grid; gap: 1px; }
  .dbe-regions-reglist button {
    display: flex; justify-content: space-between; align-items: baseline; gap: 8px; padding: 7px 10px; border-radius: 7px;
    font-size: 12.5px; color: var(--dbe-regions-muted);
    transition: background-color 160ms var(--dbe-regions-ease), color 160ms var(--dbe-regions-ease);
    & b { font-weight: 600; font-size: 11.5px; font-variant-numeric: tabular-nums; color: var(--dbe-regions-faint); }
    &:hover { background: var(--dbe-regions-sunk); color: var(--dbe-regions-ink); }
    &[aria-checked="true"] { background: var(--dbe-regions-ink); color: var(--dbe-regions-bg); font-weight: 600; }
    &[aria-checked="true"] b { color: color-mix(in oklch, var(--dbe-regions-bg) 75%, transparent); }
  }

  .dbe-regions-head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap; padding: 16px 20px 12px; border-bottom: 1px solid var(--dbe-regions-line); }
  .dbe-regions-title { display: grid; gap: 4px; min-width: 0; }
  .dbe-regions-h { font-size: clamp(19px, 0.9rem + 1cqi, 26px); font-weight: 700; letter-spacing: -0.025em; line-height: 1.12; max-width: 30ch; }
  .dbe-regions-h em { font-style: normal; color: var(--dbe-regions-accent); }
  .dbe-regions-ctrls { display: flex; gap: 8px; flex-wrap: wrap; }
  .dbe-regions-seg {
    display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbe-regions-sunk);
    & button { height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dbe-regions-muted); transition: background-color 160ms var(--dbe-regions-ease), color 160ms var(--dbe-regions-ease); }
    & button:hover { color: var(--dbe-regions-ink); }
    & button[aria-checked="true"] { background: var(--dbe-regions-card); color: var(--dbe-regions-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbe-regions-ink) 16%, transparent), 0 0 0 1px var(--dbe-regions-line); }
  }

  .dbe-regions-main {
    grid-area: main; min-height: 0; padding: 14px 20px 16px;
    display: grid; grid-template-columns: minmax(0, 1fr) clamp(250px, 26cqi, 292px); grid-template-rows: minmax(0, 1fr);
    grid-template-areas: "view detail"; gap: 16px;
  }
  .dbe-regions-view { grid-area: view; min-height: 0; animation: dbe-regions-rise 380ms var(--dbe-regions-ease) both; }

  /* ---------- tile map ---------- */
  .dbe-regions-v-map { display: grid; grid-template-rows: minmax(0, 1fr) auto; gap: 10px; }
  .dbe-regions-mapwrap { position: relative; display: grid; place-items: center; min-height: 0; container-type: size; }
  .dbe-regions-map {
    --s: min(calc((100cqw - 11 * 5px) / 12), calc((100cqh - 7 * 5px) / 8));
    display: grid; gap: 5px;
    grid-template-columns: repeat(12, var(--s));
    grid-template-rows: repeat(8, var(--s));
  }
  .dbe-regions-tile {
    position: relative;
    display: grid; align-content: center; justify-items: center; gap: 0;
    border-radius: calc(var(--s) * 0.16);
    color: var(--dbe-regions-ink);
    background: color-mix(in oklch, var(--dbe-regions-hi) calc(var(--t) * 100%), var(--dbe-regions-lo));
    font-variant-numeric: tabular-nums; line-height: 1.05;
    transition: background-color 520ms var(--dbe-regions-ease), color 300ms, opacity 220ms var(--dbe-regions-ease), transform 260ms var(--dbe-regions-spring), box-shadow 160ms;
    transition-delay: calc(var(--c) * 22ms), calc(var(--c) * 22ms), 0s, 0s, 0s;
    animation: dbe-regions-tile 640ms var(--dbe-regions-spring) both; animation-delay: calc(var(--d) * 26ms);
    & b { font-size: clamp(9px, calc(var(--s) * 0.27), 15px); font-weight: 720; letter-spacing: 0.02em; }
    & small { font-size: clamp(8px, calc(var(--s) * 0.19), 11px); font-weight: 520; opacity: 0.82; }
    &.is-dark { color: oklch(0.98 0.01 90); }
    &:hover { transform: scale(1.08); z-index: 2; box-shadow: 0 6px 16px -6px color-mix(in oklch, var(--dbe-regions-ink) 50%, transparent); }
    &:focus-visible { outline: 2px solid var(--dbe-regions-ink); outline-offset: 2px; z-index: 3; }
    &[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--dbe-regions-bg), 0 0 0 4px var(--dbe-regions-ink); z-index: 2; }
    &.is-out { opacity: 0.18; }
  }
  &[data-metric="yoy"] .dbe-regions-tile {
    background: color-mix(in oklch, var(--dbe-regions-hi) calc(max(0, var(--t) - 0.5) * 200%), color-mix(in oklch, var(--dbe-regions-neg) calc(max(0, 0.5 - var(--t)) * 200%), var(--dbe-regions-mid)));
  }
  /* hovering a legend step isolates its states, no script involved */
  &:has(.dbe-regions-bin[data-b="0"]:hover) .dbe-regions-tile:not([data-b="0"]),
  &:has(.dbe-regions-bin[data-b="1"]:hover) .dbe-regions-tile:not([data-b="1"]),
  &:has(.dbe-regions-bin[data-b="2"]:hover) .dbe-regions-tile:not([data-b="2"]),
  &:has(.dbe-regions-bin[data-b="3"]:hover) .dbe-regions-tile:not([data-b="3"]),
  &:has(.dbe-regions-bin[data-b="4"]:hover) .dbe-regions-tile:not([data-b="4"]) { opacity: 0.14; transform: scale(0.92); }

  .dbe-regions-legend { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
  .dbe-regions-bins { display: flex; flex: 1 1 320px; max-width: 520px; }
  .dbe-regions-bin {
    flex: 1; display: grid; gap: 4px; padding: 3px 1px; cursor: default; border-radius: 5px;
    & i { height: 10px; background: color-mix(in oklch, var(--dbe-regions-hi) calc(var(--t) * 100%), var(--dbe-regions-lo)); transition: transform 200ms var(--dbe-regions-spring); }
    &:first-child i { border-radius: 4px 0 0 4px; }
    &:last-child i { border-radius: 0 4px 4px 0; }
    & span { font-size: 10.5px; color: var(--dbe-regions-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
    &:hover i { transform: scaleY(1.5); }
    &:hover span { color: var(--dbe-regions-ink); }
  }
  &[data-metric="yoy"] .dbe-regions-bin i { background: color-mix(in oklch, var(--dbe-regions-hi) calc(max(0, var(--t) - 0.5) * 200%), color-mix(in oklch, var(--dbe-regions-neg) calc(max(0, 0.5 - var(--t)) * 200%), var(--dbe-regions-mid))); }

  .dbe-regions-tip {
    position: absolute; left: 0; top: 0; z-index: 10; pointer-events: none;
    min-width: 190px; padding: 10px 12px; border-radius: 10px;
    background: var(--dbe-regions-card); color: var(--dbe-regions-ink);
    border: 1px solid var(--dbe-regions-line);
    box-shadow: 0 16px 36px -12px color-mix(in oklch, var(--dbe-regions-ink) 40%, transparent);
    font-size: 12px; font-variant-numeric: tabular-nums;
    & b { display: block; font-size: 13px; font-weight: 700; margin-bottom: 4px; }
    & p { display: flex; justify-content: space-between; gap: 16px; }
    & p span { color: var(--dbe-regions-muted); }
    & p em { font-style: normal; font-weight: 640; }
    & .dbe-regions-hl { color: var(--dbe-regions-accent); }
  }

  /* ---------- rankings ---------- */
  .dbe-regions-v-rank { display: grid; }
  .dbe-regions-tablewrap { min-height: 0; border: 1px solid var(--dbe-regions-line); border-radius: 12px; background: var(--dbe-regions-card); }
  .dbe-regions-table { font-variant-numeric: tabular-nums; font-size: 12.5px; }
  .dbe-regions-table th {
    position: sticky; top: 0; z-index: 1; background: var(--dbe-regions-card); padding: 0; border-bottom: 1px solid var(--dbe-regions-line-2);
    font-size: 10.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbe-regions-muted);
    &:first-child { padding: 9px 6px 8px 12px; }
    & button { width: 100%; padding: 9px 12px 8px; font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; display: flex; gap: 4px; align-items: center; }
    &.dbe-regions-r button { justify-content: flex-end; }
    & button:hover { color: var(--dbe-regions-ink); }
    &[aria-sort="ascending"] button::after { content: "▲"; font-size: 8px; }
    &[aria-sort="descending"] button::after { content: "▼"; font-size: 8px; }
    &[aria-sort="ascending"], &[aria-sort="descending"] { color: var(--dbe-regions-ink); }
  }
  .dbe-regions-table td { padding: 7px 12px; border-bottom: 1px solid var(--dbe-regions-line); }
  .dbe-regions-table td:first-child { color: var(--dbe-regions-faint); padding-left: 12px; padding-right: 6px; }
  .dbe-regions-table tbody tr {
