/* roving focus for radio groups, tab lists and toolbars: arrows move, Home/End jump */
function roving(group, sel, attr, onPick) {
  const items = () => $$(sel, group);
  const pick = (b, focus) => {
    items().forEach(x => {
      const on = x === b;
      if (attr === 'aria-current') { if (on) x.setAttribute(attr, 'page'); else x.removeAttribute(attr); }
      else x.setAttribute(attr, String(on));
      x.tabIndex = on ? 0 : -1;
    });
    if (focus) b.focus();
    onPick(b.dataset.v, b);
  };
  items().forEach(x => { const on = attr === 'aria-current' ? x.hasAttribute(attr) : x.getAttribute(attr) === 'true'; x.tabIndex = on ? 0 : -1; });
