  rev: { label: 'Revenue', fmt: money, short: money },
  pc: { label: 'Revenue per 100k residents', fmt: money, short: money },
  aov: { label: 'Average order value', fmt: usd, short: v => '$' + Math.round(v) },
  yoy: { label: 'Revenue vs same months last year', fmt: v => pct(v), short: v => pct(v, 0) }
};

/* ---------- state ---------- */
const st = { view: 'map', metric: 'rev', range: 12, region: 'all', sel: null, sort: { k: 'rev', dir: -1 }, hoverM: null };
const inReg = s => st.region === 'all' || s.reg === st.region;
let V = [];
function compute() {
  const n = st.range, a = 24 - n, b = 12 - n;
  V = STATES.map(s => {
    let rev = 0, ord = 0, prev = 0;
    for (let m = a; m < 24; m++) { rev += s.rev[m]; ord += s.ord[m]; }
    for (let m = b; m < 12; m++) prev += s.rev[m];
    return { s, rev, ord, aov: rev / ord, pc: rev / (s.pop * 10), yoy: rev / prev - 1, prev };
  });
}
const valOf = v => v[st.metric];
let scale = null;
function makeScale() {
  const vis = V.filter(v => inReg(v.s)), xs = vis.map(valOf);
  const lo = Math.min(...xs), hi = Math.max(...xs);
  if (st.metric === 'yoy') {
    /* diverging around zero, each side stretched to its own extreme so small declines still read */
    const n = Math.min(lo, -0.01), p = Math.max(hi, 0.01);
    scale = { t: x => x < 0 ? 0.5 - 0.5 * x / n : 0.5 + 0.5 * x / p, inv: t => t < 0.5 ? (0.5 - t) * 2 * n : (t - 0.5) * 2 * p };
  } else if (st.metric === 'rev') {
    const l0 = Math.log(lo), l1 = Math.log(hi);
    scale = { t: x => (Math.log(x) - l0) / (l1 - l0 || 1), inv: t => Math.exp(l0 + t * (l1 - l0)) };
  } else scale = { t: x => (x - lo) / (hi - lo || 1), inv: t => lo + t * (hi - lo) };
}
const binOf = t => clamp(Math.floor(t * 5), 0, 4);

/* ---------- tile map ---------- */
const map = $('.dbe-regions-map'), mapwrap = $('.dbe-regions-mapwrap'), tip = $('.dbe-regions-tip', mapwrap);
const cx = 5.5, cy = 3.5;
map.innerHTML = STATES.map((s, i) => `<button class="dbe-regions-tile" data-i="${i}" tabindex="-1" aria-pressed="false" style="grid-row:${s.row + 1};grid-column:${s.col + 1};--c:${s.col};--d:${Math.hypot(s.col - cx, (s.row - cy) * 1.2).toFixed(2)};--t:0"><b>${s.code}</b><small></small></button>`).join('');
const tiles = $$('.dbe-regions-tile', map);
tiles[STATES.findIndex(s => s.code === 'CO')].tabIndex = 0;
function renderMap() {
  root.dataset.metric = st.metric;
  const fm = METRIC[st.metric].short;
  V.forEach((v, i) => {
    const el = tiles[i], t = clamp(scale.t(valOf(v)), 0, 1);
    el.style.setProperty('--t', t.toFixed(3));
    el.dataset.b = binOf(t);
    const dark = st.metric === 'yoy' ? t > 0.78 : t > 0.52;
    el.classList.toggle('is-dark', dark);
    el.classList.toggle('is-out', !inReg(v.s));
    el.setAttribute('aria-pressed', String(st.sel === i));
    $('small', el).textContent = fm(valOf(v));
    el.setAttribute('aria-label', `${v.s.name}: ${METRIC[st.metric].fmt(valOf(v))}`);
  });
  /* legend: five equal steps of the colour scale, labelled in data units */
  $('[data-f="legendtitle"]').textContent = METRIC[st.metric].label;
  $('.dbe-regions-bins').innerHTML = [0, 1, 2, 3, 4].map(b => {
    const v0 = scale.inv(b / 5), v1 = scale.inv((b + 1) / 5), f = METRIC[st.metric].short;
    const n = V.filter(v => inReg(v.s) && binOf(clamp(scale.t(valOf(v)), 0, 1)) === b).length;
    return `<li class="dbe-regions-bin" data-b="${b}" style="--t:${((b + 0.5) / 5).toFixed(2)}" title="${n} state${n === 1 ? '' : 's'}"><i></i><span>${b === 0 ? '< ' + f(v1) : b === 4 ? '≥ ' + f(v0) : f(v0) + (st.metric === 'yoy' ? ' to ' : '–') + f(v1)}</span></li>`;
  }).join('');
}
function rankOf(i) {
  const xs = V.filter(v => inReg(v.s)).sort((a, b) => valOf(b) - valOf(a));
  return xs.indexOf(V[i]) + 1;
}
function showTip(el) {
  const i = +el.dataset.i, v = V[i], m = st.metric;
  const row = (k, label, val) => `<p><span>${label}</span><em class="${k === m ? 'dbe-regions-hl' : ''}">${val}</em></p>`;
  tip.innerHTML = `<b>${v.s.name}</b>` + row('rev', 'Revenue', money(v.rev)) + row('ord', 'Orders', nf0.format(v.ord)) + row('aov', 'Avg order', usd(v.aov)) +
    row('pc', 'Per 100k people', money(v.pc)) + row('yoy', 'vs last year', pct(v.yoy)) +
    (inReg(v.s) ? `<p><span>Rank${st.region === 'all' ? '' : ' in ' + REG[st.region]}</span><em>${rankOf(i)} of ${V.filter(x => inReg(x.s)).length}</em></p>` : '');
  const r = el.getBoundingClientRect(), wr = mapwrap.getBoundingClientRect();
  placeTip(tip, mapwrap, r.left - wr.left + r.width / 2, r.top - wr.top);
}
map.addEventListener('pointerover', e => { const t = e.target.closest('.dbe-regions-tile'); if (t) showTip(t); });
map.addEventListener('pointerleave', () => { tip.hidden = true; });
map.addEventListener('focusin', e => { const t = e.target.closest('.dbe-regions-tile'); if (t) showTip(t); });
map.addEventListener('focusout', () => { tip.hidden = true; });
map.addEventListener('click', e => { const t = e.target.closest('.dbe-regions-tile'); if (t) select(+t.dataset.i === st.sel ? null : +t.dataset.i); });
/* arrow keys move to the nearest tile in that direction, so the grid behaves like a map */
map.addEventListener('keydown', e => {
  const t = e.target.closest('.dbe-regions-tile');
  if (!t) return;
  const d = { ArrowRight: [0, 1], ArrowLeft: [0, -1], ArrowDown: [1, 0], ArrowUp: [-1, 0] }[e.key];
  if (!d) return;
  e.preventDefault();
  const s = STATES[+t.dataset.i];
  let best = null, bd = Infinity;
  STATES.forEach((o, j) => {
    const dr = o.row - s.row, dc = o.col - s.col;
    const along = d[0] ? dr * d[0] : dc * d[1], across = d[0] ? Math.abs(dc) : Math.abs(dr);
    if (along <= 0) return;
    const score = along + across * 2.2;
    if (score < bd) { bd = score; best = j; }
  });
  if (best == null) return;
  tiles.forEach(x => { x.tabIndex = -1; });
  tiles[best].tabIndex = 0; tiles[best].focus();
});

/* ---------- rankings ---------- */
const tbody = $('.dbe-regions-table tbody');
function renderTable() {
  const k = st.sort.k;
  const key = k === 'name' ? null : k;
  const list = V.map((v, i) => [v, i]).filter(([v]) => inReg(v.s)).sort((a, b) => key ? (a[0][key] - b[0][key]) * st.sort.dir : a[0].s.name.localeCompare(b[0].s.name) * st.sort.dir);
  const cell = (m, txt) => `<td class="dbe-regions-r${st.metric === m ? ' is-m' : ''}${m === 'ord' || m === 'pc' ? ' dbe-regions-opt' : ''}">${txt}</td>`;
  tbody.innerHTML = list.map(([v, i], n) => `<tr data-i="${i}" tabindex="${(st.sel ?? list[0][1]) === i ? 0 : -1}" aria-selected="${st.sel === i}">` +
    `<td class="dbe-regions-r">${n + 1}</td><td><span class="dbe-regions-sname"><i style="--t:${clamp(scale.t(valOf(v)), 0, 1).toFixed(3)}"></i>${v.s.name}</span></td>` +
    cell('rev', money(v.rev)) + cell('ord', nf0.format(v.ord)) + cell('aov', usd(v.aov)) + cell('pc', money(v.pc)) +
    cell('yoy', `<span class="${v.yoy >= 0 ? 'dbe-regions-up' : 'dbe-regions-dn'}">${pct(v.yoy)}</span>`) + `</tr>`).join('');
  $$('.dbe-regions-table th[aria-sort]').forEach(th => { const b = $('button', th); th.setAttribute('aria-sort', b.dataset.sort === k ? (st.sort.dir > 0 ? 'ascending' : 'descending') : 'none'); });
}
$('.dbe-regions-table thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]');
  if (!b) return;
  const k = b.dataset.sort;
  st.sort = { k, dir: st.sort.k === k ? -st.sort.dir : k === 'name' ? 1 : -1 };
  renderTable();
});
tbody.addEventListener('click', e => { const r = e.target.closest('tr'); if (r) select(+r.dataset.i); });
tbody.addEventListener('keydown', e => {
  const r = e.target.closest('tr');
  if (!r) return;
  const rows = $$('tr', tbody), k = rows.indexOf(r);
  const j = { ArrowDown: k + 1, ArrowUp: k - 1, Home: 0, End: rows.length - 1 }[e.key];
  if (j != null) { e.preventDefault(); const n = rows[clamp(j, 0, rows.length - 1)]; rows.forEach(x => { x.tabIndex = -1; }); n.tabIndex = 0; n.focus(); }
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(+r.dataset.i); }
});

/* ---------- small multiples ---------- */
const multEl = $('.dbe-regions-multiples');
multEl.innerHTML = Object.entries(REG).map(([k, n], i) => `<button class="dbe-regions-mult" data-r="${k}" style="--i:${i}" aria-pressed="false"><header><h3>${n}</h3><span></span></header><svg aria-hidden="true"></svg></button>`).join('');
const regSeries = k => {
  const cur = new Array(12).fill(0), prev = new Array(12).fill(0);
  STATES.forEach(s => { if (s.reg !== k) return; for (let m = 0; m < 12; m++) { prev[m] += s.rev[m]; cur[m] += s.rev[m + 12]; } });
  return { cur, prev };
};
const SERIES = Object.fromEntries(Object.keys(REG).map(k => [k, regSeries(k)]));
let mGeo = {};
function renderMultiples(enter) {
  $$('.dbe-regions-mult', multEl).forEach(b => {
    const k = b.dataset.r, { cur, prev } = SERIES[k], svg = $('svg', b);
    const w = svg.clientWidth, h = svg.clientHeight;
    if (w < 40 || h < 40) return;
    const L = 40, Rr = 8, T = 8, B = 18, pw = w - L - Rr, ph = h - T - B;
    const sc = nice(Math.max(...cur, ...prev) * 1.05, 3);
    const X = m => L + m / 11 * pw, Y = v => T + ph - v / sc.top * ph;
    const path = a => a.map((v, m) => (m ? 'L' : 'M') + X(m).toFixed(1) + ',' + Y(v).toFixed(1)).join('');
    let g = '';
    for (let v = 0; v <= sc.top + 1e-6; v += sc.step) g += `<line class="dbe-regions-gl" x1="${L}" x2="${L + pw}" y1="${Y(v).toFixed(1)}" y2="${Y(v).toFixed(1)}"/><text x="${L - 6}" y="${(Y(v) + 3).toFixed(1)}" text-anchor="end">${money(v)}</text>`;
    [0, 3, 6, 9, 11].forEach(m => { g += `<text x="${X(m).toFixed(1)}" y="${h - 4}" text-anchor="${m === 0 ? 'start' : m === 11 ? 'end' : 'middle'}">${MON[m]}</text>`; });
    const win = 12 - st.range;
    if (win > 0) g += `<rect x="${X(win - 0.5).toFixed(1)}" y="${T}" width="${(X(11) - X(win - 0.5)).toFixed(1)}" height="${ph}" fill="var(--dbe-regions-sunk)"/>`;
    g += `<path class="dbe-regions-prev" d="${path(prev)}"/><path class="dbe-regions-area" d="${path(cur)}L${X(11)},${Y(0)}L${X(0)},${Y(0)}Z"/><path class="dbe-regions-cur" pathLength="1" d="${path(cur)}"/>`;
    g += `<g class="dbe-regions-hov" visibility="hidden"><line class="dbe-regions-xh" y1="${T}" y2="${T + ph}"/><circle class="dbe-regions-dot" r="4"/><text class="dbe-regions-val" text-anchor="middle"></text></g>`;
    svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
    svg.innerHTML = g;
    if (!enter) $$('.dbe-regions-cur', svg).forEach(p => { p.style.animation = 'none'; });
    mGeo[k] = { X, Y, L, pw, cur, prev };
    const a = st.range, ci = 12 - a;
    const tc = cur.slice(ci).reduce((x, y) => x + y, 0), tp = prev.slice(ci).reduce((x, y) => x + y, 0);
    $('header span', b).innerHTML = `<b>${money(tc)}</b> · ${pct(tc / tp - 1)}`;
    b.setAttribute('aria-pressed', String(st.region === k));
    b.setAttribute('aria-label', `${REG[k]}: ${money(tc)} over the last ${a} months, ${pct(tc / tp - 1)} on last year. Filter the map to ${REG[k]}.`);
  });
  syncHover();
}
function syncHover() {
  $$('.dbe-regions-mult', multEl).forEach(b => {
    const k = b.dataset.r, g = $('.dbe-regions-hov', b), geo = mGeo[k];
    if (!g || !geo) return;
    if (st.hoverM == null) { g.setAttribute('visibility', 'hidden'); return; }
    const m = st.hoverM, x = geo.X(m), y = geo.Y(geo.cur[m]);
    g.setAttribute('visibility', 'visible');
    $('line', g).setAttribute('x1', x); $('line', g).setAttribute('x2', x);
    $('circle', g).setAttribute('cx', x); $('circle', g).setAttribute('cy', y);
    const tx = $('text', g);
    tx.setAttribute('x', clamp(x, geo.L + 30, geo.L + geo.pw - 30)); tx.setAttribute('y', Math.max(14, y - 9));
    tx.textContent = `${MON[m]} ${money(geo.cur[m])} (${pct(geo.cur[m] / geo.prev[m] - 1, 0)})`;
  });
}
multEl.addEventListener('pointermove', e => {
  const b = e.target.closest('.dbe-regions-mult');
  if (!b) return;
  const geo = mGeo[b.dataset.r], r = $('svg', b).getBoundingClientRect();
  if (!geo) return;
  st.hoverM = clamp(Math.round((e.clientX - r.left - geo.L) / geo.pw * 11), 0, 11);
  syncHover();
});
multEl.addEventListener('pointerleave', () => { st.hoverM = null; syncHover(); });
multEl.addEventListener('click', e => {
  const b = e.target.closest('.dbe-regions-mult');
  if (!b) return;
  regionCtl.set(st.region === b.dataset.r ? 'all' : b.dataset.r);
});

/* ---------- detail panel ---------- */
const detail = $('.dbe-regions-detail');
const statsHTML = v => `<dl class="dbe-regions-stats" style="--i:1">` +
  `<div><dt>Revenue</dt><dd>${money(v.rev)}</dd></div><div><dt>Orders</dt><dd>${nf0.format(v.ord)}</dd></div>` +
  `<div><dt>Avg order</dt><dd>${usd(v.aov)}</dd></div><div><dt>Per 100k people</dt><dd>${money(v.pc)}</dd></div>` +
  `<div><dt>vs last year</dt><dd class="${v.yoy >= 0 ? 'dbe-regions-up' : 'dbe-regions-dn'}">${pct(v.yoy)}</dd></div><div><dt>Last year</dt><dd>${money(v.prev)}</dd></div></dl>`;
function renderDetail() {
  if (st.sel != null) {
    const v = V[st.sel], s = v.s, n = st.range;
    const months = s.rev.slice(24 - n), prev = s.rev.slice(12 - n, 12);
    const mx = Math.max(...months, ...prev);
    const bw = 100 / n;
    detail.innerHTML = `<div class="dbe-regions-dhead"><div><h3>${s.name}</h3><small>${REG[s.reg]} · #${rankOf(st.sel)} by ${METRIC[st.metric].label.toLowerCase()}</small></div>` +
      `<button class="dbe-regions-x" aria-label="Clear selection"><svg class="dbe-regions-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>` +
      statsHTML(v) +
      `<div style="--i:2"><h4>By month · bars this year, ticks last year</h4><div class="dbe-regions-months"><svg viewBox="0 0 100 60" preserveAspectRatio="none">` +
      months.map((m, k) => `<rect class="dbe-regions-mb" style="--i:${k}" x="${(k * bw + bw * 0.14).toFixed(2)}" y="${(52 - m / mx * 48).toFixed(2)}" width="${(bw * 0.72).toFixed(2)}" height="${(m / mx * 48).toFixed(2)}"><title>${MON[(12 - n + k) % 12]}: ${money(m)} (last year ${money(prev[k])})</title></rect>` +
        `<line class="dbe-regions-mp" vector-effect="non-scaling-stroke" x1="${(k * bw + bw * 0.08).toFixed(2)}" x2="${(k * bw + bw * 0.92).toFixed(2)}" y1="${(52 - prev[k] / mx * 48).toFixed(2)}" y2="${(52 - prev[k] / mx * 48).toFixed(2)}"/>`).join('') +
      `</svg></div><div style="display:flex;justify-content:space-between;font-size:10px;color:var(--dbe-regions-faint)"><span>${MON[(12 - n) % 12]}</span><span>Sep</span></div></div>` +
      `<div style="--i:3"><h4>Where it ships</h4><ol class="dbe-regions-cities">${s.cities.map((c, k) => `<li style="--i:${k};--w:${(s.split[k] / s.split[0]).toFixed(3)}"><span>${esc(c)}</span><span>${money(v.rev * s.split[k])} · ${(s.split[k] * 100).toFixed(0)}%</span><i></i></li>`).join('')}</ol></div>`;
    $('.dbe-regions-x', detail).addEventListener('click', () => select(null));
    return;
  }
  const vis = V.filter(v => inReg(v.s));
  const agg = vis.reduce((a, v) => ({ rev: a.rev + v.rev, ord: a.ord + v.ord, prev: a.prev + v.prev, pop: a.pop + v.s.pop }), { rev: 0, ord: 0, prev: 0, pop: 0 });
  const tot = { rev: agg.rev, ord: agg.ord, aov: agg.rev / agg.ord, pc: agg.rev / (agg.pop * 10), yoy: agg.rev / agg.prev - 1, prev: agg.prev };
  const top = vis.slice().sort((a, b) => valOf(b) - valOf(a)).slice(0, 6);
  detail.innerHTML = `<div class="dbe-regions-dhead"><div><h3>${st.region === 'all' ? 'United States' : REG[st.region]}</h3><small>${vis.length} states${st.region === 'all' ? ' and DC' : ''} · last ${st.range} months</small></div></div>` +
    statsHTML(tot) +
    `<div style="--i:2"><h4>Top by ${METRIC[st.metric].label.toLowerCase()}</h4><ol class="dbe-regions-toplist">${top.map((v, k) => `<li><button data-i="${V.indexOf(v)}"><span>${k + 1}</span><b>${v.s.name}</b><span>${METRIC[st.metric].fmt(valOf(v))}</span></button></li>`).join('')}</ol></div>` +
    `<p class="dbe-regions-hint" style="--i:3">Choose a state on the map or in the rankings for its months and cities.</p>`;
}
detail.addEventListener('click', e => { const b = e.target.closest('.dbe-regions-toplist button'); if (b) select(+b.dataset.i); });

/* ---------- headline ---------- */
const PER = { 3: 'Jul – Sep 2026', 6: 'Apr – Sep 2026', 12: 'Oct 2025 – Sep 2026' };
function renderHead() {
  const vis = V.filter(v => inReg(v.s));
  const rev = vis.reduce((a, v) => a + v.rev, 0), prev = vis.reduce((a, v) => a + v.prev, 0);
  const by = k => vis.slice().sort((a, b) => b[k] - a[k])[0];
  const where = st.region === 'all' ? '' : ' in the ' + REG[st.region];
  let h;
  if (st.metric === 'rev') { const t = by('rev'); h = `<em>${money(rev)}</em>${where}; ${t.s.name} alone is <em>${(t.rev / rev * 100).toFixed(0)}%</em>`; }
  else if (st.metric === 'pc') { const t = by('pc'); h = `${t.s.name} buys the most per resident: <em>${money(t.pc)}</em> per 100k`; }
  else if (st.metric === 'aov') { const t = by('aov'); h = `Average order <em>${usd(rev / vis.reduce((a, v) => a + v.ord, 0))}</em>${where}, highest in ${t.s.name}`; }
  else { const t = by('yoy'); h = `<em>${pct(rev / prev - 1)}</em> on last year${where}; ${t.s.name} grew fastest at <em>${pct(t.yoy, 0)}</em>`; }
  $('[data-f="headline"]').innerHTML = h;
  $('[data-f="period"]').textContent = PER[st.range] + ' · against the same months a year earlier';
  Object.keys(REG).concat('all').forEach(k => {
    const r = V.filter(v => k === 'all' || v.s.reg === k).reduce((a, v) => a + v.rev, 0);
    $(`[data-r="${k}"]`).textContent = money(r);
  });
}

/* ---------- controls ---------- */
function select(i) {
  st.sel = i;
  tiles.forEach((t, j) => t.setAttribute('aria-pressed', String(j === i)));
  if (i != null) { tiles.forEach(t => { t.tabIndex = -1; }); tiles[i].tabIndex = 0; }
  $$('tr', tbody).forEach(r => r.setAttribute('aria-selected', String(+r.dataset.i === i)));
  renderDetail();
}
function renderAll(enter) {
  compute(); makeScale();
  if (st.sel != null && !inReg(V[st.sel].s)) st.sel = null;
  renderHead(); renderMap();
  if (st.view === 'rank') renderTable();
  if (st.view === 'trend') renderMultiples(enter);
  renderDetail();
}
const views = $$('.dbe-regions-view'), tabs = $$('.dbe-regions-tab');
tabs.forEach((t, k) => { const a = uid('t' + k), b = uid('p' + k); t.id = a; t.setAttribute('aria-controls', b); views[k].id = b; views[k].setAttribute('aria-labelledby', a); });
roving($('.dbe-regions-nav'), '.dbe-regions-tab', 'aria-selected', v => {
  st.view = v;
  views.forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'rank') renderTable();
  if (v === 'trend') requestAnimationFrame(() => { if (!root.isConnected) return; renderMultiples(true); });
});
roving($('[data-g="metric"]'), '[role="radio"]', 'aria-checked', v => { st.metric = v; if (st.sort.k !== 'name') st.sort = { k: v, dir: -1 }; renderAll(false); });
roving($('[data-g="range"]'), '[role="radio"]', 'aria-checked', v => { st.range = +v; renderAll(false); });
const regionCtl = roving($('.dbe-regions-reglist'), '[role="radio"]', 'aria-checked', v => { st.region = v; renderAll(false); });
root.addEventListener('keydown', e => { if (e.key === 'Escape' && st.sel != null) { const i = st.sel; select(null); if (st.view === 'map') tiles[i].focus(); } });
new ResizeObserver(() => { if (st.view === 'trend') requestAnimationFrame(() => { if (!root.isConnected) return; renderMultiples(false); }); }).observe(multEl);

renderAll(true);

css:
.dbe-basket {
  width: 100%;
  height: var(--dbe-basket-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-basket-line);
  border-radius: 14px;
  background: var(--dbe-basket-bg);
  color: var(--dbe-basket-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-basket-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-basket-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-basket-num { font-variant-numeric: tabular-nums; }
  & .dbe-basket-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-basket-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-basket-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-basket-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-basket-line-2) transparent; }
  & .dbe-basket-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  & .dbe-basket-scroll::-webkit-scrollbar-thumb { background: var(--dbe-basket-line-2); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  & .dbe-basket-scroll::-webkit-scrollbar-track { background: transparent; }
}

@keyframes dbe-basket-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbe-basket-grow { from { transform: scaleY(0); } }
@keyframes dbe-basket-wide { from { transform: scaleX(0); } }
@keyframes dbe-basket-cell { from { opacity: 0; transform: scale(0.6); } }
@keyframes dbe-basket-nudge { 0%, 100% { transform: translateX(0); } 40% { transform: translateX(-3px); } 70% { transform: translateX(3px); } }

/* the net-contribution figure tints toward gain or loss through a registered hue */
@property --dbe-basket-tone {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

.dbe-basket {
  /* re-theme with these four */
  --dbe-basket-bg: oklch(0.972 0.012 80);
  --dbe-basket-ink: oklch(0.29 0.04 168);
  --dbe-basket-accent: oklch(0.5 0.13 352);
  --dbe-basket-good: oklch(0.55 0.11 155);
  /* derived */
  --dbe-basket-bad: oklch(0.58 0.15 35);
  --dbe-basket-card: color-mix(in oklch, var(--dbe-basket-bg), white 58%);
  --dbe-basket-sunk: color-mix(in oklch, var(--dbe-basket-bg), var(--dbe-basket-ink) 5%);
  --dbe-basket-line: color-mix(in oklch, var(--dbe-basket-ink) 12%, transparent);
  --dbe-basket-line-2: color-mix(in oklch, var(--dbe-basket-ink) 24%, transparent);
  --dbe-basket-muted: color-mix(in oklch, var(--dbe-basket-ink) 64%, var(--dbe-basket-bg));
  --dbe-basket-faint: color-mix(in oklch, var(--dbe-basket-ink) 38%, var(--dbe-basket-bg));
  --dbe-basket-c0: oklch(0.72 0.065 160);
  --dbe-basket-c1: oklch(0.52 0.12 352);
  --dbe-basket-c2: oklch(0.8 0.11 86);
  --dbe-basket-c3: oklch(0.6 0.075 230);
  --dbe-basket-c4: oklch(0.67 0.12 45);
  --dbe-basket-c5: oklch(0.42 0.06 170);
  --dbe-basket-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbe-basket-spring: linear(0, 0.014, 0.055 2.5%, 0.21 5.4%, 0.79 14.2%, 0.97 18.6%, 1.045 23%, 1.065 27.4%, 1.05 32%, 1.01 43%, 0.996 54%, 1);
  --dbe-basket-tone: 0;
  transition: --dbe-basket-tone 600ms var(--dbe-basket-ease);

  .dbe-basket-eyebrow { margin: 0; font-size: 10.5px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbe-basket-muted); }

  /* ---------- shell: top bar, no sidebar ---------- */
  .dbe-basket-app { display: grid; height: 100%; grid-template-rows: auto minmax(0, 1fr); }
  .dbe-basket-top {
    display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px 20px;
    padding: 12px 18px; border-bottom: 1px solid var(--dbe-basket-line);
    background: var(--dbe-basket-card);
  }
  .dbe-basket-brand { display: flex; align-items: center; gap: 10px; }
  .dbe-basket-brand svg { width: 34px; height: 34px; padding: 6px; border-radius: 50% 50% 46% 46%; background: var(--dbe-basket-ink); color: var(--dbe-basket-bg); fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  .dbe-basket-brand span { display: grid; line-height: 1.15; }
  .dbe-basket-brand b { font-weight: 700; letter-spacing: -0.01em; font-size: 14px; }
  .dbe-basket-brand small { font-size: 11.5px; color: var(--dbe-basket-muted); }
  .dbe-basket-tabs { display: flex; gap: 4px; justify-self: center; }
  .dbe-basket-tab {
    position: relative; display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px; border-radius: 99px;
    color: var(--dbe-basket-muted); font-weight: 600;
    transition: color 160ms var(--dbe-basket-ease), background-color 160ms var(--dbe-basket-ease);
    &:hover { color: var(--dbe-basket-ink); background: var(--dbe-basket-sunk); }
    &[aria-selected="true"] { color: var(--dbe-basket-bg); background: var(--dbe-basket-ink); }
  }
  .dbe-basket-filters { display: flex; gap: 8px; }
  .dbe-basket-seg {
    display: inline-flex; padding: 3px; gap: 2px; border-radius: 99px; background: var(--dbe-basket-sunk);
    & button { height: 26px; padding: 0 11px; border-radius: 99px; font-size: 12px; font-weight: 650; color: var(--dbe-basket-muted); transition: background-color 160ms var(--dbe-basket-ease), color 160ms var(--dbe-basket-ease); }
    & button:hover { color: var(--dbe-basket-ink); }
    & button[aria-checked="true"] { background: var(--dbe-basket-card); color: var(--dbe-basket-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--dbe-basket-ink) 18%, transparent); }
  }

  .dbe-basket-main { min-height: 0; padding: 16px 18px 18px; }
  .dbe-basket-view {
    height: 100%; display: grid; gap: 14px;
    grid-template-columns: minmax(0, 1fr) clamp(250px, 27cqi, 300px);
    grid-template-areas: "chart side";
    animation: dbe-basket-rise 400ms var(--dbe-basket-ease) both;
  }
  .dbe-basket-chartcard { grid-area: chart; display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; padding: 16px 18px 12px; border-radius: 16px; background: var(--dbe-basket-card); border: 1px solid var(--dbe-basket-line); }
  .dbe-basket-chead { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px 20px; flex-wrap: wrap; }
  .dbe-basket-chead > div { display: grid; gap: 4px; max-width: 58ch; }
  .dbe-basket-h { font-size: clamp(18px, 0.85rem + 0.9cqi, 24px); font-weight: 720; letter-spacing: -0.025em; line-height: 1.12; }
  .dbe-basket-sub { font-size: 12.5px; color: var(--dbe-basket-muted); }
  .dbe-basket-sub b { color: var(--dbe-basket-ink); font-weight: 650; }
  .dbe-basket-key { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--dbe-basket-muted); max-width: 360px; }
  .dbe-basket-key li { display: inline-flex; align-items: center; gap: 6px; }
  .dbe-basket-key i { width: 12px; height: 10px; border-radius: 2px; background: var(--c, var(--dbe-basket-faint)); }
  .dbe-basket-k-obs { background: color-mix(in oklch, var(--dbe-basket-ink) 22%, var(--dbe-basket-card)) !important; }
  .dbe-basket-k-proj { background: none !important; border: 2px solid var(--dbe-basket-accent); height: 10px; }

  /* ---------- histogram + draggable threshold ---------- */
  .dbe-basket-hist { position: relative; min-height: 0; margin-top: 8px; touch-action: none; user-select: none; }
  .dbe-basket-hsvg { position: absolute; inset: 0; width: 100%; height: 100%; font-size: 10.5px; font-variant-numeric: tabular-nums; cursor: ew-resize; }
  .dbe-basket-hsvg text { fill: var(--dbe-basket-muted); }
  .dbe-basket-hsvg .dbe-basket-gl { stroke: var(--dbe-basket-line); }
  .dbe-basket-hsvg .dbe-basket-bar { fill: color-mix(in oklch, var(--dbe-basket-ink) 22%, var(--dbe-basket-card)); transition: fill 140ms; }
  .dbe-basket-hsvg .dbe-basket-bar.is-free { fill: color-mix(in oklch, var(--dbe-basket-good) 50%, var(--dbe-basket-card)); }
  .dbe-basket-hsvg .dbe-basket-bar.is-zone { fill: color-mix(in oklch, var(--dbe-basket-accent) 35%, var(--dbe-basket-card)); }
  .dbe-basket-hsvg .dbe-basket-bar.is-hot { fill: var(--dbe-basket-ink); }
  .dbe-basket-hsvg.is-enter .dbe-basket-bar { transform-box: fill-box; transform-origin: bottom; animation: dbe-basket-grow 620ms var(--dbe-basket-ease) both; animation-delay: calc(var(--i) * 14ms); }
  .dbe-basket-hsvg .dbe-basket-proj { fill: none; stroke: var(--dbe-basket-accent); stroke-width: 2; stroke-linejoin: round; }
  .dbe-basket-hsvg .dbe-basket-zone { fill: color-mix(in oklch, var(--dbe-basket-accent) 7%, transparent); }
  .dbe-basket-hsvg .dbe-basket-zonelabel { fill: var(--dbe-basket-accent); font-weight: 650; }
  .dbe-basket-hsvg .dbe-basket-cur { stroke: var(--dbe-basket-ink); stroke-width: 1; stroke-dasharray: 2 3; }
  .dbe-basket-handle {
    position: absolute; top: 0; bottom: 22px; left: 0; width: 22px; margin-left: -11px;
    transform: translateX(var(--x, 0px)); cursor: ew-resize; outline: none;
    &::before { content: ""; position: absolute; left: 10px; top: 0; bottom: 0; width: 2px; border-radius: 2px; background: var(--dbe-basket-accent); }
    &::after { content: ""; position: absolute; left: 4px; bottom: -6px; width: 14px; height: 14px; border-radius: 50%; background: var(--dbe-basket-accent); box-shadow: 0 0 0 3px var(--dbe-basket-card); transition: transform 200ms var(--dbe-basket-spring); }
    &:hover::after, &.is-drag::after { transform: scale(1.25); }
    &:focus-visible::after { box-shadow: 0 0 0 3px var(--dbe-basket-card), 0 0 0 5px var(--dbe-basket-accent); }
    &.is-bump { animation: dbe-basket-nudge 360ms var(--dbe-basket-ease); }
  }
  .dbe-basket-hlabel {
    position: absolute; top: 0; left: 16px; white-space: nowrap;
    padding: 4px 8px; border-radius: 7px; background: var(--dbe-basket-accent); color: oklch(0.98 0.01 350);
    font-size: 11.5px; font-weight: 600; font-variant-numeric: tabular-nums;
    & b { font-weight: 800; }
  }
  .dbe-basket-handle.is-flip .dbe-basket-hlabel { left: auto; right: 16px; }

  .dbe-basket-tip {
    position: absolute; left: 0; top: 0; z-index: 6; pointer-events: none;
    min-width: 176px; padding: 9px 11px; border-radius: 10px;
    background: var(--dbe-basket-ink); color: var(--dbe-basket-bg);
    box-shadow: 0 14px 32px -12px color-mix(in oklch, var(--dbe-basket-ink) 70%, transparent);
    font-size: 12px; font-variant-numeric: tabular-nums;
    & b { display: block; font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; opacity: 0.7; margin-bottom: 4px; }
    & p { display: flex; justify-content: space-between; gap: 14px; }
    & p span { opacity: 0.78; display: inline-flex; align-items: center; gap: 6px; }
    & p i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
    & p em { font-style: normal; font-weight: 650; }
  }

  /* ---------- scenario panel ---------- */
  .dbe-basket-scen {
    grid-area: side; min-height: 0; overflow: auto;
    display: grid; align-content: start; gap: 14px;
    padding: 16px; border-radius: 16px;
    background: var(--dbe-basket-sunk);
    scrollbar-width: thin; scrollbar-color: var(--dbe-basket-line-2) transparent;
  }
  .dbe-basket-big {
    display: grid; gap: 2px; padding: 12px 14px; border-radius: 12px;
    background: color-mix(in oklch, var(--dbe-basket-good) calc(max(0, var(--dbe-basket-tone)) * 22%), color-mix(in oklch, var(--dbe-basket-bad) calc(max(0, -1 * var(--dbe-basket-tone)) * 22%), var(--dbe-basket-card)));
    & span { font-size: 12px; color: var(--dbe-basket-muted); font-weight: 600; }
    & output { font-size: clamp(24px, 1rem + 1.6cqi, 34px); font-weight: 760; letter-spacing: -0.035em; line-height: 1.05; font-variant-numeric: tabular-nums; }
    & small { font-size: 11.5px; color: var(--dbe-basket-muted); text-wrap: pretty; }
  }
  .dbe-basket-rows { margin: 0; display: grid; gap: 0; }
  .dbe-basket-rows div { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--dbe-basket-line); }
  .dbe-basket-rows dt { font-size: 12.5px; color: var(--dbe-basket-muted); }
  .dbe-basket-rows dd { margin: 0; display: grid; justify-items: end; line-height: 1.2; }
  .dbe-basket-rows output { font-weight: 700; font-variant-numeric: tabular-nums; font-size: 14px; }
  .dbe-basket-rows small { font-size: 11px; font-variant-numeric: tabular-nums; color: var(--dbe-basket-muted); }
  .dbe-basket-pos { color: var(--dbe-basket-good) !important; }
  .dbe-basket-neg { color: var(--dbe-basket-bad) !important; }
  .dbe-basket-range {
    display: grid; gap: 6px;
    & span { display: flex; justify-content: space-between; gap: 8px; font-size: 12px; font-weight: 600; }
    & output { font-weight: 750; font-variant-numeric: tabular-nums; }
    & input { width: 100%; margin: 0; }
    & small { font-size: 11px; color: var(--dbe-basket-muted); }
    & small b { color: var(--dbe-basket-ink); }
  }
  .dbe-basket-presets { display: flex; gap: 6px; }
  .dbe-basket-presets button {
    flex: 1; height: 30px; border-radius: 8px; font-weight: 650; font-size: 12.5px; font-variant-numeric: tabular-nums;
    background: var(--dbe-basket-card); box-shadow: inset 0 0 0 1px var(--dbe-basket-line);
    transition: background-color 160ms var(--dbe-basket-ease), color 160ms, transform 220ms var(--dbe-basket-spring);
    &:hover { box-shadow: inset 0 0 0 1px var(--dbe-basket-line-2); }
    &:active { transform: scale(0.95); }
    &[aria-pressed="true"] { background: var(--dbe-basket-accent); color: oklch(0.98 0.01 350); box-shadow: none; }
  }

  /* ---------- mix ---------- */
  .dbe-basket-mixplot { position: relative; min-height: 0; margin-top: 10px; }
  .dbe-basket-msvg { position: absolute; inset: 0; width: 100%; height: 100%; font-size: 11px; font-variant-numeric: tabular-nums; }
  .dbe-basket-msvg text { fill: var(--dbe-basket-muted); }
  .dbe-basket-msvg .dbe-basket-blabel { fill: var(--dbe-basket-ink); font-weight: 650; }
  .dbe-basket-msvg .dbe-basket-seg2 { transition: opacity 140ms; }
  .dbe-basket-msvg:has(.dbe-basket-seg2:hover) .dbe-basket-seg2:not(:hover) { opacity: 0.45; }
  .dbe-basket-msvg.is-enter .dbe-basket-col { transform-box: fill-box; transform-origin: left; animation: dbe-basket-wide 700ms var(--dbe-basket-ease) both; animation-delay: calc(var(--i) * 70ms); }
  .dbe-basket-catkey i { background: var(--c); }
  .dbe-basket-ipo { display: grid; gap: 8px; }
  .dbe-basket-ipo li { display: grid; grid-template-columns: 54px minmax(0, 1fr) 48px; align-items: center; gap: 10px; font-size: 12.5px; font-variant-numeric: tabular-nums; }
  .dbe-basket-ipo li span:last-child { text-align: right; font-weight: 650; }
  .dbe-basket-ipo li i { height: 14px; border-radius: 3px; background: var(--dbe-basket-ink); width: calc(var(--w) * 100%); transform-origin: left; animation: dbe-basket-wide 600ms var(--dbe-basket-ease) both; animation-delay: calc(var(--i) * 60ms); }
  .dbe-basket-note { font-size: 12px; color: var(--dbe-basket-muted); }
  .dbe-basket-note b { color: var(--dbe-basket-ink); }

  /* ---------- pairs ---------- */
  .dbe-basket-matrixwrap { position: relative; min-height: 0; margin-top: 12px; overflow: auto; }
  .dbe-basket-matrix { display: grid; grid-template-columns: 112px repeat(6, minmax(44px, 1fr)); gap: 4px; min-width: 420px; }
  .dbe-basket-mrow { display: contents; }
  .dbe-basket-mh { font-size: 11px; font-weight: 650; color: var(--dbe-basket-muted); display: flex; align-items: end; justify-content: center; text-align: center; padding-bottom: 4px; line-height: 1.15; }
  .dbe-basket-mh.is-row { justify-content: flex-start; align-items: center; text-align: left; padding: 0; }
  .dbe-basket-mh i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; background: var(--c); margin-right: 6px; flex: none; }
  .dbe-basket-mc {
    aspect-ratio: 1.6; min-height: 34px; border-radius: 7px; display: grid; place-items: center;
    font-size: 12px; font-weight: 650; font-variant-numeric: tabular-nums;
    background: color-mix(in oklch, var(--dbe-basket-accent) calc(max(0, var(--l)) * 100%), color-mix(in oklch, var(--dbe-basket-sunk) calc(max(0, -1 * var(--l)) * 100%), var(--dbe-basket-card)));
    color: color-mix(in oklch, var(--dbe-basket-ink) calc(100% - max(0, -1 * var(--l)) * 45%), var(--dbe-basket-card));
    transition: transform 200ms var(--dbe-basket-spring), box-shadow 160ms;
    animation: dbe-basket-cell 520ms var(--dbe-basket-spring) both; animation-delay: calc((var(--r) + var(--c2)) * 30ms);
    &.is-dark { color: oklch(0.98 0.01 350); }
    &.is-diag { background: repeating-linear-gradient(135deg, var(--dbe-basket-sunk) 0 4px, transparent 4px 8px); color: var(--dbe-basket-faint); font-weight: 500; }
    &:hover, &:focus-visible { transform: scale(1.06); box-shadow: 0 6px 16px -8px color-mix(in oklch, var(--dbe-basket-ink) 60%, transparent); outline: none; }
    &[aria-selected="true"] { box-shadow: 0 0 0 2px var(--dbe-basket-card), 0 0 0 4px var(--dbe-basket-ink); }
  }
  .dbe-basket-pairside h3 { font-size: 15px; font-weight: 720; letter-spacing: -0.015em; }
  .dbe-basket-pairside p { font-size: 12px; color: var(--dbe-basket-muted); }
  .dbe-basket-pairlist { display: grid; gap: 8px; }
  .dbe-basket-pairlist li { display: grid; gap: 4px; padding: 9px 10px; border-radius: 10px; background: var(--dbe-basket-card); animation: dbe-basket-rise 400ms var(--dbe-basket-ease) both; animation-delay: calc(var(--i) * 50ms); }
  .dbe-basket-pairlist b { font-size: 12.5px; font-weight: 650; line-height: 1.3; }
  .dbe-basket-pairlist span { font-size: 11.5px; color: var(--dbe-basket-muted); font-variant-numeric: tabular-nums; }

  /* ---------- container responses ---------- */
  @container (max-width: 1000px) {
    .dbe-basket-top { grid-template-columns: auto 1fr; }
    .dbe-basket-tabs { justify-self: end; }
    .dbe-basket-filters { grid-column: 1 / -1; justify-content: flex-end; }
  }
  @container (max-width: 860px) {
    .dbe-basket-view { height: auto; grid-template-columns: minmax(0, 1fr); grid-template-areas: "chart" "side"; }
    .dbe-basket-chartcard { height: 400px; }
    .dbe-basket-v-pairs .dbe-basket-chartcard { height: auto; }
    .dbe-basket-scen { overflow: visible; }
  }
  @container (max-width: 760px) {
    .dbe-basket-top { grid-template-columns: minmax(0, 1fr); padding: 10px 12px; }
    .dbe-basket-tabs { justify-self: stretch; overflow-x: auto; scrollbar-width: none; }
    .dbe-basket-tab { flex: none; }
    .dbe-basket-filters { justify-content: space-between; }
    .dbe-basket-main { padding: 12px; }
    .dbe-basket-chartcard { padding: 12px; }
  }
  @container (max-width: 460px) {
    .dbe-basket-brand small { display: none; }
    .dbe-basket-tab span { display: none; }
    .dbe-basket-tab[aria-selected="true"] span { display: inline; }
    .dbe-basket-chartcard { height: 360px; }
    .dbe-basket-hlabel { font-size: 10.5px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .dbe-basket { transition: none; }
  .dbe-basket *, .dbe-basket *::before, .dbe-basket *::after { animation: none !important; transition-duration: 0.01ms !important; transition-delay: 0s !important; }
}

