/* ---------- catalogue ---------- */
const CATS = ['Cleansers', 'Serums', 'Moisturisers', 'Body & bath', 'Candles & home', 'Gift sets'];
const P = [
  ['Sea fennel gel cleanser', 0, 24], ['Oat milk cleansing balm', 0, 32], ['Kelp clay mask', 0, 28],
  ['Marsh mallow hydrating serum', 1, 46], ['Vitamin C brightening drops', 1, 52], ['Retinal night serum', 1, 58],
  ['Saltmarsh day cream', 2, 38], ['Barrier repair balm', 2, 34], ['Mineral SPF 30 lotion', 2, 30],
  ['Seaweed bath salts', 3, 22], ['Driftwood body oil', 3, 36], ['Rosemary hand wash', 3, 18],
  ['Tide pool candle', 4, 42], ['Linen room mist', 4, 26],
  ['Weekend kit', 5, 64], ['The full ritual', 5, 118]
].map(([n, c, p]) => ({ n, c, p }));
const BYCAT = CATS.map((_, c) => P.map((x, i) => [x, i]).filter(([x]) => x.c === c).map(([, i]) => i));
const TOPUP = [11, 9, 0, 13]; // cheapest add-ons, ascending
const LINE = 60, ZONE = 18, FEE = 6.95, COST = 7.4, MARGIN = 0.68;
/* how strongly a basket that starts in one category pulls in each other one */
const AFF = [
  [0.4, 1.8, 3.2, 0.5, 0.3, 0.25],
  [1.8, 0.3, 3.4, 0.4, 0.3, 0.3],
  [3.0, 3.2, 0.3, 0.6, 0.3, 0.25],
  [0.5, 0.3, 0.6, 0.6, 3.0, 0.8],
  [0.3, 0.3, 0.3, 3.2, 0.5, 2.2],
  [0.3, 0.4, 0.3, 1.0, 2.6, 0.2]
];

/* ---------- a year of orders, Oct 2025 to Oct 2026 ---------- */
const R = rng(60601);
const DAYS = 365, END = Date.UTC(2026, 9, 2);
const MONTHF = [0.8, 0.82, 0.9, 0.95, 1.0, 0.94, 0.9, 0.92, 1.0, 1.12, 1.62, 1.84]; // Jan..Dec
const ORDERS = [];
for (let d = 0; d < DAYS; d++) {
  const dt = new Date(END - (DAYS - 1 - d) * 864e5), mo = dt.getUTCMonth(), wd = dt.getUTCDay();
  const n = Math.round(30 * MONTHF[mo] * (wd === 0 ? 1.15 : wd === 6 ? 1.05 : 0.97) * (0.85 + R() * 0.3));
  const giftW = mo === 10 || mo === 11 ? 0.22 : 0.07;
  const W = [0.2, 0.19, 0.21, 0.21, 0.1, giftW];
  for (let k = 0; k < n; k++) {
    const app = R() < 0.36;
    const u = R();
    let items = app ? (u < 0.45 ? 1 : u < 0.78 ? 2 : u < 0.93 ? 3 : 4) : (u < 0.36 ? 1 : u < 0.67 ? 2 : u < 0.86 ? 3 : u < 0.95 ? 4 : 5);
    const list = [];
    let first = -1;
    for (let i = 0; i < items; i++) {
      /* later items lean toward categories that pair with the first one (a regimen, a bath ritual, a gift) */
      const w = first < 0 ? W : W.map((x, c) => x * AFF[first][c]);
      let x = R() * w.reduce((a, v) => a + v, 0), c = 0;
      while (c < 5 && x > w[c]) { x -= w[c]; c++; }
      if (first < 0) first = c;
      list.push(BYCAT[c][Math.floor(R() * BYCAT[c].length)]);
    }
    const nat = list.reduce((a, i) => a + P[i].p, 0);
    let obs = nat, topped = -1;
    /* at today's $60 line, some baskets just under it add the cheapest item that clears it */
    if (nat >= LINE - ZONE && nat < LINE && R() < 0.38) {
      topped = TOPUP.find(i => nat + P[i].p >= LINE);
      list.push(topped); obs = nat + P[topped].p;
    }
    ORDERS.push({ d, ch: app ? 'app' : 'web', items: list, nat, obs, topped });
  }
}

/* ---------- formatting ---------- */
const nf0 = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const usd = v => (v < 0 ? '−$' : '$') + Math.abs(v).toFixed(2);
const usd0 = v => (v < 0 ? '−$' : '$') + nf0.format(Math.abs(Math.round(v)));
const sgn = (v, f) => (v > 0 ? '+' : v < 0 ? '−' : '±') + f(Math.abs(v));
const pct = v => (v * 100).toFixed(1) + '%';

/* ---------- state ---------- */
const st = { view: 'ship', ch: 'all', range: 90, T: 75, p: 0.38, cell: null, hoverBin: null };
let F = [];
const filter = () => { const from = DAYS - st.range; F = ORDERS.filter(o => o.d >= from && (st.ch === 'all' || o.ch === st.ch)); };

/* ---------- threshold scenario ---------- */
function observedP() {
  let zone = 0, up = 0;
  for (const o of F) if (o.nat >= LINE - ZONE && o.nat < LINE) { zone++; if (o.topped >= 0) up++; }
  return zone ? up / zone : 0;
}
function overshoot() {
  let s = 0, n = 0;
  for (const o of F) if (o.topped >= 0) { s += o.obs - LINE; n++; }
  return n ? s / n : 6;
}
function scenario(T, p) {
  const over = overshoot();
  let merch = 0, free = 0, paid = 0, nudged = 0;
  for (const o of F) {
    const v = o.nat;
    if (v >= T) { merch += v; free++; }
    else if (v >= T - ZONE) { merch += (1 - p) * v + p * (T + over); free += p; paid += 1 - p; nudged += p; }
    else { merch += v; paid++; }
  }
  const N = F.length;
  return { N, merch, aov: merch / N, free: free / N, paid, nudged, ship: paid * FEE - N * COST, contrib: merch * MARGIN + paid * FEE - N * COST, over };
}
function current() {
  const N = F.length;
  let merch = 0, free = 0, nudged = 0;
  for (const o of F) { merch += o.obs; if (o.obs >= LINE) free++; if (o.topped >= 0) nudged++; }
  const paid = N - free;
  return { N, merch, aov: merch / N, free: free / N, paid, nudged, ship: paid * FEE - N * COST, contrib: merch * MARGIN + paid * FEE - N * COST };
}

/* ---------- histogram ---------- */
const hist = $('.dbe-basket-hist'), hsvg = $('.dbe-basket-hsvg'), handle = $('.dbe-basket-handle'), htip = $('.dbe-basket-tip', hist);
