  s += `<rect class="dbe-basket-zone" x="${X(st.T - ZONE).toFixed(1)}" y="${T0}" width="${(X(st.T) - X(st.T - ZONE)).toFixed(1)}" height="${ph}"/>`;
  s += `<text class="dbe-basket-zonelabel" x="${((X(st.T - ZONE) + X(st.T)) / 2).toFixed(1)}" y="${T0 + 12}" text-anchor="middle">nudge zone</text>`;
  for (let b = 0; b < NB; b++) {
    const lo = b * BIN, cls = lo >= st.T ? ' is-free' : lo + BIN > st.T - ZONE ? ' is-zone' : '';
