  $('[data-f="ipo"]').innerHTML = `<b>${avgItems.toFixed(2)}</b> items per order. Top-ups add an item to <b>${pct(topped / F.length)}</b> of orders` + (best ? `; the usual add-on is the ${P[best[0]].n.toLowerCase()} at $${P[best[0]].p}.` : '.');
