msvg.addEventListener('pointermove', e => {
  const seg = e.target.closest('.dbe-basket-seg2');
  if (!seg || !mGeo) { mtip.hidden = true; return; }
  const r = mGeo[+seg.dataset.k], c = +seg.dataset.c, sum = r.v.reduce((a, b) => a + b, 0);
  mtip.innerHTML = `<b>${r.label}</b><p><span><i style="--c:var(--dbe-basket-c${c})"></i>${CATS[c]}</span><em>${usd0(r.v[c])}</em></p><p><span>Share of band</span><em>${pct(r.v[c] / sum)}</em></p>`;
  const mr = mix.getBoundingClientRect();
