msvg.addEventListener('pointerleave', () => { mtip.hidden = true; });
new ResizeObserver(es => { const r = es[0].contentRect; mw = r.width; mh = r.height; if (st.view === 'mix') later(() => drawMix(false)); }).observe(mix);

/* ---------- bought together ---------- */
const matrix = $('.dbe-basket-matrix'), mxwrap = $('.dbe-basket-matrixwrap'), xtip = $('.dbe-basket-tip', mxwrap), side = $('.dbe-basket-pairside');
let PM = null;
function pairData() {
  const N = F.length, cnt = new Float64Array(6), both = Array.from({ length: 6 }, () => new Float64Array(6)), solo = new Float64Array(6);
