}
function drawPairs() {
  PM = pairData();
  let best = null;
  let h = `<div class="dbe-basket-mrow" role="row"><span class="dbe-basket-mh" role="columnheader"></span>${CATS.map((c, j) => `<span class="dbe-basket-mh" role="columnheader"><i style="--c:var(--dbe-basket-c${j})"></i>${c.split(' ')[0]}</span>`).join('')}</div>`;
  CATS.forEach((ca, a) => {
    h += `<div class="dbe-basket-mrow" role="row"><span class="dbe-basket-mh is-row" role="rowheader"><i style="--c:var(--dbe-basket-c${a})"></i>${ca}</span>`;
    CATS.forEach((cb, b) => {
      if (a === b) { h += `<span class="dbe-basket-mc is-diag" role="gridcell" tabindex="-1" data-a="${a}" data-b="${b}" style="--r:${a};--c2:${b};--l:0">solo ${Math.round(PM.solo[a] / (PM.cnt[a] || 1) * 100)}%</span>`; return; }
      const l = PM.lift(a, b), t = clamp((l - 1) / 1.1, -1, 1);
      if (!best || l > best[2]) best = [a, b, l];
      h += `<span class="dbe-basket-mc${t > 0.55 ? ' is-dark' : ''}" role="gridcell" tabindex="-1" aria-selected="false" data-a="${a}" data-b="${b}" style="--r:${a};--c2:${b};--l:${t.toFixed(3)}" aria-label="${ca} with ${cb}: lift ${l.toFixed(2)}, ${nf0.format(PM.both[a][b])} orders">${l.toFixed(1)}×</span>`;
    });
    h += '</div>';
  });
  matrix.innerHTML = h;
  if (!st.cell || st.cell[0] === st.cell[1]) st.cell = best ? [best[0], best[1]] : [0, 1];
  pickCell(st.cell[0], st.cell[1], false);
