  side.innerHTML = `<h3 class="dbe-basket-eyebrow">Selected pair</h3><h3>${CATS[a]} + ${CATS[b]}</h3>` +
    `<p>Together in <b>${nf0.format(n)}</b> orders (${pct(n / PM.N)}), lift <b>${l.toFixed(2)}×</b>. ${l >= 1.2 ? 'A natural bundle or cross-sell.' : l < 0.9 ? 'Shoppers rarely combine these.' : 'About what chance predicts.'}</p>` +
    `<ol class="dbe-basket-pairlist">${top.map(([k, c], i) => { const [x, y] = k.split('|').map(Number); return `<li style="--i:${i}"><b>${P[x].n} + ${P[y].n}</b><span>${nf0.format(c)} orders · $${P[x].p + P[y].p} together</span></li>`; }).join('')}</ol>`;
