matrix.addEventListener('click', e => { const c = e.target.closest('.dbe-basket-mc'); if (c) pickCell(+c.dataset.a, +c.dataset.b, false); });
matrix.addEventListener('keydown', e => {
  const c = e.target.closest('.dbe-basket-mc');
