});
matrix.addEventListener('pointerover', e => {
  const c = e.target.closest('.dbe-basket-mc');
  if (!c || !PM) { xtip.hidden = true; return; }
  const a = +c.dataset.a, b = +c.dataset.b;
  xtip.innerHTML = a === b ? `<b>${CATS[a]}</b><p><span>Orders</span><em>${nf0.format(PM.cnt[a])}</em></p><p><span>Bought alone</span><em>${nf0.format(PM.solo[a])}</em></p>`
    : `<b>${CATS[a]} + ${CATS[b]}</b><p><span>Orders with both</span><em>${nf0.format(PM.both[a][b])}</em></p><p><span>Lift</span><em>${PM.lift(a, b).toFixed(2)}×</em></p><p><span>${CATS[a]} alone</span><em>${pct(PM.cnt[a] / PM.N)}</em></p>`;
  const r = c.getBoundingClientRect(), wr = mxwrap.getBoundingClientRect();
