pIn.value = Math.round(st.p * 100);
refresh(true);

css:
.dbe-returns {
  width: 100%;
  height: var(--dbe-returns-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-returns-line);
  border-radius: 14px;
  background: var(--dbe-returns-bg);
  color: var(--dbe-returns-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-returns-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-returns-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-returns-num { font-variant-numeric: tabular-nums; }
  & .dbe-returns-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-returns-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-returns-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-returns-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-returns-line-2) transparent; }
  & .dbe-returns-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  & .dbe-returns-scroll::-webkit-scrollbar-thumb { background: var(--dbe-returns-line-2); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  & .dbe-returns-scroll::-webkit-scrollbar-track { background: transparent; }
}

@keyframes dbe-returns-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbe-returns-col { from { transform: scaleY(0); } }
@keyframes dbe-returns-out { from { transform: scaleX(0); } }

.dbe-returns {
  /* re-theme with these four */
  --dbe-returns-bg: oklch(0.966 0.014 70);
  --dbe-returns-ink: oklch(0.3 0.035 40);
  --dbe-returns-accent: oklch(0.52 0.12 30);
  --dbe-returns-good: oklch(0.55 0.09 150);
  /* reasons: an earthy, colour-blind-aware sequence */
  --dbe-returns-r0: oklch(0.56 0.12 30);
  --dbe-returns-r1: oklch(0.74 0.11 62);
  --dbe-returns-r2: oklch(0.55 0.07 240);
  --dbe-returns-r3: oklch(0.42 0.06 330);
  --dbe-returns-r4: oklch(0.8 0.04 85);
  --dbe-returns-r5: oklch(0.66 0.07 180);
  --dbe-returns-r6: oklch(0.36 0.03 60);
  /* derived */
  --dbe-returns-card: color-mix(in oklch, var(--dbe-returns-bg), white 60%);
  --dbe-returns-sunk: color-mix(in oklch, var(--dbe-returns-bg), var(--dbe-returns-ink) 5%);
  --dbe-returns-line: color-mix(in oklch, var(--dbe-returns-ink) 12%, transparent);
  --dbe-returns-line-2: color-mix(in oklch, var(--dbe-returns-ink) 24%, transparent);
  --dbe-returns-muted: color-mix(in oklch, var(--dbe-returns-ink) 63%, var(--dbe-returns-bg));
  --dbe-returns-faint: color-mix(in oklch, var(--dbe-returns-ink) 40%, var(--dbe-returns-bg));
  --dbe-returns-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbe-returns-serif: ui-serif, "Iowan Old Style", Georgia, serif;

  .dbe-returns-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dbe-returns-muted); }
  .dbe-returns-r { text-align: right; }

  /* ---------- shell ---------- */
  .dbe-returns-app { display: grid; height: 100%; grid-template-columns: 206px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }
  .dbe-returns-side { grid-area: side; display: flex; flex-direction: column; gap: 24px; padding: 18px 12px 16px; border-right: 1px solid var(--dbe-returns-line); min-height: 0; overflow: auto; }
  .dbe-returns-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbe-returns-brand svg { width: 34px; height: 34px; padding: 6px; border-radius: 10px; background: var(--dbe-returns-accent); color: var(--dbe-returns-bg); fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linejoin: round; flex: none; }
  .dbe-returns-brand span { display: grid; line-height: 1.15; }
  .dbe-returns-brand b { font: 600 16px/1.1 var(--dbe-returns-serif); letter-spacing: -0.01em; }
  .dbe-returns-brand small { font-size: 11.5px; color: var(--dbe-returns-muted); }
  .dbe-returns-nav { display: grid; gap: 2px; }
  .dbe-returns-tab {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbe-returns-muted); font-weight: 560;
    transition: background-color 160ms var(--dbe-returns-ease), color 160ms var(--dbe-returns-ease);
    & span { flex: 1; }
    &:hover { color: var(--dbe-returns-ink); background: var(--dbe-returns-sunk); }
    &[aria-selected="true"] { color: var(--dbe-returns-ink); background: var(--dbe-returns-card); box-shadow: 0 0 0 1px var(--dbe-returns-line); font-weight: 650; }
    &[aria-selected="true"] .dbe-returns-ico { color: var(--dbe-returns-accent); }
  }
  .dbe-returns-badge { font-style: normal; font-size: 11px; font-weight: 700; min-width: 22px; padding: 1px 6px; text-align: center; border-radius: 99px; background: var(--dbe-returns-accent); color: var(--dbe-returns-card); font-variant-numeric: tabular-nums; }
  .dbe-returns-sidestats { margin: auto 0 0; display: grid; gap: 12px; padding: 14px 10px 0; border-top: 1px solid var(--dbe-returns-line); }
  .dbe-returns-sidestats div { display: grid; gap: 1px; }
  .dbe-returns-sidestats dt { font-size: 11px; color: var(--dbe-returns-muted); }
  .dbe-returns-sidestats dd { margin: 0; font: 600 20px/1.1 var(--dbe-returns-serif); font-variant-numeric: tabular-nums lining-nums; }

  .dbe-returns-head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap; padding: 16px 20px 12px; border-bottom: 1px solid var(--dbe-returns-line); }
  .dbe-returns-title { display: grid; gap: 4px; }
  .dbe-returns-h { font: 600 clamp(22px, 1rem + 1.2cqi, 30px)/1.05 var(--dbe-returns-serif); letter-spacing: -0.015em; }
  .dbe-returns-ctrls { display: flex; gap: 8px; flex-wrap: wrap; }
  .dbe-returns-seg {
    display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbe-returns-sunk); flex-wrap: wrap;
    & button { height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dbe-returns-muted); transition: background-color 160ms var(--dbe-returns-ease), color 160ms var(--dbe-returns-ease); }
    & button:hover { color: var(--dbe-returns-ink); }
    & button[aria-checked="true"] { background: var(--dbe-returns-ink); color: var(--dbe-returns-bg); }
  }

  .dbe-returns-main { grid-area: main; min-height: 0; padding: 14px 20px 16px; }
  .dbe-returns-view { height: 100%; min-height: 0; animation: dbe-returns-rise 380ms var(--dbe-returns-ease) both; }
  .dbe-returns-v-mosaic { display: grid; grid-template-columns: minmax(0, 1fr) clamp(240px, 26cqi, 290px); gap: 14px; }
  .dbe-returns-card { border-radius: 14px; background: var(--dbe-returns-card); border: 1px solid var(--dbe-returns-line); min-height: 0; }
  .dbe-returns-mcard, .dbe-returns-fcard { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 10px; padding: 14px 16px 12px; }
  .dbe-returns-mtools { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px 16px; flex-wrap: wrap; }
  .dbe-returns-sub { font-size: 12.5px; color: var(--dbe-returns-muted); max-width: 62ch; }
  .dbe-returns-ts { color: var(--dbe-returns-r0); }
  .dbe-returns-tl { color: color-mix(in oklch, var(--dbe-returns-r1), var(--dbe-returns-ink) 30%); }
  .dbe-returns-toggle { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 600; cursor: pointer; white-space: nowrap; }
  .dbe-returns-toggle input { width: 15px; height: 15px; margin: 0; }

  .dbe-returns-mosaic, .dbe-returns-fit { position: relative; min-height: 0; }
  .dbe-returns-msvg, .dbe-returns-fsvg { position: absolute; inset: 0; width: 100%; height: 100%; font-size: 11px; font-variant-numeric: tabular-nums; }
  .dbe-returns-msvg text, .dbe-returns-fsvg text { fill: var(--dbe-returns-muted); }
  .dbe-returns-msvg .dbe-returns-cat { fill: var(--dbe-returns-ink); font-weight: 650; }
  .dbe-returns-msvg .dbe-returns-rate { fill: var(--dbe-returns-ink); font-weight: 700; font-size: 12px; }
  .dbe-returns-msvg .dbe-returns-colg { transform-box: fill-box; transform-origin: bottom; }
  .dbe-returns-msvg.is-enter .dbe-returns-colg { animation: dbe-returns-col 700ms var(--dbe-returns-ease) both; animation-delay: calc(var(--i) * 70ms); }
  .dbe-returns-msvg .dbe-returns-cell { cursor: pointer; transition: opacity 160ms var(--dbe-returns-ease), filter 160ms; }
  .dbe-returns-msvg .dbe-returns-cell:focus-visible { outline: none; }
  .dbe-returns-msvg .dbe-returns-cell:focus-visible rect { stroke: var(--dbe-returns-ink); stroke-width: 3; }
  .dbe-returns-msvg:has(.dbe-returns-cell:hover) .dbe-returns-cell:not(:hover) { opacity: 0.55; }
  .dbe-returns-msvg .dbe-returns-cell:hover rect { filter: brightness(1.06); }
  .dbe-returns-msvg .dbe-returns-cell.is-sel rect { stroke: var(--dbe-returns-ink); stroke-width: 2.5; }
  .dbe-returns-msvg .dbe-returns-flag { fill: none; stroke: var(--dbe-returns-ink); stroke-width: 1.5; stroke-dasharray: 4 3; pointer-events: none; }
  .dbe-returns-msvg:not(.is-flag) .dbe-returns-flag { display: none; }
  .dbe-returns-msvg .dbe-returns-in { font-weight: 650; pointer-events: none; }
  .dbe-returns-reasons { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--dbe-returns-muted); }
  .dbe-returns-reasons li { display: inline-flex; align-items: center; gap: 6px; }
  .dbe-returns-reasons i { width: 10px; height: 10px; border-radius: 2px; background: var(--c); }

  .dbe-returns-tip {
    position: absolute; left: 0; top: 0; z-index: 6; pointer-events: none;
    min-width: 190px; padding: 10px 12px; border-radius: 10px;
    background: var(--dbe-returns-ink); color: var(--dbe-returns-bg);
    box-shadow: 0 16px 34px -12px color-mix(in oklch, var(--dbe-returns-ink) 70%, transparent);
    font-size: 12px; font-variant-numeric: tabular-nums;
    & b { display: block; font: 600 14px/1.2 var(--dbe-returns-serif); margin-bottom: 4px; }
    & p { display: flex; justify-content: space-between; gap: 14px; }
    & p span { opacity: 0.75; }
    & p em { font-style: normal; font-weight: 650; }
  }

  .dbe-returns-detail { display: grid; align-content: start; gap: 14px; padding: 16px; border-radius: 14px; background: var(--dbe-returns-sunk); min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbe-returns-line-2) transparent; }
  .dbe-returns-detail > * { animation: dbe-returns-rise 340ms var(--dbe-returns-ease) both; animation-delay: calc(var(--i, 0) * 45ms); }
  .dbe-returns-detail h3 { font: 600 20px/1.15 var(--dbe-returns-serif); letter-spacing: -0.01em; text-wrap: balance; }
  .dbe-returns-detail p { font-size: 12.5px; color: var(--dbe-returns-muted); }
  .dbe-returns-detail p b { color: var(--dbe-returns-ink); }
  .dbe-returns-dl { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 0; }
  .dbe-returns-dl div { display: grid; gap: 1px; }
  .dbe-returns-dl dt { font-size: 11px; color: var(--dbe-returns-muted); }
  .dbe-returns-dl dd { margin: 0; font: 600 18px/1.15 var(--dbe-returns-serif); font-variant-numeric: tabular-nums lining-nums; }
  .dbe-returns-index { display: grid; gap: 6px; }
  .dbe-returns-index li { display: grid; grid-template-columns: 96px minmax(0, 1fr) 42px; align-items: center; gap: 8px; font-size: 12px; }
  .dbe-returns-index li span:last-child { text-align: right; font-weight: 650; font-variant-numeric: tabular-nums; }
  .dbe-returns-index li i { height: 8px; border-radius: 4px; background: var(--c); width: calc(var(--w) * 100%); transform-origin: left; animation: dbe-returns-out 600ms var(--dbe-returns-ease) both; animation-delay: calc(var(--i) * 40ms); }
