  CATS.forEach((c, ci) => {
    const w = A.colTot[ci] / A.all * usable;
    s += `<g class="dbe-returns-colg" style="--i:${ci}">`;
    let y = T + ph;
    REASONS.forEach((r, ri) => {
      const val = A.cells[ci][ri][A.key];
      if (val <= 0) return;
      const h = val / A.colTot[ci] * ph;
