      const sel = st.sel && st.sel[0] === ci && st.sel[1] === ri;
      const ix = index(ci, ri);
      s += `<g class="dbe-returns-cell${sel ? ' is-sel' : ''}" data-c="${ci}" data-r="${ri}" tabindex="${sel || (!st.sel && ci === 0 && ri === 0) ? 0 : -1}" role="button" aria-label="${c.n}, ${r}: ${fmt(val)}, ${pct(val / A.colTot[ci])} of ${c.n.toLowerCase()} returns">` +
        `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${Math.max(0, w).toFixed(1)}" height="${Math.max(0, h - 1.5).toFixed(1)}" rx="2" fill="${rcol(ri)}"/>`;
      if (w > 46 && h > 18) s += `<text class="dbe-returns-in" x="${(x + 6).toFixed(1)}" y="${(y + 14).toFixed(1)}" style="fill:${ri === 1 || ri === 4 ? 'var(--dbe-returns-ink)' : 'oklch(0.98 0.01 80)'}">${Math.round(val / A.colTot[ci] * 100)}%</text>`;
      s += '</g>';
      if (ix >= 1.35 && h > 6) s += `<rect class="dbe-returns-flag" x="${(x + 1.5).toFixed(1)}" y="${(y + 1.5).toFixed(1)}" width="${Math.max(0, w - 3).toFixed(1)}" height="${Math.max(0, h - 4.5).toFixed(1)}" rx="2"/>`;
      cellPos.push({ ci, ri, x, y, w, h });
    });
    s += '</g>';
    const cx = x + w / 2;
    const rate = A.cells[ci].reduce((a, cc) => a + cc.u, 0) / A.sold[ci];
    /* labels shrink with the column: full, abbreviated, or left to the tooltip */
    s += `<text class="dbe-returns-rate" x="${cx.toFixed(1)}" y="${T - 18}" text-anchor="middle">${w > 48 ? pct(rate) : w > 26 ? pct(rate, 0) : ''}</text>`;
    if (w > 48) s += `<text x="${cx.toFixed(1)}" y="${T - 5}" text-anchor="middle" style="font-size:10px">${w > 70 ? 'return rate' : 'rate'}</text>`;
    s += `<text class="dbe-returns-cat" x="${cx.toFixed(1)}" y="${mh - 16}" text-anchor="middle">${w > 74 ? c.n : w > 30 ? c.n.slice(0, 3) + '.' : ''}</text>`;
