/* ---------- return queue ---------- */
const NAMES = ['Maya T.', 'Ines R.', 'Harper L.', 'Noor A.', 'Celeste B.', 'Priya K.', 'Jun W.', 'Amara O.', 'Leonie F.', 'Sofia M.', 'Rosa D.', 'Hana S.', 'Elif Y.', 'Grace N.', 'Tess V.', 'Zara P.'];
