css:
.dbe-margin {
  width: 100%;
  height: var(--dbe-margin-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-margin-line);
  border-radius: 14px;
  background: var(--dbe-margin-bg);
  color: var(--dbe-margin-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-margin-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-margin-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-margin-num { font-variant-numeric: tabular-nums; }
  & .dbe-margin-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-margin-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-margin-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-margin-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-margin-line-2) transparent; }
