}

@keyframes dbe-margin-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbe-margin-pop { from { opacity: 0; scale: 0; } }
@keyframes dbe-margin-drop { from { transform: scaleY(0); } }

.dbe-margin {
  /* re-theme with these four */
  --dbe-margin-bg: oklch(0.992 0.002 95);
