  --dbe-margin-spring: linear(0, 0.016, 0.062 2.6%, 0.24 5.7%, 0.82 15%, 0.99 19.5%, 1.06 24%, 1.075 28.2%, 1.055 33%, 1.012 44%, 0.996 55%, 1);
  letter-spacing: -0.005em;

  .dbe-margin-eyebrow { font-size: 10px; font-weight: 750; letter-spacing: 0.14em; text-transform: uppercase; color: var(--dbe-margin-muted); }
  .dbe-margin-r { text-align: right; }

  /* ---------- shell ---------- */
  .dbe-margin-app { display: grid; height: 100%; grid-template-columns: 200px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }
  .dbe-margin-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 14px; border-right: 2px solid var(--dbe-margin-ink); min-height: 0; overflow: auto; }
  .dbe-margin-brand { display: flex; align-items: center; gap: 10px; }
  .dbe-margin-brand svg { width: 34px; height: 34px; padding: 5px; background: var(--dbe-margin-ink); color: var(--dbe-margin-bg); fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; flex: none; }
  .dbe-margin-brand span { display: grid; line-height: 1.1; }
  .dbe-margin-brand b { font-weight: 800; font-size: 15px; letter-spacing: -0.03em; }
  .dbe-margin-brand small { font-size: 11px; color: var(--dbe-margin-muted); }
  .dbe-margin-nav { display: grid; gap: 0; border-top: 1px solid var(--dbe-margin-line); }
  .dbe-margin-tab {
    display: flex; align-items: center; gap: 10px; padding: 10px 2px; border-bottom: 1px solid var(--dbe-margin-line);
    color: var(--dbe-margin-muted); font-weight: 650;
