  }
  .dbe-margin-cats { border: 0; margin: 0; padding: 0; display: grid; gap: 2px; min-inline-size: 0; }
  .dbe-margin-cats legend { padding: 0; margin-bottom: 8px; }
  .dbe-margin-cat {
    display: grid; grid-template-columns: 16px 1fr auto; align-items: center; gap: 8px; padding: 6px 4px; border-radius: 4px; cursor: pointer; font-size: 12.5px; font-weight: 600;
    & input { appearance: none; width: 14px; height: 14px; margin: 0; border-radius: 50%; border: 2px solid var(--c); background: var(--c); cursor: pointer; transition: background-color 140ms, transform 220ms var(--dbe-margin-spring); }
    & input:not(:checked) { background: transparent; transform: scale(0.85); }
