  }
  .dbe-margin-target { margin-top: auto; display: grid; gap: 2px; padding-top: 14px; border-top: 2px solid var(--dbe-margin-ink); }
  .dbe-margin-target output { font-size: 34px; font-weight: 800; letter-spacing: -0.05em; line-height: 1; color: var(--dbe-margin-accent); font-variant-numeric: tabular-nums; }
  .dbe-margin-target small { font-size: 11px; color: var(--dbe-margin-muted); text-wrap: pretty; }

  .dbe-margin-head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 20px; padding: 14px 20px 12px; border-bottom: 2px solid var(--dbe-margin-ink); flex-wrap: wrap; }
  .dbe-margin-kpis { display: flex; gap: clamp(16px, 3cqi, 40px); flex-wrap: wrap; }
  .dbe-margin-kpi { display: grid; gap: 0; }
  .dbe-margin-kpi span { font-size: 10px; font-weight: 750; letter-spacing: 0.14em; text-transform: uppercase; color: var(--dbe-margin-muted); }
  .dbe-margin-kpi output { font-size: clamp(22px, 1rem + 1.4cqi, 32px); font-weight: 800; letter-spacing: -0.045em; line-height: 1.05; font-variant-numeric: tabular-nums; }
  .dbe-margin-kpi-alert output { color: var(--dbe-margin-accent); }
  .dbe-margin-seg {
    display: inline-flex; border: 1.5px solid var(--dbe-margin-ink); border-radius: 3px; overflow: hidden;
    & button { height: 28px; padding: 0 12px; font-size: 12px; font-weight: 750; letter-spacing: 0.02em; transition: background-color 140ms, color 140ms; }
