  .dbe-margin-seg-sm button { height: 24px; padding: 0 9px; font-size: 11px; white-space: nowrap; }

  .dbe-margin-main { grid-area: main; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) clamp(260px, 29cqi, 320px); grid-template-areas: "view detail"; }
  .dbe-margin-view { grid-area: view; min-height: 0; animation: dbe-margin-rise 360ms var(--dbe-margin-ease) both; }

  /* ---------- matrix ---------- */
  .dbe-margin-v-matrix { padding: 12px 8px 10px 16px; }
  .dbe-margin-plot { position: relative; height: 100%; min-height: 0; touch-action: pan-y; }
  .dbe-margin-svg { position: absolute; inset: 0; width: 100%; height: 100%; font-size: 10.5px; font-variant-numeric: tabular-nums; }
  .dbe-margin-svg text { fill: var(--dbe-margin-muted); }
  .dbe-margin-svg .dbe-margin-gl { stroke: var(--dbe-margin-line); }
  .dbe-margin-svg .dbe-margin-ax { stroke: var(--dbe-margin-ink); stroke-width: 1.5; }
  .dbe-margin-svg .dbe-margin-q { font-size: 11px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; fill: var(--dbe-margin-faint); }
  .dbe-margin-svg .dbe-margin-under { fill: color-mix(in oklch, var(--dbe-margin-accent) 5%, transparent); }
  .dbe-margin-svg .dbe-margin-med { stroke: var(--dbe-margin-ink); stroke-dasharray: 2 4; opacity: 0.5; }
  .dbe-margin-svg .dbe-margin-b {
    cursor: pointer; transition: transform 700ms var(--dbe-margin-ease), opacity 260ms var(--dbe-margin-ease);
    & circle { fill: color-mix(in oklch, var(--c) 78%, transparent); stroke: var(--c); stroke-width: 1.5; transition: r 600ms var(--dbe-margin-ease), fill 160ms; }
    &:hover circle, &:focus-visible circle { fill: var(--c); }
    &:focus-visible { outline: none; }
    &.is-sel circle { stroke: var(--dbe-margin-ink); stroke-width: 2.5; fill: var(--c); }
    &.is-below circle { stroke-dasharray: 3 2; }
    & text { fill: var(--dbe-margin-ink); font-weight: 650; font-size: 10.5px; pointer-events: none; opacity: 0; transition: opacity 160ms; }
    &.is-sel text, &:hover text, &.is-lab text { opacity: 1; }
    &.is-off { opacity: 0; pointer-events: none; }
  }
