  .dbe-margin-tline {
    position: absolute; left: 0; right: 0; top: 0; height: 18px; margin-top: -9px;
    transform: translateY(var(--y, 0px)); cursor: ns-resize; outline: none;
    &::before { content: ""; position: absolute; left: var(--l, 44px); right: 6px; top: 8px; height: 2px; background: var(--dbe-margin-accent); }
    & span { position: absolute; right: 6px; top: -12px; font-size: 11px; font-weight: 800; letter-spacing: 0.02em; color: var(--dbe-margin-accent); background: var(--dbe-margin-bg); padding: 0 4px; font-variant-numeric: tabular-nums; }
    &:hover::before, &.is-drag::before { height: 3px; top: 7.5px; }
