  }

  .dbe-margin-tip {
    position: absolute; left: 0; top: 0; z-index: 8; pointer-events: none;
    min-width: 200px; padding: 10px 12px; background: var(--dbe-margin-ink); color: var(--dbe-margin-bg);
    font-size: 12px; font-variant-numeric: tabular-nums;
    & b { display: block; font-size: 13px; font-weight: 750; margin-bottom: 1px; letter-spacing: -0.01em; }
    & small { display: block; font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; opacity: 0.6; margin-bottom: 6px; }
    & p { display: flex; justify-content: space-between; gap: 14px; }
    & p span { opacity: 0.7; }
    & p em { font-style: normal; font-weight: 700; }
