  }
  .dbe-margin-pn { display: flex; align-items: center; gap: 8px; }
  .dbe-margin-pn i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); flex: none; }
  .dbe-margin-pn b { font-weight: 650; }
  .dbe-margin-mbar { display: grid; grid-template-columns: 46px minmax(60px, 1fr); align-items: center; gap: 8px; }
  .dbe-margin-mbar span { text-align: right; font-weight: 750; }
  .dbe-margin-mbar span.is-neg, .dbe-margin-table .is-below { color: var(--dbe-margin-accent); }
