  .dbe-margin-wf { position: relative; min-height: 0; }
  .dbe-margin-wsvg { position: absolute; inset: 0; width: 100%; height: 100%; font-size: 11px; font-variant-numeric: tabular-nums; }
  .dbe-margin-wsvg text { fill: var(--dbe-margin-muted); }
