  .dbe-margin-wsvg .dbe-margin-wv { fill: var(--dbe-margin-ink); font-weight: 750; }
  .dbe-margin-wsvg .dbe-margin-wb { transition: opacity 140ms; }
  .dbe-margin-wsvg .dbe-margin-wb rect { fill: color-mix(in oklch, var(--dbe-margin-accent) 70%, var(--dbe-margin-bg)); }
