  .dbe-margin-wsvg:has(.dbe-margin-wb:hover) .dbe-margin-wb:not(:hover) { opacity: 0.4; }
  .dbe-margin-wsvg .dbe-margin-conn { stroke: var(--dbe-margin-ink); stroke-width: 1; stroke-dasharray: 2 2; opacity: 0.5; }
  .dbe-margin-wsvg.is-enter .dbe-margin-wb rect { transform-box: fill-box; transform-origin: left; animation: dbe-margin-drop 520ms var(--dbe-margin-ease) both; animation-delay: calc(var(--i) * 70ms); }
  .dbe-margin-verdict { font-size: 12.5px; line-height: 1.45; text-wrap: pretty; }
  .dbe-margin-verdict b { font-weight: 750; }
  .dbe-margin-verdict .is-neg { color: var(--dbe-margin-accent); }

  /* ---------- container responses ---------- */
  @container (max-width: 1040px) {
    .dbe-margin-app { grid-template-columns: 172px minmax(0, 1fr); }
    .dbe-margin-kpi:nth-child(4) { display: none; }
  }
  @container (max-width: 900px) {
