/* round an axis maximum up to 1/2/2.5/5 x 10^n */
function nice(max, n = 4) {
  if (!(max > 0)) return { step: 1, top: n };
  const raw = max / n, mag = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / mag;
