/* ---------- catalogue: name, category, list price, COGS share of list, shipping per unit, return rate, units a day, base discount, promo sensitivity ---------- */
const CATS = ['Bikes', 'Components', 'Apparel', 'Accessories', 'Nutrition'];
const RAW = [
  ['Strada 105 road bike', 0, 2450, 0.64, 85, 0.04, 0.9, 0.06, 0.6],
  ['Gravel One', 0, 1980, 0.63, 85, 0.05, 1.1, 0.07, 0.6],
