  ['Recovery bar, 12-pack', 4, 30, 0.55, 5, 0, 7, 0.1, 0.7]
];
const FEE = 0.029, FEE_FIX = 0.3, RET_LOSS = 0.25;
const PERIODS = { 30: { days: 30, boost: 0.5, label: 'Sep 3 – Oct 2, 2026', note: 'end-of-summer sale' }, 90: { days: 90, boost: 0.2, label: 'Jul 5 – Oct 2, 2026', note: 'one sale event' }, ytd: { days: 275, boost: 0.08, label: 'Jan 1 – Oct 2, 2026', note: 'year to date' } };
const R = rng(2468);
const NOISE = RAW.map(() => ({ 30: 0.85 + R() * 0.3, 90: 0.9 + R() * 0.2, ytd: 0.93 + R() * 0.14 }));
let PRODUCTS = [];
function build(period) {
  const P = PERIODS[period];
  PRODUCTS = RAW.map(([name, cat, price, cogsPct, ship, ret, perDay, disc0, sens], i) => {
    const disc = Math.min(0.4, disc0 * (1 + sens * P.boost));
    const units = Math.max(1, Math.round(perDay * P.days * (1 + 0.7 * (disc - disc0)) * NOISE[i][period] * (cat === 0 && period === 'ytd' ? 0.9 : 1)));
    const net = price * (1 - disc);
    const parts = { price, discount: price * disc, cogs: price * cogsPct, ship, fees: net * FEE + FEE_FIX, returns: ret * (RET_LOSS * net + ship) };
    const cm = net - parts.cogs - parts.ship - parts.fees - parts.returns;
    return { i, name, cat, units, net, parts, cm, pct: cm / net, rev: net * units, cmTot: cm * units, disc, ret };
  });
}

/* ---------- formatting ---------- */
const nf0 = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const money = v => { const a = Math.abs(v), s = v < 0 ? '−' : ''; return a >= 1e6 ? s + '$' + (a / 1e6).toFixed(2) + 'M' : a >= 1e4 ? s + '$' + (a / 1e3).toFixed(0) + 'k' : a >= 1e3 ? s + '$' + (a / 1e3).toFixed(1) + 'k' : s + '$' + a.toFixed(a < 100 ? 2 : 0); };
