  const below = xs.filter(p => p.pct < st.target).length;
  $('[data-k="below"]').textContent = `${below} of ${xs.length}`;
  CATS.forEach((_, k) => { $(`[data-n="${k}"]`).textContent = PRODUCTS.filter(p => p.cat === k).length; });
