  const X = u => L + (Math.log10(u) - lx0) / (lx1 - lx0) * (pw - L - Rr);
  const Y = v => T + (YMAX - clamp(v, YMIN, YMAX)) / (YMAX - YMIN) * (ph - T - B);
  const maxRev = Math.max(...PRODUCTS.map(p => p.rev));
