  for (let v = -0.1; v <= YMAX + 1e-6; v += 0.1) s += `<line class="dbe-margin-gl" x1="${L}" x2="${pw - Rr}" y1="${Y(v).toFixed(1)}" y2="${Y(v).toFixed(1)}"/><text x="${L - 8}" y="${(Y(v) + 3.5).toFixed(1)}" text-anchor="end">${pct(v, 0)}</text>`;
  s += `<line class="dbe-margin-ax" x1="${L}" x2="${pw - Rr}" y1="${Y(0).toFixed(1)}" y2="${Y(0).toFixed(1)}"/>`;
  for (let e = Math.ceil(G.lx0); e <= G.lx1; e++) [1, 2, 5].forEach(m => {
    const u = m * Math.pow(10, e);
    if (Math.log10(u) < G.lx0 || Math.log10(u) > G.lx1) return;
    s += `<line class="dbe-margin-gl" x1="${X(u).toFixed(1)}" x2="${X(u).toFixed(1)}" y1="${T}" y2="${ph - B}"/><text x="${X(u).toFixed(1)}" y="${ph - B + 14}" text-anchor="middle">${nf0.format(u)}</text>`;
  });
  s += `<text x="${pw - Rr}" y="${ph - 4}" text-anchor="end" style="font-weight:700;letter-spacing:.1em;font-size:9.5px">UNITS SOLD (LOG) →</text>`;
  const xsVis = PRODUCTS.filter(vis).map(p => p.units).sort((a, b) => a - b);
  const med = xsVis.length ? xsVis[xsVis.length >> 1] : 1;
