    `<p><span>Contribution</span><em class="${p.cmTot < 0 ? 'dbe-margin-neg' : ''}">${money(p.cmTot)}</em></p><p><span>Margin</span><em class="${p.pct < st.target ? 'dbe-margin-neg' : ''}">${pct(p.pct)}</em></p><p><span>Avg discount</span><em>${pct(p.disc, 0)}</em></p>`;
