/* ---------- waterfall detail ---------- */
const wf = $('.dbe-margin-wf'), wsvg = $('.dbe-margin-wsvg'), wtip = $('.dbe-margin-tip', wf);
let ww = 0, wh = 0, WR = null;
function renderDetail(enter) {
  const p = PRODUCTS[st.sel];
  $('[data-d="cat"]').textContent = CATS[p.cat];
  $('[data-d="name"]').textContent = p.name;
  $('[data-d="facts"]').textContent = `${nf0.format(p.units)} units · ${money(p.rev)} net · ${pct(p.disc, 0)} avg discount · ${pct(p.ret, 0)} returned`;
  drawWaterfall(enter);
  const costs = [['discounting', p.parts.discount], ['shipping', p.parts.ship], ['payment fees', p.parts.fees], ['returns', p.parts.returns]].sort((a, b) => b[1] - a[1]);
  const gap = p.pct - st.target;
  $('[data-d="verdict"]').innerHTML = `${gap >= 0 ? 'Clears' : '<span class="is-neg">Misses</span>'} the ${pct(st.target, 0)} target by <b class="${gap < 0 ? 'is-neg' : ''}">${Math.abs(gap * 100).toFixed(1)} pts</b>. After cost of goods, ${costs[0][0]} is the biggest leak at <b>${money(costs[0][1])}</b> a unit` +
    (gap < 0 ? `; closing the gap means finding <b>${money(-gap * p.net)}</b> a unit.` : '.');
}
function drawWaterfall(enter) {
  if (ww < 120 || wh < 100) return;
  const p = PRODUCTS[st.sel], m = st.basis === 'unit' ? 1 : p.units;
  const rows = [['List price', p.parts.price, 'start'], ['Discount', -p.parts.discount], ['Cost of goods', -p.parts.cogs], ['Shipping', -p.parts.ship], ['Payment fees', -p.parts.fees], ['Returns', -p.parts.returns], ['Contribution', p.cm, 'end']];
  WR = rows.map(r => [r[0], r[1] * m, r[2]]);
  const L = 92, Rr = 62, rowH = wh / rows.length, bh = Math.min(20, rowH * 0.62);
  const lo = Math.min(0, p.cm * m), hi = p.parts.price * m;
  const X = v => L + (v - lo) / (hi - lo) * (ww - L - Rr);
  let cum = 0, s = '';
  WR.forEach(([label, v, kind], k) => {
    const y = k * rowH + (rowH - bh) / 2;
    let a, b;
    if (kind === 'start') { a = 0; b = v; cum = v; }
    else if (kind === 'end') { a = 0; b = v; }
    else { a = cum + v; b = cum; cum += v; }
    const x0 = X(Math.min(a, b)), x1 = X(Math.max(a, b));
    s += `<g class="dbe-margin-wb${kind ? ' is-' + kind : ''}${kind === 'end' && v < 0 ? ' is-neg' : ''}" data-k="${k}"><text class="dbe-margin-wl" x="0" y="${(y + bh / 2 + 4).toFixed(1)}">${label}</text>` +
