.dbe-checkout {
  width: 100%;
  height: var(--dbe-checkout-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border: 1px solid var(--dbe-checkout-line);
  border-radius: 14px;
  background: var(--dbe-checkout-bg);
  color: var(--dbe-checkout-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbe-checkout-accent);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select { font: inherit; color: inherit; letter-spacing: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dbe-checkout-accent); outline-offset: 2px; }
  & h2, & h3, & h4, & p { margin: 0; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; overflow: visible; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; width: 100%; }
  & th { font-weight: inherit; text-align: inherit; }
  & output, & .dbe-checkout-num { font-variant-numeric: tabular-nums; }
  & .dbe-checkout-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
  & .dbe-checkout-ico { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .dbe-checkout-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .dbe-checkout-scroll { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbe-checkout-line-2) transparent; }
  & .dbe-checkout-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  & .dbe-checkout-scroll::-webkit-scrollbar-thumb { background: var(--dbe-checkout-line-2); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
  & .dbe-checkout-scroll::-webkit-scrollbar-track { background: transparent; }
}

@keyframes dbe-checkout-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbe-checkout-left { from { transform: scaleX(0); } }
@keyframes dbe-checkout-fade { from { opacity: 0; } }
@keyframes dbe-checkout-draw { from { stroke-dashoffset: 1; } }

.dbe-checkout {
  /* re-theme with these four */
  --dbe-checkout-bg: oklch(0.175 0.004 285);
  --dbe-checkout-ink: oklch(0.95 0.004 285);
  --dbe-checkout-mob: oklch(0.7 0.18 38);
  --dbe-checkout-desk: oklch(0.8 0.085 232);
  /* derived */
  --dbe-checkout-accent: var(--dbe-checkout-mob);
  --dbe-checkout-sunk: color-mix(in oklch, var(--dbe-checkout-bg), black 30%);
  --dbe-checkout-panel: color-mix(in oklch, var(--dbe-checkout-bg), var(--dbe-checkout-ink) 4.5%);
  --dbe-checkout-raise: color-mix(in oklch, var(--dbe-checkout-bg), var(--dbe-checkout-ink) 9%);
  --dbe-checkout-line: color-mix(in oklch, var(--dbe-checkout-ink) 10%, transparent);
  --dbe-checkout-line-2: color-mix(in oklch, var(--dbe-checkout-ink) 20%, transparent);
  --dbe-checkout-muted: color-mix(in oklch, var(--dbe-checkout-ink) 60%, var(--dbe-checkout-bg));
  --dbe-checkout-faint: color-mix(in oklch, var(--dbe-checkout-ink) 36%, var(--dbe-checkout-bg));
  --dbe-checkout-bad: oklch(0.68 0.19 25);
  --dbe-checkout-ease: cubic-bezier(0.22, 1, 0.36, 1);

  .dbe-checkout-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dbe-checkout-muted); }

  /* ---------- shell ---------- */
  .dbe-checkout-app { display: grid; height: 100%; grid-template-columns: 64px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "rail head" "rail main"; }
  .dbe-checkout-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 20px; padding: 16px 0; border-right: 1px solid var(--dbe-checkout-line); background: var(--dbe-checkout-sunk); }
  .dbe-checkout-logo svg { width: 36px; height: 36px; padding: 6px; border-radius: 50%; background: linear-gradient(135deg, var(--dbe-checkout-mob), color-mix(in oklch, var(--dbe-checkout-mob), var(--dbe-checkout-desk) 70%)); color: var(--dbe-checkout-sunk); fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dbe-checkout-nav { display: grid; gap: 6px; }
  .dbe-checkout-tab {
    position: relative; width: 44px; height: 44px; display: grid; place-items: center; border-radius: 12px; color: var(--dbe-checkout-muted);
    transition: background-color 160ms var(--dbe-checkout-ease), color 160ms var(--dbe-checkout-ease);
    & span { position: absolute; left: calc(100% + 10px); top: 50%; translate: 0 -50%; padding: 4px 8px; border-radius: 6px; background: var(--dbe-checkout-raise); color: var(--dbe-checkout-ink); font-size: 12px; font-weight: 600; white-space: nowrap; pointer-events: none; opacity: 0; transform: translateX(-4px); transition: opacity 140ms var(--dbe-checkout-ease), transform 200ms var(--dbe-checkout-ease); z-index: 10; }
    &:hover span, &:focus-visible span { opacity: 1; transform: none; }
    &:hover { color: var(--dbe-checkout-ink); background: var(--dbe-checkout-panel); }
    &[aria-selected="true"] { color: var(--dbe-checkout-ink); background: var(--dbe-checkout-raise); }
    &[aria-selected="true"] .dbe-checkout-ico { color: var(--dbe-checkout-mob); }
  }

  .dbe-checkout-head { grid-area: head; display: flex; justify-content: space-between; align-items: flex-end; gap: 12px 20px; flex-wrap: wrap; padding: 16px 20px 12px; border-bottom: 1px solid var(--dbe-checkout-line); }
  .dbe-checkout-title { display: grid; gap: 4px; min-width: 0; }
  .dbe-checkout-h { font-size: clamp(18px, 0.8rem + 1cqi, 25px); font-weight: 650; letter-spacing: -0.025em; line-height: 1.15; max-width: 40ch; }
  .dbe-checkout-h .m { color: var(--dbe-checkout-mob); }
  .dbe-checkout-h .d { color: var(--dbe-checkout-desk); }
  .dbe-checkout-ctrls { display: flex; gap: 8px; flex-wrap: wrap; }
  .dbe-checkout-seg {
    display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--dbe-checkout-sunk); border: 1px solid var(--dbe-checkout-line);
    & button { height: 26px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dbe-checkout-muted); transition: background-color 160ms var(--dbe-checkout-ease), color 160ms var(--dbe-checkout-ease); }
    & button:hover { color: var(--dbe-checkout-ink); }
    & button[aria-checked="true"] { background: var(--dbe-checkout-raise); color: var(--dbe-checkout-ink); }
  }

  .dbe-checkout-main { grid-area: main; min-height: 0; padding: 14px 20px 16px; }
  .dbe-checkout-view { height: 100%; min-height: 0; animation: dbe-checkout-rise 380ms var(--dbe-checkout-ease) both; }

  /* ---------- butterfly ---------- */
  .dbe-checkout-v-funnel { display: grid; grid-template-columns: minmax(0, 1fr) clamp(250px, 28cqi, 310px); gap: 16px; }
  .dbe-checkout-fly { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 8px; min-height: 0; }
  .dbe-checkout-legend { display: flex; justify-content: space-between; font-size: 12px; font-weight: 600; }
  .dbe-checkout-legend span { display: inline-flex; align-items: center; gap: 8px; color: var(--dbe-checkout-muted); }
  .dbe-checkout-legend b { color: var(--dbe-checkout-ink); font-size: 18px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  .dbe-checkout-legend i { width: 10px; height: 10px; border-radius: 3px; }
  .dbe-checkout-lm i { background: var(--dbe-checkout-mob); }
  .dbe-checkout-ld i { background: var(--dbe-checkout-desk); }
  .dbe-checkout-plot { position: relative; min-height: 0; }
  .dbe-checkout-svg { position: absolute; inset: 0; width: 100%; height: 100%; font-size: 11px; font-variant-numeric: tabular-nums; }
  .dbe-checkout-svg text { fill: var(--dbe-checkout-muted); }
  .dbe-checkout-svg .dbe-checkout-step { cursor: pointer; }
  .dbe-checkout-svg .dbe-checkout-step:focus-visible { outline: none; }
  .dbe-checkout-svg .dbe-checkout-step:focus-visible .dbe-checkout-sl { fill: var(--dbe-checkout-ink); text-decoration: underline; }
  .dbe-checkout-svg .dbe-checkout-sbg { fill: transparent; transition: fill 160ms; }
  .dbe-checkout-svg .dbe-checkout-step:hover .dbe-checkout-sbg { fill: color-mix(in oklch, var(--dbe-checkout-ink) 4%, transparent); }
  .dbe-checkout-svg .dbe-checkout-step.is-sel .dbe-checkout-sbg { fill: color-mix(in oklch, var(--dbe-checkout-ink) 7%, transparent); }
  .dbe-checkout-svg .dbe-checkout-sl { fill: var(--dbe-checkout-ink); font-weight: 650; font-size: 12px; }
  .dbe-checkout-svg .dbe-checkout-sn { fill: var(--dbe-checkout-faint); font-size: 10px; letter-spacing: 0.1em; }
  .dbe-checkout-svg .dbe-checkout-bm { fill: var(--dbe-checkout-mob); }
  .dbe-checkout-svg .dbe-checkout-bd { fill: var(--dbe-checkout-desk); }
  .dbe-checkout-svg .dbe-checkout-wm { fill: color-mix(in oklch, var(--dbe-checkout-mob) 16%, transparent); }
  .dbe-checkout-svg .dbe-checkout-wd { fill: color-mix(in oklch, var(--dbe-checkout-desk) 14%, transparent); }
  .dbe-checkout-svg .dbe-checkout-n { fill: var(--dbe-checkout-ink); font-weight: 650; }
  .dbe-checkout-svg .dbe-checkout-drop { fill: var(--dbe-checkout-bad); font-weight: 650; font-size: 10.5px; }
  .dbe-checkout-svg .dbe-checkout-bar { transition: opacity 160ms; }
  .dbe-checkout-svg:has(.dbe-checkout-bar:hover) .dbe-checkout-bar:not(:hover) { opacity: 0.55; }
  .dbe-checkout-svg.is-enter .dbe-checkout-bm { transform-box: fill-box; transform-origin: right; animation: dbe-checkout-left 700ms var(--dbe-checkout-ease) both; animation-delay: calc(var(--i) * 70ms); }
  .dbe-checkout-svg.is-enter .dbe-checkout-bd { transform-box: fill-box; transform-origin: left; animation: dbe-checkout-left 700ms var(--dbe-checkout-ease) both; animation-delay: calc(var(--i) * 70ms); }
  .dbe-checkout-svg.is-enter .dbe-checkout-wm, .dbe-checkout-svg.is-enter .dbe-checkout-wd, .dbe-checkout-svg.is-enter .dbe-checkout-drop { animation: dbe-checkout-fade 600ms var(--dbe-checkout-ease) both; animation-delay: calc(300ms + var(--i) * 70ms); }

  .dbe-checkout-tip {
    position: absolute; left: 0; top: 0; z-index: 8; pointer-events: none;
    min-width: 196px; padding: 10px 12px; border-radius: 10px;
    background: var(--dbe-checkout-raise); border: 1px solid var(--dbe-checkout-line-2);
    box-shadow: 0 16px 34px -10px oklch(0 0 0 / 0.65);
    font-size: 12px; font-variant-numeric: tabular-nums;
    & b { display: flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 650; margin-bottom: 5px; }
    & b i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); }
    & p { display: flex; justify-content: space-between; gap: 14px; }
    & p span { color: var(--dbe-checkout-muted); }
    & p em { font-style: normal; font-weight: 650; }
  }

  .dbe-checkout-why { display: grid; align-content: start; gap: 12px; padding: 16px; border-radius: 14px; background: var(--dbe-checkout-panel); border: 1px solid var(--dbe-checkout-line); min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbe-checkout-line-2) transparent; }
  .dbe-checkout-why > * { animation: dbe-checkout-rise 360ms var(--dbe-checkout-ease) both; animation-delay: calc(var(--i, 0) * 45ms); }
  .dbe-checkout-why h3 { font-size: 16px; font-weight: 680; letter-spacing: -0.015em; line-height: 1.2; text-wrap: balance; }
  .dbe-checkout-why p { font-size: 12px; color: var(--dbe-checkout-muted); }
  .dbe-checkout-why p b { color: var(--dbe-checkout-ink); }
  .dbe-checkout-split { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  .dbe-checkout-split div { padding: 9px 10px; border-radius: 10px; background: var(--dbe-checkout-sunk); display: grid; gap: 1px; }
  .dbe-checkout-split span { font-size: 11px; color: var(--dbe-checkout-muted); }
  .dbe-checkout-split output { font-size: 19px; font-weight: 700; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
  .dbe-checkout-split .m output { color: var(--dbe-checkout-mob); }
  .dbe-checkout-split .d output { color: var(--dbe-checkout-desk); }
  .dbe-checkout-reasons { display: grid; gap: 10px; }
  .dbe-checkout-reasons li { display: grid; gap: 4px; animation: dbe-checkout-rise 360ms var(--dbe-checkout-ease) both; animation-delay: calc(120ms + var(--i) * 50ms); }
  .dbe-checkout-reasons header { display: flex; justify-content: space-between; gap: 8px; font-size: 12.5px; }
  .dbe-checkout-reasons header span { color: var(--dbe-checkout-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dbe-checkout-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 3px; }
  .dbe-checkout-pair i { height: 6px; border-radius: 3px; background: var(--dbe-checkout-sunk); position: relative; overflow: hidden; }
  .dbe-checkout-pair i::before { content: ""; position: absolute; inset: 0; width: calc(var(--w) * 100%); border-radius: inherit; background: var(--c); transform-origin: left; animation: dbe-checkout-left 600ms var(--dbe-checkout-ease) both; animation-delay: calc(200ms + var(--i) * 50ms); }
  .dbe-checkout-pair i:first-child::before { left: auto; right: 0; transform-origin: right; }

  /* ---------- trend ---------- */
  .dbe-checkout-v-trend { display: grid; }
  .dbe-checkout-card { border-radius: 14px; background: var(--dbe-checkout-panel); border: 1px solid var(--dbe-checkout-line); min-height: 0; }
  .dbe-checkout-card > header { padding: 14px 16px 6px; display: grid; gap: 2px; }
  .dbe-checkout-card h3 { font-size: 14px; font-weight: 650; }
  .dbe-checkout-card header p { font-size: 12px; color: var(--dbe-checkout-muted); }
  .dbe-checkout-tcard { display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbe-checkout-tplot { position: relative; min-height: 0; margin: 0 8px 8px; }
  .dbe-checkout-tsvg { position: absolute; inset: 0; width: 100%; height: 100%; font-size: 10.5px; font-variant-numeric: tabular-nums; }
  .dbe-checkout-tsvg text { fill: var(--dbe-checkout-muted); }
  .dbe-checkout-tsvg .dbe-checkout-gl { stroke: var(--dbe-checkout-line); }
  .dbe-checkout-tsvg .dbe-checkout-tm, .dbe-checkout-tsvg .dbe-checkout-td { fill: none; stroke-width: 2.2; stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: 1; }
  .dbe-checkout-tsvg .dbe-checkout-tm { stroke: var(--dbe-checkout-mob); }
  .dbe-checkout-tsvg .dbe-checkout-td { stroke: var(--dbe-checkout-desk); }
  .dbe-checkout-tsvg .dbe-checkout-raw { fill: none; stroke-width: 1; opacity: 0.28; }
  .dbe-checkout-tsvg.is-enter .dbe-checkout-tm, .dbe-checkout-tsvg.is-enter .dbe-checkout-td { animation: dbe-checkout-draw 1100ms var(--dbe-checkout-ease) both; }
  .dbe-checkout-tsvg .dbe-checkout-ev line { stroke: var(--dbe-checkout-ink); stroke-dasharray: 2 3; opacity: 0.5; }
  .dbe-checkout-tsvg .dbe-checkout-ev text { fill: var(--dbe-checkout-ink); font-weight: 600; }
  .dbe-checkout-tsvg .dbe-checkout-xh line { stroke: var(--dbe-checkout-ink); opacity: 0.4; }
  .dbe-checkout-tsvg .dbe-checkout-xh circle { stroke: var(--dbe-checkout-bg); stroke-width: 2; }

  /* ---------- payments ---------- */
  .dbe-checkout-v-pay { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 14px; align-content: start; }
  .dbe-checkout-methods { padding: 6px 16px 16px; display: grid; gap: 14px; }
  .dbe-checkout-meth { display: grid; grid-template-columns: 150px minmax(0, 1fr) 64px; align-items: center; gap: 6px 12px; animation: dbe-checkout-rise 420ms var(--dbe-checkout-ease) both; animation-delay: calc(var(--i) * 60ms); }
  .dbe-checkout-meth > div:first-child { display: grid; line-height: 1.2; }
  .dbe-checkout-meth b { font-weight: 650; }
  .dbe-checkout-meth small { font-size: 11px; color: var(--dbe-checkout-muted); font-variant-numeric: tabular-nums; }
  .dbe-checkout-meth > output { text-align: right; font-weight: 700; font-variant-numeric: tabular-nums; }
  .dbe-checkout-mbars { display: grid; gap: 4px; }
  .dbe-checkout-mbars i { display: block; height: 9px; border-radius: 3px; background: var(--c); width: calc(var(--w) * 100%); transform-origin: left; animation: dbe-checkout-left 650ms var(--dbe-checkout-ease) both; animation-delay: calc(var(--i) * 60ms); }
  .dbe-checkout-declines { padding: 6px 16px 16px; display: grid; gap: 10px; }
  .dbe-checkout-declines li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 10px; font-size: 12.5px; animation: dbe-checkout-rise 420ms var(--dbe-checkout-ease) both; animation-delay: calc(var(--i) * 50ms); }
  .dbe-checkout-declines li span { color: var(--dbe-checkout-muted); font-variant-numeric: tabular-nums; }
  .dbe-checkout-declines li i { grid-column: 1 / -1; height: 6px; border-radius: 3px; background: linear-gradient(90deg, var(--dbe-checkout-bad) calc(var(--w) * 100%), var(--dbe-checkout-sunk) 0); }

