  const all = [...T.m, ...T.d, ...T.mr, ...T.dr];
  const mn = Math.min(...all), mxv = Math.max(...all), sc = nice(mxv - mn, 4);
  const lo = Math.max(0, Math.floor(mn / sc.step) * sc.step), hi = Math.ceil(mxv / sc.step) * sc.step;
  const X = i => L + (n === 1 ? 0 : i / (n - 1)) * pwi, Y = v => Tp + phi - (v - lo) / (hi - lo) * phi;
  const path = a => a.map((v, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ',' + Y(v).toFixed(1)).join('');
  let s = '';
  for (let v = lo; v <= hi + 1e-9; v += sc.step) s += `<line class="dbe-checkout-gl" x1="${L}" x2="${L + pwi}" y1="${Y(v).toFixed(1)}" y2="${Y(v).toFixed(1)}"/><text x="${L - 7}" y="${(Y(v) + 3.5).toFixed(1)}" text-anchor="end">${pct(v, 1)}</text>`;
  const every = Math.max(1, Math.round(n / 6));
  for (let i = 0; i < n; i += every) s += `<text x="${X(i).toFixed(1)}" y="${th - 6}" text-anchor="middle">${dLabel(T.d0 + i)}</text>`;
  /* event markers stack their labels so neighbours never collide */
  EVENTS.forEach(([d, label], k) => {
    const i = d - T.d0;
    if (i < 0 || i >= n) return;
    const right = X(i) > L + pwi - 150;
    s += `<g class="dbe-checkout-ev"><line x1="${X(i).toFixed(1)}" x2="${X(i).toFixed(1)}" y1="${Tp - 8}" y2="${Tp + phi}"/><text x="${(X(i) + (right ? -5 : 5)).toFixed(1)}" y="${(Tp - 10 + k * 14).toFixed(1)}" text-anchor="${right ? 'end' : 'start'}">${label}</text></g>`;
  });
  if (T.win > 1) s += `<path class="dbe-checkout-raw" style="stroke:var(--dbe-checkout-mob)" d="${path(T.mr)}"/><path class="dbe-checkout-raw" style="stroke:var(--dbe-checkout-desk)" d="${path(T.dr)}"/>`;
  s += `<path class="dbe-checkout-td" pathLength="1" d="${path(T.d)}"/><path class="dbe-checkout-tm" pathLength="1" d="${path(T.m)}"/>`;
  s += `<g class="dbe-checkout-xh" visibility="hidden"><line y1="${Tp}" y2="${Tp + phi}"/><circle r="4" style="fill:var(--dbe-checkout-mob)"/><circle r="4" style="fill:var(--dbe-checkout-desk)"/></g>`;
  tsvg.setAttribute('viewBox', `0 0 ${tw} ${th}`);
  tsvg.innerHTML = s;
  tsvg.classList.toggle('is-enter', !!enter && !calm());
