}
tsvg.addEventListener('pointermove', e => {
  if (!T) return;
  const r = tsvg.getBoundingClientRect(), i = clamp(Math.round((e.clientX - r.left - T.L) / T.pw * (T.n - 1)), 0, T.n - 1);
  const g = $('.dbe-checkout-xh', tsvg), x = T.X(i);
  g.setAttribute('visibility', 'visible');
  $('line', g).setAttribute('x1', x); $('line', g).setAttribute('x2', x);
  const cs = $$('circle', g);
  cs[0].setAttribute('cx', x); cs[0].setAttribute('cy', T.Y(T.m[i]));
  cs[1].setAttribute('cx', x); cs[1].setAttribute('cy', T.Y(T.d[i]));
  const ev = EVENTS.find(([d]) => d === T.d0 + i);
  ttip.innerHTML = `<b>${dLabel(T.d0 + i)}${ev ? ' · ' + ev[1] : ''}</b>` +
    `<p><span>Mobile${T.win > 1 ? ', 7-day' : ''}</span><em style="color:var(--dbe-checkout-mob)">${pct(T.m[i], 2)}</em></p><p><span>Desktop${T.win > 1 ? ', 7-day' : ''}</span><em style="color:var(--dbe-checkout-desk)">${pct(T.d[i], 2)}</em></p>` +
    (T.win > 1 ? `<p><span>That day</span><em>${pct(T.mr[i], 1)} · ${pct(T.dr[i], 1)}</em></p>` : '');
  placeTip(ttip, tplot, x, Math.min(T.Y(T.m[i]), T.Y(T.d[i])));
});
tsvg.addEventListener('pointerleave', () => { ttip.hidden = true; const g = $('.dbe-checkout-xh', tsvg); if (g) g.setAttribute('visibility', 'hidden'); });

/* ---------- payments ---------- */
function renderPay() {
  const orders = { m: F.m[5], d: F.d[5] };
  const rows = DEVS.map(dv => apportion(orders[dv], METHODS.map(x => x.mix[dv])));
  let attempts = 0, okTot = 0;
  const data = METHODS.map((x, i) => {
    const om = rows[0][i], od = rows[1][i], am = Math.round(om / x.ok.m), ad = Math.round(od / x.ok.d);
    attempts += am + ad; okTot += om + od;
    return { x, om, od, att: am + ad };
  });
  const mx = Math.max(...data.map(r => Math.max(r.om / orders.m, r.od / orders.d)));
  $('.dbe-checkout-methods').innerHTML = data.map((r, i) => `<div class="dbe-checkout-meth" style="--i:${i}"><div><b>${r.x.n}</b><small>${nf0.format(r.om + r.od)} orders · avg $${r.x.aov}</small></div>` +
    `<div class="dbe-checkout-mbars"><i style="--c:var(--dbe-checkout-mob);--w:${(r.om / orders.m / mx).toFixed(3)}" title="Mobile: ${pct(r.om / orders.m)} of orders"></i><i style="--c:var(--dbe-checkout-desk);--w:${(r.od / orders.d / mx).toFixed(3)}" title="Desktop: ${pct(r.od / orders.d)} of orders"></i></div>` +
    `<output title="Successful attempts">${pct((r.om + r.od) / r.att)}</output></div>`).join('');
  $('[data-f="paysub"]').textContent = `${nf0.format(okTot)} orders from ${nf0.format(attempts)} attempts. Bars are each method's share of mobile and desktop orders; right, its success rate.`;
  /* the same numbers by device, so every bar above can be read exactly */
  const att = (o, k) => Math.round(o / k);
  let sm = 0, sd = 0, am = 0, ad = 0;
  $('.dbe-checkout-xtable tbody').innerHTML = data.map(r => {
    const xm = att(r.om, r.x.ok.m), xd = att(r.od, r.x.ok.d);
    sm += r.om; sd += r.od; am += xm; ad += xd;
    const okm = r.om / xm, okd = r.od / xd;
    return `<tr><td>${r.x.n}</td><td>${nf0.format(r.om)} <small style="color:var(--dbe-checkout-muted)">${pct(r.om / orders.m, 0)}</small></td><td class="${okm < 0.85 ? 'is-low' : ''}">${pct(okm)}</td>` +
      `<td>${nf0.format(r.od)} <small style="color:var(--dbe-checkout-muted)">${pct(r.od / orders.d, 0)}</small></td><td class="${okd < 0.85 ? 'is-low' : ''}">${pct(okd)}</td><td>$${r.x.aov}</td></tr>`;
  }).join('');
  const aovAll = data.reduce((a, r) => a + (r.om + r.od) * r.x.aov, 0) / okTot;
  $('.dbe-checkout-xtable tfoot').innerHTML = `<tr><td>All methods</td><td>${nf0.format(sm)}</td><td>${pct(sm / am)}</td><td>${nf0.format(sd)}</td><td>${pct(sd / ad)}</td><td>$${aovAll.toFixed(2)}</td></tr>`;
  const failed = attempts - okTot, dc = apportion(failed, DECLINE.map(d => d[1])), dm = Math.max(...dc);
  $('.dbe-checkout-declines').innerHTML = DECLINE.map((d, i) => `<li style="--i:${i};--w:${(dc[i] / dm).toFixed(3)}"><b>${d[0]}</b><span>${nf0.format(dc[i])} · ${pct(dc[i] / failed, 0)}</span><i></i></li>`).join('');
  $('[data-f="declsub"]').textContent = `${nf0.format(failed)} failed attempts; most shoppers retry, so these overlap with the orders above.`;
}

/* ---------- headline + controls ---------- */
function renderHead() {
  const cm = F.m[5] / F.m[0], cd = F.d[5] / F.d[0], k = bestGap();
  $('[data-f="mconv"]').textContent = pct(cm);
  $('[data-f="dconv"]').textContent = pct(cd);
  $('[data-f="headline"]').innerHTML = `<span class="m">${pct(cm)}</span> of mobile carts become orders against <span class="d">${pct(cd)}</span> on desktop. The widest gap opens at ${STEPS[k].toLowerCase()}.`;
}
function refresh(enter) {
  aggregate();
  if (st.sel == null) st.sel = bestGap();
  renderHead();
  if (st.view === 'funnel') { drawFunnel(enter); renderWhy(); }
  if (st.view === 'trend') drawTrend(enter);
  if (st.view === 'pay') renderPay();
}
