root.addEventListener('keydown', e => { if (e.key === 'Escape' && st.view === 'funnel' && st.sel !== 0) pick(0, false); });

aggregate();
st.sel = bestGap();
renderHead();
renderWhy();
later(() => drawFunnel(true));
